// 英語（高校受験）1〜100問。questions.js の後、script.js の前に読み込みます。
"use strict";
QUESTIONS.push(...[
  { label: "【英語・高校受験】", q: "「attend」の意味は？", choices: ["〜を借りる", "〜を貸す", "〜に出席する"], answer: 2, explain: "She attended the meeting.（彼女は会議に出席した）。名詞は attendance（出席）" },
  { label: "【英語・高校受験】", q: "「〜を発見する」を表す英単語は？", choices: ["describe", "deliver", "discover"], answer: 2, explain: "Scientists discovered a new star.（科学者たちは新しい星を発見した）。名詞は discovery" },
  { label: "【英語・高校受験】", q: "「however」の意味は？", choices: ["それゆえに", "しかしながら", "そのうえ"], answer: 1, explain: "I like tennis. However, I'm not good at it.（テニスは好きだ。しかし、得意ではない）" },
  { label: "【英語・高校受験】", q: "「although」の意味は？", choices: ["〜なので", "〜のあとで", "〜だけれども"], answer: 2, explain: "Although it was raining, we went out.（雨が降っていたが、私たちは出かけた）" },
  { label: "【英語・高校受験】", q: "「improve」の意味は？", choices: ["〜を想像する", "〜を証明する", "〜を改善する、上達させる"], answer: 2, explain: "I want to improve my English.（英語を上達させたい）" },
  { label: "【英語・高校受験】", q: "「〜を借りる」を表す英単語は？", choices: ["lend", "lose", "borrow"], answer: 2, explain: "May I borrow your pen?（ペンを借りてもいいですか）。lend は「貸す」" },
  { label: "【英語・高校受験】", q: "「lend」の意味は？", choices: ["〜を貸す", "〜を借りる", "〜を失う"], answer: 0, explain: "Can you lend me some money?（お金を少し貸してくれませんか）" },
  { label: "【英語・高校受験】", q: "I can't ( ) which shirt to buy. 空所に入る語は？", choices: ["divide", "describe", "decide"], answer: 2, explain: "I can't decide which shirt to buy.（どのシャツを買うか決められない）" },
  { label: "【英語・高校受験】", q: "「invite」の意味は？", choices: ["〜を発明する", "〜を調査する", "〜を招待する"], answer: 2, explain: "She invited me to her birthday party.（彼女は私を誕生日パーティーに招待した）" },
  { label: "【英語・高校受験】", q: "「〜を説明する」を表す英単語は？", choices: ["explore", "explain", "express"], answer: 1, explain: "Could you explain the rule?（そのルールを説明してもらえますか）。explore は「探検する」、express は「表現する」" },
  { label: "【英語・高校受験】", q: "「describe」の意味は？", choices: ["〜を禁止する", "〜を配達する", "〜の特徴を述べる、描写する"], answer: 2, explain: "Can you describe the man?（その男性の特徴を話してもらえますか）" },
  { label: "【英語・高校受験】", q: "「〜を受け取る」を表す英単語は？", choices: ["reserve", "receive", "remove"], answer: 1, explain: "I received a letter from her.（彼女から手紙を受け取った）" },
  { label: "【英語・高校受験】", q: "「〜を提供する」を表す英単語は？", choices: ["provide", "protect", "produce"], answer: 0, explain: "The school provides free lunch.（その学校は無料の昼食を提供している）" },
  { label: "【英語・高校受験】", q: "「〜の準備をする」を表す英単語は？", choices: ["repair", "compare", "prepare"], answer: 2, explain: "I'm preparing for the exam.（試験の準備をしている）" },
  { label: "【英語・高校受験】", q: "「choose」の意味は？", choices: ["〜を選ぶ", "〜を追いかける", "〜を開く"], answer: 0, explain: "活用は choose - chose - chosen。Choose one of these.（このうち1つを選んで）" },
  { label: "【英語・高校受験】", q: "「expect」の意味は？", choices: ["〜を輸出する", "〜を説明する", "〜を予期する、期待する"], answer: 2, explain: "I expect him to come soon.（彼がもうすぐ来ると思う）" },
  { label: "【英語・高校受験】", q: "「depend on 〜」の意味は？", choices: ["〜に反対する", "〜に頼る、〜しだいである", "〜を訪ねる"], answer: 1, explain: "It depends on the weather.（天気しだいだ）" },
  { label: "【英語・高校受験】", q: "「〜を発達させる、開発する」を表す英単語は？", choices: ["develop", "devote", "deliver"], answer: 0, explain: "They developed a new app.（彼らは新しいアプリを開発した）。名詞は development" },
  { label: "【英語・高校受験】", q: "「〜を生産する」を表す英単語は？", choices: ["promise", "produce", "prohibit"], answer: 1, explain: "This factory produces cars.（この工場は車を生産している）" },
  { label: "【英語・高校受験】", q: "Seat belts ( ) us in car accidents. 空所に入る語は？", choices: ["predict", "pretend", "protect"], answer: 2, explain: "protect A from B で「AをBから守る」。（シートベルトは車の事故で私たちを守る）" },
  { label: "【英語・高校受験】", q: "「survive」の意味は？", choices: ["観察する", "接触する", "生き残る"], answer: 2, explain: "Only one man survived the accident.（その事故で生き残ったのは1人だけだった）" },
  { label: "【英語・高校受験】", q: "「imagine」の意味は？", choices: ["〜を想像する", "〜を模倣する", "〜を輸入する"], answer: 0, explain: "Imagine a world without music.（音楽のない世界を想像してみて）" },
  { label: "【英語・高校受験】", q: "「realize」の意味は？", choices: ["〜を記録する", "〜に気づく", "〜を軽くする"], answer: 1, explain: "I realized I had left my bag.（かばんを置き忘れたと気づいた）" },
  { label: "【英語・高校受験】", q: "「〜を提案する」を表す英単語は？", choices: ["suggest", "suffer", "support"], answer: 0, explain: "I suggest going by train.（電車で行くことを提案する）" },
  { label: "【英語・高校受験】", q: "「allow」の意味は？", choices: ["〜を許す、許可する", "〜を警告する", "〜を並べる"], answer: 0, explain: "My parents don't allow me to stay out late.（両親は私が夜遅くまで外出するのを許さない）" },
  { label: "【英語・高校受験】", q: "「約束（する）」を表す英単語は？", choices: ["produce", "promise", "propose"], answer: 1, explain: "He promised to help me.（彼は私を手伝うと約束した）" },
  { label: "【英語・高校受験】", q: "「refuse」の意味は？", choices: ["〜を補充する", "〜を断る、拒否する", "〜を再利用する"], answer: 1, explain: "She refused my offer.（彼女は私の申し出を断った）" },
  { label: "【英語・高校受験】", q: "「suffer」の意味は？", choices: ["〜を救う", "〜を満足させる", "苦しむ、（病気などに）かかる"], answer: 2, explain: "He suffers from a cold.（彼は風邪で苦しんでいる）。suffer from 〜 の形でよく使う" },
  { label: "【英語・高校受験】", q: "「環境」を表す英単語は？", choices: ["entertainment", "equipment", "environment"], answer: 2, explain: "We should protect the environment.（私たちは環境を守るべきだ）" },
  { label: "【英語・高校受験】", q: "「culture」の意味は？", choices: ["文化", "農業", "文学"], answer: 0, explain: "Japanese culture is unique.（日本の文化は独特だ）" },
  { label: "【英語・高校受験】", q: "「custom」の意味は？", choices: ["衣装", "税関", "（社会の）習慣、風習"], answer: 2, explain: "It's a custom to take off your shoes in Japan.（日本では靴を脱ぐのが習慣だ）。customs は「税関」の意味になる" },
  { label: "【英語・高校受験】", q: "「tradition」の意味は？", choices: ["取引", "交通", "伝統"], answer: 2, explain: "This festival is an old tradition.（この祭りは古い伝統だ）" },
  { label: "【英語・高校受験】", q: "「century」の意味は？", choices: ["世紀", "中心", "証明書"], answer: 0, explain: "the twenty-first century（21世紀）" },
  { label: "【英語・高校受験】", q: "「人口」を表す英単語は？", choices: ["popularity", "pollution", "population"], answer: 2, explain: "The population of Tokyo is about 14 million.（東京の人口は約1400万人だ）" },
  { label: "【英語・高校受験】", q: "「education」の意味は？", choices: ["教育", "説明", "教室"], answer: 0, explain: "She received a good education.（彼女は良い教育を受けた）" },
  { label: "【英語・高校受験】", q: "「experience」の意味は？", choices: ["実験", "専門家", "経験（する）"], answer: 2, explain: "It was a great experience.（すばらしい経験だった）。experiment が「実験」" },
  { label: "【英語・高校受験】", q: "「機会、好機」を表す英単語は？", choices: ["opposition", "opportunity", "optimism"], answer: 1, explain: "I had an opportunity to meet him.（彼に会う機会があった）" },
  { label: "【英語・高校受験】", q: "「違い」を表す英単語は？", choices: ["distance", "difference", "discipline"], answer: 1, explain: "What's the difference between A and B?（AとBの違いは何ですか）" },
  { label: "【英語・高校受験】", q: "「society」の意味は？", choices: ["社会", "安全", "孤独"], answer: 0, explain: "We live in a modern society.（私たちは現代社会に生きている）" },
  { label: "【英語・高校受験】", q: "「government」の意味は？", choices: ["知事", "政党", "政府"], answer: 2, explain: "The government will build a new bridge.（政府は新しい橋を建設する予定だ）" },
  { label: "【英語・高校受験】", q: "「language」の意味は？", choices: ["言語", "論理", "文学"], answer: 0, explain: "English is a global language.（英語は世界的な言語だ）" },
  { label: "【英語・高校受験】", q: "「目的地」を表す英単語は？", choices: ["destination", "decision", "distribution"], answer: 0, explain: "We reached our destination at noon.（私たちは正午に目的地に着いた）" },
  { label: "【英語・高校受験】", q: "「festival」の意味は？", choices: ["宴会", "祭り", "断食"], answer: 1, explain: "a music festival（音楽祭）" },
  { label: "【英語・高校受験】", q: "「隣人」を表す英単語は？", choices: ["relative", "neighbor", "stranger"], answer: 1, explain: "My neighbor has a big dog.（隣人は大きな犬を飼っている）" },
  { label: "【英語・高校受験】", q: "「ability」の意味は？", choices: ["責任", "能力", "安定"], answer: 1, explain: "She has the ability to speak three languages.（彼女は3か国語を話す能力がある）" },
  { label: "【英語・高校受験】", q: "「冒険」を表す英単語は？", choices: ["advertisement", "adventure", "advantage"], answer: 1, explain: "an exciting adventure（わくわくする冒険）" },
  { label: "【英語・高校受験】", q: "「advice」の意味は？", choices: ["広告", "助言", "事故"], answer: 1, explain: "Thank you for your advice.（助言をありがとう）。数えられない名詞で、an advice とは言わない" },
  { label: "【英語・高校受験】", q: "「article」の意味は？", choices: ["芸術", "結論", "記事、品物"], answer: 2, explain: "I read an article about space.（宇宙についての記事を読んだ）" },
  { label: "【英語・高校受験】", q: "「観客、聴衆」を表す英単語は？", choices: ["author", "audio", "audience"], answer: 2, explain: "The audience clapped loudly.（観客は大きな拍手をした）" },
  { label: "【英語・高校受験】", q: "「climate」の意味は？", choices: ["気温", "天気予報", "気候"], answer: 2, explain: "a warm climate（温暖な気候）。weather は「その日の天気」" },
  { label: "【英語・高校受験】", q: "「海岸」を表す英単語は？", choices: ["coast", "cost", "coach"], answer: 0, explain: "We drove along the coast.（私たちは海岸沿いを車で走った）" },
  { label: "【英語・高校受験】", q: "「勇気」を表す英単語は？", choices: ["course", "courage", "courtesy"], answer: 1, explain: "It takes courage to say sorry.（謝るには勇気がいる）" },
  { label: "【英語・高校受験】", q: "「danger」の意味は？", choices: ["危険", "怒り", "見知らぬ人"], answer: 0, explain: "The tourists were in danger.（旅行者たちは危険な状態にあった）。anger は「怒り」、stranger は「見知らぬ人」" },
  { label: "【英語・高校受験】", q: "「diary」の意味は？", choices: ["辞書", "酪農", "日記"], answer: 2, explain: "I keep a diary every day.（毎日日記をつけている）。dairy は「酪農」" },
  { label: "【英語・高校受験】", q: "「災害」を表す英単語は？", choices: ["disaster", "disappointment", "distance"], answer: 0, explain: "a natural disaster（自然災害）" },
  { label: "【英語・高校受験】", q: "「journey」の意味は？", choices: ["新聞", "（長い）旅", "職業"], answer: 1, explain: "a long journey（長い旅）。trip より、少し長めで大きな移動のイメージ" },
  { label: "【英語・高校受験】", q: "「fashion」の意味は？", choices: ["工場", "流行、ファッション", "繊維"], answer: 1, explain: "She follows fashion.（彼女は流行を追っている）" },
  { label: "【英語・高校受験】", q: "「fortune」の意味は？", choices: ["要塞", "未来", "運、財産"], answer: 2, explain: "He made a fortune.（彼は財産を築いた）" },
  { label: "【英語・高校受験】", q: "「habit」の意味は？", choices: ["生息地", "（個人の）習慣、くせ", "趣味"], answer: 1, explain: "Smoking is a bad habit.（喫煙は悪い習慣だ）" },
  { label: "【英語・高校受験】", q: "He is so ( ) that he always tells the truth. 空所に入る語は？", choices: ["honor", "honest", "hungry"], answer: 1, explain: "honest は h を発音しない。（彼はとても正直で、いつも本当のことを言う）" },
  { label: "【英語・高校受験】", q: "「modern」の意味は？", choices: ["現代の、近代的な", "控えめな", "古代の"], answer: 0, explain: "a modern building（近代的な建物）" },
  { label: "【英語・高校受験】", q: "「礼儀正しい」を表す英単語は？", choices: ["political", "polite", "polluted"], answer: 1, explain: "Be polite to older people.（年上の人には礼儀正しくしなさい）" },
  { label: "【英語・高校受験】", q: "This singer is ( ) among young people. 空所に入る語は？", choices: ["popular", "population", "pollution"], answer: 0, explain: "be popular among 〜 で「〜のあいだで人気がある」" },
  { label: "【英語・高校受験】", q: "It is ( ) for you to wear a helmet. 空所に入る語は？", choices: ["necessity", "necessary", "nervous"], answer: 1, explain: "It is necessary for A to 〜 で「Aが〜することは必要だ」。necessity は名詞（必要性）" },
  { label: "【英語・高校受験】", q: "「successful」の意味は？", choices: ["成功した", "連続した", "十分な"], answer: 0, explain: "She is a successful writer.（彼女は成功した作家だ）。名詞は success、動詞は succeed" },
  { label: "【英語・高校受験】", q: "This chair is very ( ). I can sit for hours. 空所に入る語は？", choices: ["convenient", "comparable", "comfortable"], answer: 2, explain: "comfortable は「（体に）心地よい」。convenient は「（都合がよくて）便利な」" },
  { label: "【英語・高校受験】", q: "The new station is very ( ) for shopping. 空所に入る語は？", choices: ["comfortable", "convenient", "conventional"], answer: 1, explain: "a convenient location（便利な場所）。convenient は「都合がよい」" },
  { label: "【英語・高校受験】", q: "「familiar」の意味は？", choices: ["家族の", "よく知られた、なじみのある", "有名な"], answer: 1, explain: "This song sounds familiar.（この曲は聞き覚えがある）。be familiar with 〜 で「〜をよく知っている」" },
  { label: "【英語・高校受験】", q: "「foreign」の意味は？", choices: ["外国の", "森の", "正式の"], answer: 0, explain: "a foreign language（外国語）" },
  { label: "【英語・高校受験】", q: "「いくつかの」を表す英単語は？", choices: ["severe", "separate", "several"], answer: 2, explain: "I waited for several hours.（数時間待った）" },
  { label: "【英語・高校受験】", q: "「various」の意味は？", choices: ["さまざまな", "明らかな", "重要な"], answer: 0, explain: "various kinds of food（さまざまな種類の食べ物）。名詞は variety" },
  { label: "【英語・高校受験】", q: "Her illness is ( ). She must go to the hospital. 空所に入る語は？", choices: ["series", "several", "serious"], answer: 2, explain: "serious は「重大な、深刻な」。（彼女の病気は深刻で、病院へ行かなければならない）" },
  { label: "【英語・高校受験】", q: "「certain」の意味は？", choices: ["注意深い", "明らかな", "確かな、ある〜"], answer: 2, explain: "I'm certain he will come.（彼は必ず来ると確信している）。a certain person は「ある人」" },
  { label: "【英語・高校受験】", q: "「特に」を表す英単語は？", choices: ["exactly", "especially", "extremely"], answer: 1, explain: "I like fruit, especially apples.（果物が好きで、特にりんごが好きだ）" },
  { label: "【英語・高校受験】", q: "「actually」の意味は？", choices: ["最近", "実は、実際に", "ついに"], answer: 1, explain: "Actually, I've never been there.（実は、そこに行ったことがない）" },
  { label: "【英語・高校受験】", q: "「突然」を表す英単語は？", choices: ["suddenly", "slowly", "silently"], answer: 0, explain: "Suddenly, the lights went out.（突然、明かりが消えた）" },
  { label: "【英語・高校受験】", q: "「recently」の意味は？", choices: ["すぐに", "最近", "めったに〜ない"], answer: 1, explain: "I haven't seen him recently.（最近彼に会っていない）" },
  { label: "【英語・高校受験】", q: "「ほとんど、もう少しで」を表す英単語は？", choices: ["clearly", "nearby", "nearly"], answer: 2, explain: "It's nearly ten o'clock.（もうすぐ10時だ）" },
  { label: "【英語・高校受験】", q: "「instead」の意味は？", choices: ["内側に", "ただちに", "代わりに"], answer: 2, explain: "I don't want coffee. I'll have tea instead.（コーヒーはいらない。代わりに紅茶にする）" },
  { label: "【英語・高校受験】", q: "「I don't live here anymore.」の anymore の意味は？", choices: ["もはや〜ない", "いつでも", "ふたたび"], answer: 0, explain: "否定文で使い、「もう（ここには）住んでいない」の意味になる" },
  { label: "【英語・高校受験】", q: "「throughout」の意味は？", choices: ["〜の向こうに", "〜のあいだじゅう、〜の至るところに", "〜の代わりに"], answer: 1, explain: "It rained throughout the day.（一日中雨が降っていた）" },
  { label: "【英語・高校受験】", q: "「among」の意味は？", choices: ["（2つ）のあいだに", "（3つ以上）のなかで", "〜に対して"], answer: 1, explain: "Among the five students, she is the tallest.（5人のなかで、彼女がいちばん背が高い）。2つのあいだは between" },
  { label: "【英語・高校受験】", q: "I visited my uncle ( ) the summer vacation. 空所に入る語は？", choices: ["during", "while", "since"], answer: 0, explain: "during の後ろは名詞（期間）。while の後ろは「主語＋動詞」" },
  { label: "【英語・高校受験】", q: "You can't get in ( ) you have a ticket. 空所に入る語は？", choices: ["unless", "until", "although"], answer: 0, explain: "unless は「〜でない限り」。（チケットがない限り、入れない）" },
  { label: "【英語・高校受験】", q: "I don't know ( ) he will come or not. 空所に入る語は？", choices: ["whether", "weather", "whenever"], answer: 0, explain: "whether は「〜かどうか」。weather は「天気」で、発音は同じ" },
  { label: "【英語・高校受験】", q: "「either A or B」の意味は？", choices: ["AもBも", "AでもBでもない", "AかBのどちらか"], answer: 2, explain: "You can have either tea or coffee.（紅茶かコーヒーのどちらかが飲めます）" },
  { label: "【英語・高校受験】", q: "「neither」の意味は？", choices: ["どちらか", "どちらも〜ない", "どちらも"], answer: 1, explain: "Neither of them came.（彼らのどちらも来なかった）" },
  { label: "【英語・高校受験】", q: "「whenever」の意味は？", choices: ["〜のあいだ", "〜する前に", "〜するときはいつでも"], answer: 2, explain: "Call me whenever you need help.（助けが必要なときはいつでも電話して）" },
  { label: "【英語・高校受験】", q: "「vegetable」の意味は？", choices: ["果物", "野菜", "植物"], answer: 1, explain: "Eat more vegetables.（もっと野菜を食べなさい）" },
  { label: "【英語・高校受験】", q: "「luggage」の意味は？", choices: ["（旅行の）手荷物", "言語", "小包"], answer: 0, explain: "I lost my luggage.（手荷物をなくした）。数えられない名詞で、two pieces of luggage のように数える" },
  { label: "【英語・高校受験】", q: "「薬」を表す英単語は？", choices: ["medicine", "medium", "medal"], answer: 0, explain: "Take this medicine twice a day.（この薬を1日2回飲みなさい）" },
  { label: "【英語・高校受験】", q: "「けが」を表す英単語は？", choices: ["justice", "industry", "injury"], answer: 2, explain: "He had a serious injury.（彼は重傷を負った）" },
  { label: "【英語・高校受験】", q: "「scene」の意味は？", choices: ["場面、光景", "科学", "季節"], answer: 0, explain: "the last scene of the movie（映画の最後の場面）" },
  { label: "【英語・高校受験】", q: "「要求（する）、頼みごと」を表す英単語は？", choices: ["request", "respect", "rescue"], answer: 0, explain: "He made a request.（彼は頼みごとをした）" },
  { label: "【英語・高校受験】", q: "「tourist」の意味は？", choices: ["観光客", "地元の人", "運転手"], answer: 0, explain: "Many tourists visit Kyoto.（多くの観光客が京都を訪れる）" },
  { label: "【英語・高校受験】", q: "「shortage」の意味は？", choices: ["不足", "短所", "短縮"], answer: 0, explain: "a water shortage（水不足）" },
  { label: "【英語・高校受験】", q: "「ancient」の意味は？", choices: ["正確な", "古代の", "年に1度の"], answer: 1, explain: "ancient Rome（古代ローマ）" },
  { label: "【英語・高校受験】", q: "「achieve」の意味は？", choices: ["〜を達成する", "〜に到着する", "〜を調整する"], answer: 0, explain: "She achieved her goal.（彼女は目標を達成した）。名詞は achievement" },
  { label: "【英語・高校受験】", q: "「remain」の意味は？", choices: ["〜を思い出す", "〜を取り除く", "〜のままである、残る"], answer: 2, explain: "Please remain seated.（座ったままでいてください）" },
  { label: "【英語・高校受験】", q: "「gather」の意味は？", choices: ["〜を分ける", "〜を集める、集まる", "〜を育てる"], answer: 1, explain: "Students gathered in the hall.（生徒たちがホールに集まった）" },

// ===== 英語（高校受験）101〜200問 =====
  { label: "【英語・高校受験】", q: "「for example」の意味は？", choices: ["その結果", "例えば", "つまり"], answer: 1, explain: "I like sports, for example, tennis and soccer.（私はスポーツが好きで、例えばテニスやサッカーが好きだ）" },
  { label: "【英語・高校受験】", q: "「as well as 〜」の意味は？", choices: ["〜の代わりに", "〜だけでなく…も", "〜のあとで"], answer: 1, explain: "She speaks English as well as French.（彼女はフランス語だけでなく英語も話す）" },
  { label: "【英語・高校受験】", q: "「in front of 〜」の意味は？", choices: ["〜の後ろに", "〜の前に（場所）", "〜の中に"], answer: 1, explain: "There is a bus stop in front of the school.（学校の前にバス停がある）。時間の「前に」は before" },
  { label: "【英語・高校受験】", q: "「look forward to 〜ing」の意味は？", choices: ["〜を楽しみに待つ", "〜を探す", "〜を見守る"], answer: 0, explain: "I'm looking forward to seeing you.（あなたに会えるのを楽しみにしている）。to の後ろは動名詞（〜ing）" },
  { label: "【英語・高校受験】", q: "「〜の世話をする」を表す英語は？", choices: ["take part in", "take off", "take care of"], answer: 2, explain: "She takes care of her little brother.（彼女は弟の世話をする）。look after とほぼ同じ意味" },
  { label: "【英語・高校受験】", q: "「be good at 〜」の意味は？", choices: ["〜が好きだ", "〜が得意だ", "〜に飽きている"], answer: 1, explain: "He is good at math.（彼は数学が得意だ）。反対は be poor at 〜" },
  { label: "【英語・高校受験】", q: "I ( ) play tennis when I was a child. 空所に入る語（句）は？", choices: ["use to", "am used to", "used to"], answer: 2, explain: "used to 〜 は「以前は〜したものだ」。be used to 〜ing は「〜に慣れている」" },
  { label: "【英語・高校受験】", q: "「たくさんの」を表す英語は？", choices: ["a little", "a few", "a lot of"], answer: 2, explain: "We have a lot of rain in June.（6月は雨がたくさん降る）。肯定文でよく使う" },
  { label: "【英語・高校受験】", q: "「at least」の意味は？", choices: ["せいぜい", "少なくとも", "とうとう"], answer: 1, explain: "You should sleep at least seven hours.（少なくとも7時間は眠るべきだ）。「せいぜい」は at most" },
  { label: "【英語・高校受験】", q: "「by the way」の意味は？", choices: ["とにかく", "ところで", "そのうえ"], answer: 1, explain: "By the way, what time is it?（ところで、今何時ですか）。話題を変えるときに使う" },
  { label: "【英語・高校受験】", q: "Let's go to the sea ( ) the mountains. 空所に入る語（句）は？", choices: ["because of", "as well as", "instead of"], answer: 2, explain: "instead of 〜 は「〜の代わりに」。（山の代わりに海へ行こう）" },
  { label: "【英語・高校受験】", q: "「in fact」の意味は？", choices: ["実は、実際に", "例えば", "結局"], answer: 0, explain: "He looks young, but in fact he is fifty.（彼は若く見えるが、実は50歳だ）" },
  { label: "【英語・高校受験】", q: "「of course」の意味は？", choices: ["もちろん", "とうとう", "たぶん"], answer: 0, explain: "Of course, you can use my pen.（もちろん、私のペンを使っていいよ）" },
  { label: "【英語・高校受験】", q: "「〜のために（原因・理由）」を表す英語は？", choices: ["because", "because of", "although"], answer: 1, explain: "We stayed home because of the rain.（雨のために私たちは家にいた）。because の後ろは「主語＋動詞」、because of の後ろは名詞" },
  { label: "【英語・高校受験】", q: "「as soon as 〜」の意味は？", choices: ["〜するとすぐに", "〜するかぎり", "〜するまで"], answer: 0, explain: "Call me as soon as you arrive.（着いたらすぐに電話して）" },
  { label: "【英語・高校受験】", q: "「あきらめる」を表す英語は？", choices: ["give in", "give up", "give out"], answer: 1, explain: "Don't give up!（あきらめないで）。give up 〜ing で「〜することをあきらめる」" },
  { label: "【英語・高校受験】", q: "「look for 〜」の意味は？", choices: ["〜を見る", "〜を見守る", "〜を探す"], answer: 2, explain: "I'm looking for my key.（鍵を探している）。look at 〜 は「〜を見る」" },
  { label: "【英語・高校受験】", q: "「〜に参加する」を表す英語は？", choices: ["take part in", "take care of", "take place in"], answer: 0, explain: "Many students took part in the festival.（多くの生徒が祭りに参加した）。participate in と同じ意味" },
  { label: "【英語・高校受験】", q: "「get along with 〜」の意味は？", choices: ["〜と仲良くやっていく", "〜と別れる", "〜に追いつく"], answer: 0, explain: "I get along with my classmates.（私はクラスメートと仲良くやっている）" },
  { label: "【英語・高校受験】", q: "We have ( ) milk. Let's buy some more. 空所に入る語（句）は？", choices: ["run into", "run out of", "run away"], answer: 1, explain: "run out of 〜 は「〜を使い果たす」。（牛乳を切らした。もっと買おう）" },
  { label: "【英語・高校受験】", q: "「come up with 〜」の意味は？", choices: ["〜を思いつく", "〜に追いつく", "〜を訪ねる"], answer: 0, explain: "She came up with a good idea.（彼女はいい考えを思いついた）" },
  { label: "【英語・高校受験】", q: "「make sure」の意味は？", choices: ["〜を作り直す", "確かめる、確実にする", "〜を安全にする"], answer: 1, explain: "Make sure the door is locked.（ドアに鍵がかかっているか確かめて）" },
  { label: "【英語・高校受験】", q: "「〜を消す」を表す英語は？", choices: ["turn on", "turn up", "turn off"], answer: 2, explain: "Please turn off the TV.（テレビを消してください）。turn on は「〜をつける」" },
  { label: "【英語・高校受験】", q: "「put on 〜」の意味は？", choices: ["〜を身につける", "〜を脱ぐ", "〜をしまう"], answer: 0, explain: "Put on your coat. It's cold.（コートを着なさい。寒いよ）。put on は着る動作、wear は着ている状態" },
  { label: "【英語・高校受験】", q: "「pick up 〜」の意味は？", choices: ["〜を拾う、迎えに行く", "〜を置く", "〜を運ぶ"], answer: 0, explain: "I'll pick you up at the station.（駅へ迎えに行くよ）" },
  { label: "【英語・高校受験】", q: "「〜を調べて知る、見つけ出す」を表す英語は？", choices: ["look out", "find out", "work out"], answer: 1, explain: "I found out the truth.（私は真実を知った）。look for は「探す」、find out は「調べて知る」" },
  { label: "【英語・高校受験】", q: "「fall asleep」の意味は？", choices: ["目を覚ます", "夢を見る", "眠りに落ちる"], answer: 2, explain: "I fell asleep on the train.（私は電車で眠ってしまった）" },
  { label: "【英語・高校受験】", q: "The train left ( ) time, exactly at nine. 空所に入る語（句）は？", choices: ["on", "in", "at"], answer: 0, explain: "on time は「時間どおりに」。in time は「間に合って」" },
  { label: "【英語・高校受験】", q: "I got to the airport just ( ) time for my flight. 空所に入る語（句）は？", choices: ["on", "at", "in"], answer: 2, explain: "in time (for 〜) は「〜に間に合って」" },
  { label: "【英語・高校受験】", q: "「so far」の意味は？", choices: ["とても遠くに", "今までのところ", "もうすぐ"], answer: 1, explain: "So far, I haven't had any problems.（今までのところ、問題はない）。現在完了形とよく使う" },
  { label: "【英語・高校受験】", q: "Kyoto is ( ) its old temples. 空所に入る語（句）は？", choices: ["famous as", "famous of", "famous for"], answer: 2, explain: "be famous for 〜 は「〜で有名だ」。be famous as 〜 は「〜として有名だ」" },
  { label: "【英語・高校受験】", q: "「be afraid of 〜」の意味は？", choices: ["〜を恐れる", "〜を恥じる", "〜に飽きる"], answer: 0, explain: "She is afraid of dogs.（彼女は犬が怖い）" },
  { label: "【英語・高校受験】", q: "「〜に興味がある」を表す英語は？", choices: ["be interested in", "be surprised at", "be tired of"], answer: 0, explain: "I'm interested in history.（私は歴史に興味がある）。be surprised at 〜 は「〜に驚く」、be tired of 〜 は「〜にうんざりしている」" },
  { label: "【英語・高校受験】", q: "「would like to 〜」の意味は？", choices: ["〜するべきだ", "〜したことがある", "〜したい（ていねいな言い方）"], answer: 2, explain: "I would like to ask a question.（質問したいのですが）。want to 〜 よりていねい" },
  { label: "【英語・高校受験】", q: "She can speak ( ) English but also French. 空所に入る語（句）は？", choices: ["both", "either", "not only"], answer: 2, explain: "not only A but also B で「AだけでなくBも」" },
  { label: "【英語・高校受験】", q: "「too 〜 to …」の意味は？", choices: ["〜するのに十分…だ", "〜すぎて…できない", "とても〜なので…だ"], answer: 1, explain: "He is too tired to walk.（彼は疲れすぎて歩けない）。enough to 〜 は「〜するのに十分」" },
  { label: "【英語・高校受験】", q: "「each other」の意味は？", choices: ["お互い", "それぞれ別々に", "どちらか一方"], answer: 0, explain: "They help each other.（彼らはお互いに助け合っている）" },
  { label: "【英語・高校受験】", q: "「all over the world」の意味は？", choices: ["世界の終わりに", "世界一", "世界中で"], answer: 2, explain: "This singer is famous all over the world.（この歌手は世界中で有名だ）" },
  { label: "【英語・高校受験】", q: "「at first」の意味は？", choices: ["最初は", "ついに", "最後に"], answer: 0, explain: "At first, I didn't like it.（最初は、それが好きではなかった）。「ついに」は at last" },
  { label: "【英語・高校受験】", q: "「after all」の意味は？", choices: ["何よりも", "すべての後に", "結局、やはり"], answer: 2, explain: "He didn't come after all.（結局、彼は来なかった）" },
  { label: "【英語・高校受験】", q: "「accept」の意味は？", choices: ["〜を断る", "〜を受け入れる", "〜を例外とする"], answer: 1, explain: "She accepted the invitation.（彼女は招待を受け入れた）" },
  { label: "【英語・高校受験】", q: "「admit」の意味は？", choices: ["〜を提出する", "〜を認める", "〜を禁止する"], answer: 1, explain: "He admitted his mistake.（彼は自分の間違いを認めた）" },
  { label: "【英語・高校受験】", q: "You should ( ) eating too much sugar. 空所に入る語（句）は？", choices: ["admit", "allow", "avoid"], answer: 2, explain: "avoid は後ろに〜ing をとる。（砂糖をとりすぎるのは避けたほうがいい）" },
  { label: "【英語・高校受験】", q: "「belong to 〜」の意味は？", choices: ["〜に所属する", "〜を信じる", "〜に勝つ"], answer: 0, explain: "I belong to the tennis club.（私はテニス部に所属している）" },
  { label: "【英語・高校受験】", q: "The concert was ( ) because of the typhoon. 空所に入る語（句）は？", choices: ["celebrated", "collected", "canceled"], answer: 2, explain: "cancel は「〜を取り消す」。（台風のため、コンサートは中止になった）" },
  { label: "【英語・高校受験】", q: "「〜を祝う」を表す英語は？", choices: ["collect", "calculate", "celebrate"], answer: 2, explain: "We celebrated her birthday.（私たちは彼女の誕生日を祝った）" },
  { label: "【英語・高校受験】", q: "「collect」の意味は？", choices: ["〜を選ぶ", "〜を集める", "〜を直す"], answer: 1, explain: "He collects stamps.（彼は切手を集めている）" },
  { label: "【英語・高校受験】", q: "「compare」の意味は？", choices: ["〜を準備する", "〜を修理する", "〜を比較する"], answer: 2, explain: "Don't compare yourself with others.（他人と自分を比べないで）。compare A with B" },
  { label: "【英語・高校受験】", q: "「complain」の意味は？", choices: ["不平を言う", "〜を完成する", "〜を包む"], answer: 0, explain: "He always complains about the food.（彼はいつも食べ物に文句を言う）" },
  { label: "【英語・高校受験】", q: "「connect」の意味は？", choices: ["〜を制限する", "〜をつなぐ", "〜を切る"], answer: 1, explain: "This bridge connects the two islands.（この橋は2つの島をつなぐ）" },
  { label: "【英語・高校受験】", q: "「〜を続ける」を表す英語は？", choices: ["contain", "continue", "contact"], answer: 1, explain: "Please continue your story.（話を続けてください）" },
  { label: "【英語・高校受験】", q: "「destroy」の意味は？", choices: ["〜を設計する", "〜を描く", "〜を破壊する"], answer: 2, explain: "The storm destroyed many houses.（嵐で多くの家が壊れた）" },
  { label: "【英語・高校受験】", q: "「消える、見えなくなる」を表す英語は？", choices: ["disagree", "discover", "disappear"], answer: 2, explain: "The sun disappeared behind the clouds.（太陽が雲の後ろに消えた）" },
  { label: "【英語・高校受験】", q: "「discuss」の意味は？", choices: ["〜を発見する", "〜を割引する", "〜について話し合う"], answer: 2, explain: "We discussed the plan.（私たちは計画について話し合った）。discuss の後ろに about は不要" },
  { label: "【英語・高校受験】", q: "「earn」の意味は？", choices: ["〜を稼ぐ", "〜を学ぶ", "〜を聞く"], answer: 0, explain: "He earns 3,000 yen an hour.（彼は時給3000円を稼ぐ）" },
  { label: "【英語・高校受験】", q: "「exchange」の意味は？", choices: ["〜を交換する", "〜を伸ばす", "〜を輸出する"], answer: 0, explain: "Let's exchange email addresses.（メールアドレスを交換しよう）" },
  { label: "【英語・高校受験】", q: "「escape」の意味は？", choices: ["逃げる", "〜を探検する", "〜を見積もる"], answer: 0, explain: "The prisoner escaped.（その囚人は逃げた）" },
  { label: "【英語・高校受験】", q: "「guess」の意味は？", choices: ["〜を推測する", "〜を案内する", "〜を守る"], answer: 0, explain: "Guess what happened.（何が起こったと思う？）" },
  { label: "【英語・高校受験】", q: "「ignore」の意味は？", choices: ["〜を想像する", "〜を怒らせる", "〜を無視する"], answer: 2, explain: "She ignored my message.（彼女は私のメッセージを無視した）" },
  { label: "【英語・高校受験】", q: "Does the price ( ) breakfast? 空所に入る語（句）は？", choices: ["increase", "introduce", "include"], answer: 2, explain: "include は「〜を含む」。（料金に朝食は含まれますか）" },
  { label: "【英語・高校受験】", q: "「増える、〜を増やす」を表す英語は？", choices: ["decrease", "increase", "introduce"], answer: 1, explain: "The population is increasing.（人口は増えている）。反対は decrease" },
  { label: "【英語・高校受験】", q: "「mention」の意味は？", choices: ["〜を維持する", "〜を直す", "〜に言及する"], answer: 2, explain: "He didn't mention the problem.（彼はその問題に触れなかった）" },
  { label: "【英語・高校受験】", q: "「notice」の意味は？", choices: ["〜を拒む", "〜に気づく", "〜を訂正する"], answer: 1, explain: "I noticed a strange smell.（変なにおいに気づいた）" },
  { label: "【英語・高校受験】", q: "「prefer」の意味は？", choices: ["〜を準備する", "〜のほうを好む", "〜を予測する"], answer: 1, explain: "I prefer tea to coffee.（コーヒーより紅茶が好きだ）。prefer A to B" },
  { label: "【英語・高校受験】", q: "Heavy snow can ( ) trains from running. 空所に入る語（句）は？", choices: ["include", "prevent", "reduce"], answer: 1, explain: "prevent A from 〜ing で「Aが〜するのを防ぐ」" },
  { label: "【英語・高校受験】", q: "「recognize」の意味は？", choices: ["〜を記録する", "〜を推薦する", "〜だとわかる、〜を認める"], answer: 2, explain: "I recognized her voice.（彼女の声だとわかった）" },
  { label: "【英語・高校受験】", q: "「reduce」の意味は？", choices: ["〜を生産する", "〜を減らす", "〜を再利用する"], answer: 1, explain: "We should reduce waste.（ごみを減らすべきだ）" },
  { label: "【英語・高校受験】", q: "「require」の意味は？", choices: ["〜を必要とする", "〜を研究する", "〜を修理する"], answer: 0, explain: "This job requires patience.（この仕事は忍耐を必要とする）" },
  { label: "【英語・高校受験】", q: "「accident」の意味は？", choices: ["同意", "事故", "成績"], answer: 1, explain: "He had a car accident.（彼は交通事故にあった）" },
  { label: "【英語・高校受験】", q: "「利点、強み」を表す英語は？", choices: ["adventure", "address", "advantage"], answer: 2, explain: "Living in a city has many advantages.（都会に住むことには多くの利点がある）。反対は disadvantage" },
  { label: "【英語・高校受験】", q: "「attention」の意味は？", choices: ["注意", "到着", "意図"], answer: 0, explain: "Pay attention to the teacher.（先生の話に注意しなさい）" },
  { label: "【英語・高校受験】", q: "「character」の意味は？", choices: ["首都", "性格、登場人物", "小切手"], answer: 1, explain: "She has a strong character.（彼女は強い性格だ）" },
  { label: "【英語・高校受験】", q: "「comment」の意味は？", choices: ["委員会", "コメント、意見", "商業"], answer: 1, explain: "Please leave a comment.（コメントを残してください）" },
  { label: "【英語・高校受験】", q: "「群衆、人ごみ」を表す英語は？", choices: ["crown", "crowd", "cloud"], answer: 1, explain: "There was a big crowd at the station.（駅は大勢の人でにぎわっていた）" },
  { label: "【英語・高校受験】", q: "「detail」の意味は？", choices: ["詳細", "防衛", "破壊"], answer: 0, explain: "Please tell me the details.（詳しく教えてください）" },
  { label: "【英語・高校受験】", q: "「努力」を表す英語は？", choices: ["effort", "effect", "exit"], answer: 0, explain: "Make an effort to study every day.（毎日勉強する努力をしなさい）。effect は「効果」" },
  { label: "【英語・高校受験】", q: "「goal」の意味は？", choices: ["金", "目標、ゴール", "ガラス"], answer: 1, explain: "Her goal is to become a doctor.（彼女の目標は医者になることだ）" },
  { label: "【英語・高校受験】", q: "「knowledge」の意味は？", choices: ["知り合い", "知識", "大学"], answer: 1, explain: "He has a lot of knowledge about cars.（彼は車についての知識が豊富だ）。k は発音しない" },
  { label: "【英語・高校受験】", q: "「memory」の意味は？", choices: ["記憶、思い出", "記念碑", "会員"], answer: 0, explain: "I have a good memory.（私は記憶力がいい）" },
  { label: "【英語・高校受験】", q: "「nature」の意味は？", choices: ["栄養", "自然、本質", "国家"], answer: 1, explain: "I love nature.（私は自然が大好きだ）。nation は「国家」" },
  { label: "【英語・高校受験】", q: "「騒音、物音」を表す英語は？", choices: ["noise", "nose", "north"], answer: 0, explain: "Don't make so much noise.（そんなに騒がないで）" },
  { label: "【英語・高校受験】", q: "I felt a sharp ( ) in my back. 空所に入る語（句）は？", choices: ["paint", "page", "pain"], answer: 2, explain: "pain は「痛み」。paint は「塗料」" },
  { label: "【英語・高校受験】", q: "「purpose」の意味は？", choices: ["目的", "追跡", "利益"], answer: 0, explain: "What is the purpose of your visit?（訪問の目的は何ですか）" },
  { label: "【英語・高校受験】", q: "「質」を表す英語は？", choices: ["quality", "quantity", "quarter"], answer: 0, explain: "Quality is more important than quantity.（質は量より大切だ）。quantity は「量」" },
  { label: "【英語・高校受験】", q: "「trouble」の意味は？", choices: ["旅行", "信頼", "困りごと、面倒"], answer: 2, explain: "I'm in trouble.（困ったことになっている）" },
  { label: "【英語・高校受験】", q: "Please tell me the ( ). 空所に入る語（句）は？", choices: ["tooth", "truth", "tree"], answer: 1, explain: "tell the truth は「本当のことを言う」" },
  { label: "【英語・高校受験】", q: "「ordinary」の意味は？", choices: ["ふつうの", "特別な", "順番の"], answer: 0, explain: "an ordinary day（ふつうの日）" },
  { label: "【英語・高校受験】", q: "I'm ( ) of my son. 空所に入る語（句）は？", choices: ["proudly", "pride", "proud"], answer: 2, explain: "be proud of 〜 は「〜を誇りに思う」。名詞は pride" },
  { label: "【英語・高校受験】", q: "「rare」の意味は？", choices: ["まれな、めずらしい", "生の", "公平な"], answer: 0, explain: "a rare bird（めずらしい鳥）" },
  { label: "【英語・高校受験】", q: "「similar」の意味は？", choices: ["簡単な", "安全な", "似ている"], answer: 2, explain: "Your bag is similar to mine.（あなたのバッグは私のに似ている）。be similar to 〜" },
  { label: "【英語・高校受験】", q: "「upset」の意味は？", choices: ["落ち着いた", "動揺した、腹を立てた", "眠い"], answer: 1, explain: "She was upset about the result.（彼女は結果に動揺した）" },
  { label: "【英語・高校受験】", q: "「valuable」の意味は？", choices: ["変わりやすい", "価値のある、貴重な", "利用できる"], answer: 1, explain: "Time is valuable.（時間は貴重だ）" },
  { label: "【英語・高校受験】", q: "「wise」の意味は？", choices: ["広い", "弱い", "賢明な"], answer: 2, explain: "a wise decision（賢明な決断）" },
  { label: "【英語・高校受験】", q: "「absent」の意味は？", choices: ["欠席の", "抽象的な", "絶対の"], answer: 0, explain: "He was absent from school yesterday.（彼は昨日学校を休んだ）。反対は present" },
  { label: "【英語・高校受験】", q: "「common」の意味は？", choices: ["喜劇の", "委員会の", "ふつうの、共通の"], answer: 2, explain: "Smith is a common name.（スミスはよくある名前だ）" },
  { label: "【英語・高校受験】", q: "「curious」の意味は？", choices: ["怒った", "好奇心の強い", "退屈な"], answer: 1, explain: "Children are curious about everything.（子どもは何にでも好奇心を持つ）" },
  { label: "【英語・高校受験】", q: "「probably」の意味は？", choices: ["たぶん", "確実に", "めったに〜ない"], answer: 0, explain: "It will probably rain tomorrow.（明日はたぶん雨だ）" },
  { label: "【英語・高校受験】", q: "「therefore」の意味は？", choices: ["それゆえに", "しかしながら", "そのうえ"], answer: 0, explain: "I think, therefore I am.（我思う、ゆえに我あり）" },
  { label: "【英語・高校受験】", q: "「otherwise」の意味は？", choices: ["その代わりに", "もっと早く", "さもないと"], answer: 2, explain: "Hurry up, otherwise you'll be late.（急ぎなさい。さもないと遅れるよ）" },
  { label: "【英語・高校受験】", q: "「meanwhile」の意味は？", choices: ["やがて", "ついに", "そのあいだに"], answer: 2, explain: "Meanwhile, he was cooking dinner.（そのあいだ、彼は夕食を作っていた）" },

// ===== 英語（高校受験）201〜300問 =====
  { label: "【英語・高校受験】", q: "「be proud of 〜」の意味は？", choices: ["〜を恥じる", "〜を心配する", "〜を誇りに思う"], answer: 2, explain: "I'm proud of my team.（私はチームを誇りに思っている）。反対は be ashamed of 〜" },
  { label: "【英語・高校受験】", q: "「（辞書などで）〜を調べる」を表す英語は？", choices: ["look into", "look up", "look out"], answer: 1, explain: "Look up the word in a dictionary.（その単語を辞書で調べなさい）" },
  { label: "【英語・高校受験】", q: "「look into 〜」の意味は？", choices: ["〜を見上げる", "〜を眺める", "〜を調査する"], answer: 2, explain: "The police are looking into the case.（警察はその事件を調べている）" },
  { label: "【英語・高校受験】", q: "「Look out!」の意味は？", choices: ["外を見て！", "気をつけて！", "探して！"], answer: 1, explain: "Look out! A car is coming.（気をつけて！車が来ているよ）" },
  { label: "【英語・高校受験】", q: "She ( ) her mother. They both have long hair. 空所に入る語（句）は？", choices: ["looks like", "looks for", "looks after"], answer: 0, explain: "look like 〜 は「〜に似ている、〜のように見える」" },
  { label: "【英語・高校受験】", q: "「take off」の意味は？", choices: ["着陸する", "出発を遅らせる", "離陸する、（服などを）脱ぐ"], answer: 2, explain: "The plane took off at noon.（飛行機は正午に離陸した）。反対は land（着陸）、put on（着る）" },
  { label: "【英語・高校受験】", q: "「take after 〜」の意味は？", choices: ["〜に似ている（親などに）", "〜の世話をする", "〜を追いかける"], answer: 0, explain: "He takes after his father.（彼は父親に似ている）。血縁関係のある人に使う" },
  { label: "【英語・高校受験】", q: "「take place」の意味は？", choices: ["行われる、起こる", "場所をとる", "席を譲る"], answer: 0, explain: "The festival takes place in August.（その祭りは8月に行われる）。受け身の形にはしない" },
  { label: "【英語・高校受験】", q: "「（電車・バスなどに）乗る」を表す英語は？", choices: ["get off", "get up", "get on"], answer: 2, explain: "Get on the train at Osaka.（大阪で電車に乗りなさい）。get off は「降りる」" },
  { label: "【英語・高校受験】", q: "You should ( ) the bus at the next stop. 空所に入る語（句）は？", choices: ["get off", "get on", "get up"], answer: 0, explain: "get off は「（乗り物から）降りる」。（次の停留所でバスを降りるといい）" },
  { label: "【英語・高校受験】", q: "「get over 〜」の意味は？", choices: ["〜に乗り込む", "〜を乗り越える、〜から回復する", "〜を片づける"], answer: 1, explain: "It took a week to get over my cold.（風邪が治るのに1週間かかった）" },
  { label: "【英語・高校受験】", q: "「get in touch with 〜」の意味は？", choices: ["〜と触れ合う", "〜と出会う", "〜と連絡をとる"], answer: 2, explain: "I'll get in touch with you soon.（すぐに連絡するよ）" },
  { label: "【英語・高校受験】", q: "「go on 〜ing」の意味は？", choices: ["〜しに出かける", "〜し続ける", "〜をやめる"], answer: 1, explain: "He went on talking for an hour.（彼は1時間話し続けた）" },
  { label: "【英語・高校受験】", q: "「go through 〜」の意味は？", choices: ["〜を経験する、〜を通り抜ける", "〜を避ける", "〜を壊す"], answer: 0, explain: "She went through a hard time.（彼女はつらい時期を経験した）" },
  { label: "【英語・高校受験】", q: "「（宿題などを）提出する」を表す英語は？", choices: ["hand in", "hand out", "hand down"], answer: 0, explain: "Please hand in your report by Friday.（金曜日までにレポートを提出してください）。hand out は「配る」" },
  { label: "【英語・高校受験】", q: "「Hold on.」の意味は？", choices: ["がんばって", "ちょっと待って", "動かないで"], answer: 1, explain: "Hold on a minute.（ちょっと待って）。電話で「そのままお待ちください」の意味でも使う" },
  { label: "【英語・高校受験】", q: "「keep in touch」の意味は？", choices: ["連絡を絶つ", "連絡を取り合う", "連絡を待つ"], answer: 1, explain: "Let's keep in touch.（連絡を取り合おう）" },
  { label: "【英語・高校受験】", q: "「let 〜 down」の意味は？", choices: ["〜を降ろす", "〜をがっかりさせる", "〜を休ませる"], answer: 1, explain: "I don't want to let you down.（あなたをがっかりさせたくない）" },
  { label: "【英語・高校受験】", q: "「make up one's mind」の意味は？", choices: ["気持ちを変える", "覚える", "決心する"], answer: 2, explain: "I made up my mind to study abroad.（私は留学すると決心した）" },
  { label: "【英語・高校受験】", q: "「〜を利用する、活用する」を表す英語は？", choices: ["make up for", "make fun of", "make use of"], answer: 2, explain: "Make use of your time.（時間を有効に使いなさい）。make fun of 〜 は「〜をからかう」" },
  { label: "【英語・高校受験】", q: "「on purpose」の意味は？", choices: ["偶然に", "急いで", "わざと"], answer: 2, explain: "He broke the cup on purpose.（彼はわざとカップを割った）。反対は by accident" },
  { label: "【英語・高校受験】", q: "「by mistake」の意味は？", choices: ["わざと", "間違って", "すぐに"], answer: 1, explain: "I took your umbrella by mistake.（間違ってあなたの傘を持ってきてしまった）" },
  { label: "【英語・高校受験】", q: "I got up early ( ) catch the first train. 空所に入る語（句）は？", choices: ["so that", "in order to", "because of"], answer: 1, explain: "in order to 〜 は「〜するために」（目的）。後ろは動詞の原形" },
  { label: "【英語・高校受験】", q: "「as a result」の意味は？", choices: ["例えば", "ところで", "その結果"], answer: 2, explain: "He studied hard. As a result, he passed the exam.（彼は一生懸命勉強し、その結果、試験に合格した）" },
  { label: "【英語・高校受験】", q: "「on the other hand」の意味は？", choices: ["その結果", "たとえば", "一方で"], answer: 2, explain: "This plan is cheap. On the other hand, it takes a long time.（この計画は安いが、一方で時間がかかる）" },
  { label: "【英語・高校受験】", q: "「in the end」の意味は？", choices: ["結局、最後には", "最初は", "ついでに"], answer: 0, explain: "In the end, we decided to stay home.（結局、私たちは家にいることにした）" },
  { label: "【英語・高校受験】", q: "「for the first time」の意味は？", choices: ["初めて", "最後に", "ひさしぶりに"], answer: 0, explain: "I saw snow for the first time.（私は初めて雪を見た）" },
  { label: "【英語・高校受験】", q: "「from now on」の意味は？", choices: ["今までは", "今後は", "今のところ"], answer: 1, explain: "From now on, I'll get up earlier.（今後は、もっと早く起きます）" },
  { label: "【英語・高校受験】", q: "「right away」の意味は？", choices: ["ずっと前に", "すぐに", "そのうちに"], answer: 1, explain: "Please come right away.（すぐに来てください）" },
  { label: "【英語・高校受験】", q: "「sooner or later」の意味は？", choices: ["早ければ早いほど", "いつでも", "遅かれ早かれ"], answer: 2, explain: "Sooner or later, you'll understand.（遅かれ早かれ、わかるよ）" },
  { label: "【英語・高校受験】", q: "You can stay here ( ) you are quiet. 空所に入る語（句）は？", choices: ["as soon as", "as long as", "as well as"], answer: 1, explain: "as long as 〜 は「〜する限り」（条件）" },
  { label: "【英語・高校受験】", q: "「even if 〜」の意味は？", choices: ["〜でない限り", "たとえ〜でも", "〜かどうか"], answer: 1, explain: "Even if it rains, I'll go.（たとえ雨でも行く）" },
  { label: "【英語・高校受験】", q: "「no longer 〜」の意味は？", choices: ["まだ〜ない", "長くない", "もはや〜ない"], answer: 2, explain: "He no longer lives here.（彼はもうここには住んでいない）" },
  { label: "【英語・高校受験】", q: "I like fruit, ( ) apples and oranges. 空所に入る語（句）は？", choices: ["as well as", "instead of", "such as"], answer: 2, explain: "such as 〜 は「〜のような」（例を挙げる）" },
  { label: "【英語・高校受験】", q: "「be in a hurry」の意味は？", choices: ["心配している", "気に入っている", "急いでいる"], answer: 2, explain: "I'm in a hurry. Let's go.（急いでいるんだ。行こう）" },
  { label: "【英語・高校受験】", q: "「be about to 〜」の意味は？", choices: ["〜するべきだ", "〜したことがある", "まさに〜しようとしている"], answer: 2, explain: "The movie is about to start.（映画が始まろうとしている）" },
  { label: "【英語・高校受験】", q: "You ( ) go to bed early. You look tired. 空所に入る語（句）は？", choices: ["would better", "had better", "should better"], answer: 1, explain: "had better 〜 は「〜したほうがよい」（強めの助言）。後ろは動詞の原形" },
  { label: "【英語・高校受験】", q: "「be supposed to 〜」の意味は？", choices: ["〜することになっている", "〜するふりをする", "〜を想像する"], answer: 0, explain: "I'm supposed to meet him at six.（6時に彼に会うことになっている）" },
  { label: "【英語・高校受験】", q: "「be likely to 〜」の意味は？", choices: ["〜しそうだ", "〜が好きだ", "〜に似ている"], answer: 0, explain: "It is likely to rain tonight.（今夜は雨が降りそうだ）" },
  { label: "【英語・高校受験】", q: "「〜でいっぱいだ」を表す英語は？", choices: ["be made of", "be tired of", "be full of"], answer: 2, explain: "The box is full of toys.（その箱はおもちゃでいっぱいだ）" },
  { label: "【英語・高校受験】", q: "「be tired of 〜」の意味は？", choices: ["〜に興味がある", "〜にうんざりしている", "〜が得意だ"], answer: 1, explain: "I'm tired of the same food every day.（毎日同じ食事にうんざりしている）" },
  { label: "【英語・高校受験】", q: "「be different from 〜」の意味は？", choices: ["〜に似ている", "〜と同じだ", "〜と違う"], answer: 2, explain: "My opinion is different from yours.（私の意見はあなたのとは違う）" },
  { label: "【英語・高校受験】", q: "I was ( ) school this morning. 空所に入る語（句）は？", choices: ["late to", "late for", "late in"], answer: 1, explain: "be late for 〜 は「〜に遅れる」" },
  { label: "【英語・高校受験】", q: "「pay attention to 〜」の意味は？", choices: ["〜に注意を払う", "〜を払い戻す", "〜に気づかない"], answer: 0, explain: "Pay attention to what he says.（彼の言うことに注意を払いなさい）。to のあとは名詞・動名詞" },
  { label: "【英語・高校受験】", q: "「take advantage of 〜」の意味は？", choices: ["〜の世話をする", "〜を利用する、〜につけこむ", "〜を延期する"], answer: 1, explain: "Let's take advantage of the good weather.（いい天気を利用しよう）" },
  { label: "【英語・高校受験】", q: "「turn down 〜」の意味は？", choices: ["〜を回す", "〜を断る、（音量を）下げる", "〜を見下ろす"], answer: 1, explain: "He turned down the job offer.（彼は仕事の申し出を断った）。turn up は「（音量を）上げる」" },
  { label: "【英語・高校受験】", q: "「turn into 〜」の意味は？", choices: ["〜に入る", "〜を回す", "〜に変わる"], answer: 2, explain: "The caterpillar turned into a butterfly.（毛虫はちょうになった）" },
  { label: "【英語・高校受験】", q: "「put off 〜」の意味は？", choices: ["〜を身につける", "〜を延期する", "〜を消す"], answer: 1, explain: "We put off the meeting until next week.（会議を来週に延期した）" },
  { label: "【英語・高校受験】", q: "「set up 〜」の意味は？", choices: ["〜を延期する", "〜を設立する、準備する", "〜を解散する"], answer: 1, explain: "They set up a new company.（彼らは新しい会社を設立した）" },
  { label: "【英語・高校受験】", q: "「show up」の意味は？", choices: ["〜を見せる", "〜を目立たなくする", "現れる"], answer: 2, explain: "He didn't show up at the party.（彼はパーティーに現れなかった）" },
  { label: "【英語・高校受験】", q: "「arrange」の意味は？", choices: ["〜を手配する、整える", "〜を到着させる", "〜を禁止する"], answer: 0, explain: "I'll arrange a meeting.（会議を手配しよう）" },
  { label: "【英語・高校受験】", q: "「〜を引きつける」を表す英語は？", choices: ["attach", "attract", "attack"], answer: 1, explain: "The festival attracts many tourists.（その祭りは多くの観光客を引きつける）。形容詞は attractive" },
  { label: "【英語・高校受験】", q: "「compete」の意味は？", choices: ["〜を保存する", "〜を整理する", "競争する"], answer: 2, explain: "Many companies compete with each other.（多くの会社が競い合っている）。名詞は competition" },
  { label: "【英語・高校受験】", q: "「concentrate」の意味は？", choices: ["〜を集める", "〜を結ぶ", "集中する"], answer: 2, explain: "I can't concentrate on my work.（仕事に集中できない）。concentrate on 〜 の形で使う" },
  { label: "【英語・高校受験】", q: "「consider」の意味は？", choices: ["〜を比べる", "〜に相談する", "〜をよく考える、考慮する"], answer: 2, explain: "Please consider my idea.（私の案を考慮してください）。後ろは名詞か 〜ing" },
  { label: "【英語・高校受験】", q: "「〜を含んでいる」を表す英語は？", choices: ["continue", "contain", "control"], answer: 1, explain: "This bottle contains juice.（このボトルにはジュースが入っている）" },
  { label: "【英語・高校受験】", q: "「deliver」の意味は？", choices: ["〜を提案する", "〜を預ける", "〜を配達する"], answer: 2, explain: "They deliver the mail every morning.（彼らは毎朝郵便を配達する）" },
  { label: "【英語・高校受験】", q: "「deny」の意味は？", choices: ["〜を認める", "〜を否定する", "〜を守る"], answer: 1, explain: "He denied the story.（彼はその話を否定した）" },
  { label: "【英語・高校受験】", q: "「disturb」の意味は？", choices: ["〜を配る", "〜を分ける", "〜を邪魔する"], answer: 2, explain: "Don't disturb me. I'm studying.（邪魔しないで。勉強中なの）" },
  { label: "【英語・高校受験】", q: "「〜を励ます」を表す英語は？", choices: ["engage", "enjoy", "encourage"], answer: 2, explain: "She encouraged me to try again.（彼女はもう一度挑戦するよう励ましてくれた）" },
  { label: "【英語・高校受験】", q: "「examine」の意味は？", choices: ["〜を調べる、診察する", "〜を練習する", "〜を免除する"], answer: 0, explain: "The doctor examined the child.（医者はその子を診察した）。名詞は examination（試験・検査）" },
  { label: "【英語・高校受験】", q: "「explore」の意味は？", choices: ["〜を探検する", "〜を輸出する", "〜を爆発させる"], answer: 0, explain: "They explored the cave.（彼らはその洞くつを探検した）" },
  { label: "【英語・高校受験】", q: "「express」の意味は？", choices: ["〜を表現する", "〜を延長する", "〜を押す"], answer: 0, explain: "It's hard to express my feelings.（自分の気持ちを表現するのは難しい）" },
  { label: "【英語・高校受験】", q: "「handle」の意味は？", choices: ["〜を扱う、処理する", "〜を手渡す", "〜を吊るす"], answer: 0, explain: "Can you handle this problem?（この問題を処理できますか）" },
  { label: "【英語・高校受験】", q: "「hesitate」の意味は？", choices: ["ためらう", "急ぐ", "遅れる"], answer: 0, explain: "Don't hesitate to ask me.（遠慮なく私に聞いてください）" },
  { label: "【英語・高校受験】", q: "「impress」の意味は？", choices: ["〜を押し込む", "〜を感動させる、好印象を与える", "〜を輸入する"], answer: 1, explain: "I was impressed by her speech.（彼女のスピーチに感動した）" },
  { label: "【英語・高校受験】", q: "「〜と主張する、言い張る」を表す英語は？", choices: ["resist", "insist", "exist"], answer: 1, explain: "He insisted that he was right.（彼は自分が正しいと言い張った）" },
  { label: "【英語・高校受験】", q: "「invent」の意味は？", choices: ["〜を投資する", "〜を発明する", "〜を在庫する"], answer: 1, explain: "Who invented the telephone?（電話を発明したのは誰か）。名詞は invention" },
  { label: "【英語・高校受験】", q: "「judge」の意味は？", choices: ["〜を動かす", "〜を結合する", "〜を判断する"], answer: 2, explain: "Don't judge a book by its cover.（見かけで判断してはいけない）。名詞では「裁判官」の意味" },
  { label: "【英語・高校受験】", q: "「なんとか〜する、〜を経営する」を表す英語は？", choices: ["manage", "mention", "manner"], answer: 0, explain: "I managed to finish the work.（なんとか仕事を終えた）。manage to 〜 は「なんとか〜する」" },
  { label: "【英語・高校受験】", q: "「measure」の意味は？", choices: ["〜を混ぜる", "〜に会う", "〜を測る"], answer: 2, explain: "Measure the length of the desk.（机の長さを測りなさい）" },
  { label: "【英語・高校受験】", q: "「observe」の意味は？", choices: ["〜を保存する", "〜を観察する", "〜を取り除く"], answer: 1, explain: "We observed birds in the park.（私たちは公園で鳥を観察した）" },
  { label: "【英語・高校受験】", q: "「occur」の意味は？", choices: ["起こる", "〜を占める", "〜を提供する"], answer: 0, explain: "The accident occurred at night.（その事故は夜に起こった）。受け身にはしない" },
  { label: "【英語・高校受験】", q: "「rescue」の意味は？", choices: ["〜を救助する", "〜を研究する", "〜を要求する"], answer: 0, explain: "The firefighters rescued the boy.（消防士がその少年を救助した）" },
  { label: "【英語・高校受験】", q: "「solve」の意味は？", choices: ["〜を売る", "〜を解決する", "〜を分ける"], answer: 1, explain: "Let's solve this problem together.（この問題を一緒に解決しよう）。名詞は solution" },
  { label: "【英語・高校受験】", q: "「benefit」の意味は？", choices: ["利益、恩恵", "損害", "貯金"], answer: 0, explain: "the benefits of exercise（運動の利点）" },
  { label: "【英語・高校受験】", q: "「border」の意味は？", choices: ["国境、境界", "注文", "ボール"], answer: 0, explain: "the border between France and Spain（フランスとスペインの国境）" },
  { label: "【英語・高校受験】", q: "「予算」を表す英語は？", choices: ["bucket", "budget", "bugle"], answer: 1, explain: "a tight budget（厳しい予算）" },
  { label: "【英語・高校受験】", q: "「career」の意味は？", choices: ["職業、経歴", "気配り", "荷物"], answer: 0, explain: "She had a long career as a teacher.（彼女は教師として長いキャリアがあった）" },
  { label: "【英語・高校受験】", q: "「challenge」の意味は？", choices: ["挑戦、難題", "変化", "偶然"], answer: 0, explain: "Learning a new language is a big challenge.（新しい言語を学ぶのは大きな挑戦だ）" },
  { label: "【英語・高校受験】", q: "「citizen」の意味は？", choices: ["市長", "都市", "市民、国民"], answer: 2, explain: "He is a citizen of Japan.（彼は日本国民だ）" },
  { label: "【英語・高校受験】", q: "「damage」の意味は？", choices: ["損害、被害", "ダム", "危険"], answer: 0, explain: "The storm caused serious damage.（嵐は深刻な被害をもたらした）" },
  { label: "【英語・高校受験】", q: "「決定、決心」を表す英語は？", choices: ["division", "decoration", "decision"], answer: 2, explain: "Have you made a decision?（決心はついた？）。動詞は decide" },
  { label: "【英語・高校受験】", q: "「evidence」の意味は？", choices: ["証拠", "出来事", "証明書"], answer: 0, explain: "There is no evidence.（証拠がない）。数えられない名詞" },
  { label: "【英語・高校受験】", q: "「fee」の意味は？", choices: ["恐怖", "（サービスの）料金", "運賃"], answer: 1, explain: "an entrance fee（入場料）" },
  { label: "【英語・高校受験】", q: "「method」の意味は？", choices: ["方法", "医学", "瞬間"], answer: 0, explain: "a new method of teaching（新しい教え方）" },
  { label: "【英語・高校受験】", q: "「意見」を表す英語は？", choices: ["option", "operation", "opinion"], answer: 2, explain: "In my opinion, he is right.（私の意見では、彼は正しい）" },
  { label: "【英語・高校受験】", q: "「passenger」の意味は？", choices: ["歩行者", "運転手", "乗客"], answer: 2, explain: "The bus has thirty passengers.（バスには30人の乗客がいる）" },
  { label: "【英語・高校受験】", q: "「pressure」の意味は？", choices: ["圧縮", "楽しみ", "圧力、プレッシャー"], answer: 2, explain: "peer pressure（仲間からの圧力）" },
  { label: "【英語・高校受験】", q: "「schedule」の意味は？", choices: ["予定、時刻表", "学校", "奨学金"], answer: 0, explain: "a busy schedule（忙しい予定）" },
  { label: "【英語・高校受験】", q: "「anxious」の意味は？", choices: ["熱心な", "心配している、不安な", "怒った"], answer: 1, explain: "She felt anxious before the exam.（彼女は試験の前に不安だった）" },
  { label: "【英語・高校受験】", q: "「eager」の意味は？", choices: ["熱心な、切望している", "簡単な", "早い"], answer: 0, explain: "He is eager to learn.（彼は学ぶことに熱心だ）。be eager to 〜 の形でよく使う" },
  { label: "【英語・高校受験】", q: "「equal」の意味は？", choices: ["特別な", "等しい、平等な", "地方の"], answer: 1, explain: "All people are equal.（すべての人は平等だ）" },
  { label: "【英語・高校受験】", q: "「essential」の意味は？", choices: ["不可欠な", "余分な", "人工の"], answer: 0, explain: "Water is essential for life.（水は生命に不可欠だ）" },
  { label: "【英語・高校受験】", q: "「generous」の意味は？", choices: ["一般的な", "遺伝の", "気前のよい、寛大な"], answer: 2, explain: "He is generous to everyone.（彼は誰にでも気前がよい）" },
  { label: "【英語・高校受験】", q: "「巨大な」を表す英語は？", choices: ["huge", "humble", "human"], answer: 0, explain: "a huge building（巨大な建物）" },
  { label: "【英語・高校受験】", q: "「obvious」の意味は？", choices: ["従順な", "明らかな", "必要な"], answer: 1, explain: "It's obvious that he is lying.（彼がうそをついているのは明らかだ）" },
  { label: "【英語・高校受験】", q: "「tough」の意味は？", choices: ["やさしい", "つらい、たくましい、固い", "丁寧な"], answer: 1, explain: "a tough job（つらい仕事）。発音は /tʌf/" },
  { label: "【英語・高校受験】", q: "「unique」の意味は？", choices: ["ふつうの", "団結した", "唯一の、独特の"], answer: 2, explain: "Every snowflake is unique.（雪の結晶はどれも独特だ）" },
  { label: "【英語・高校受験】", q: "「urgent」の意味は？", choices: ["緊急の", "上品な", "都会の"], answer: 0, explain: "an urgent message（緊急のメッセージ）" },

// ===== 英語（高校受験）301〜400問 =====
  { label: "【英語・高校受験】", q: "「remind」の意味は？", choices: ["〜に思い出させる", "〜を取り除く", "〜を繰り返す"], answer: 0, explain: "This song reminds me of my school days.（この歌を聞くと学生時代を思い出す）。remind A of B で「AにBを思い出させる」" },
  { label: "【英語・高校受験】", q: "「〜を繰り返す」を表す英単語は？", choices: ["repair", "repeat", "reply"], answer: 1, explain: "Could you repeat that, please?（もう一度言っていただけますか）" },
  { label: "【英語・高校受験】", q: "「replace」の意味は？", choices: ["〜を返す", "〜を報告する", "〜を取りかえる、〜の代わりになる"], answer: 2, explain: "I need to replace the old battery.（古い電池を取りかえる必要がある）" },
  { label: "【英語・高校受験】", q: "「〜を取り除く」を表す英単語は？", choices: ["remind", "remain", "remove"], answer: 2, explain: "Please remove your shoes at the door.（入り口で靴を脱いでください）" },
  { label: "【英語・高校受験】", q: "「reserve」の意味は？", choices: ["〜を予約する", "〜を断る", "〜を受け取る"], answer: 0, explain: "I'd like to reserve a table for two.（2人分のテーブルを予約したいのですが）" },
  { label: "【英語・高校受験】", q: "「reply」の意味は？", choices: ["返事をする", "〜を繰り返す", "〜を期待する"], answer: 0, explain: "She replied to my email quickly.（彼女は私のメールにすぐ返事をくれた）。reply to 〜 の形で使う" },
  { label: "【英語・高校受験】", q: "「〜を翻訳する」を表す英単語は？", choices: ["transfer", "transport", "translate"], answer: 2, explain: "Please translate this sentence into English.（この文を英語に翻訳してください）。translate A into B" },
  { label: "【英語・高校受験】", q: "「spread」の意味は？", choices: ["〜を節約する", "〜を広げる、広がる", "〜をつづる"], answer: 1, explain: "The news spread quickly.（そのニュースはすばやく広まった）。活用は spread - spread - spread" },
  { label: "【英語・高校受験】", q: "「warn」の意味は？", choices: ["〜に警告する", "〜を洗う", "〜を温める"], answer: 0, explain: "He warned us about the danger.（彼は私たちに危険を警告した）" },
  { label: "【英語・高校受験】", q: "「waste」の意味は？", choices: ["〜を無駄にする、無駄", "〜を待つ", "〜を心配する"], answer: 0, explain: "Don't waste your time.（時間を無駄にしないで）。a waste of time で「時間の無駄」" },
  { label: "【英語・高校受験】", q: "「trust」の意味は？", choices: ["〜を試す", "〜を治療する", "〜を信頼する"], answer: 2, explain: "I trust you.（あなたを信頼している）。名詞でも「信頼」の意味" },
  { label: "【英語・高校受験】", q: "「forgive」の意味は？", choices: ["〜を忘れる", "〜を与える", "〜を許す"], answer: 2, explain: "Please forgive me.（どうか許してください）。活用は forgive - forgave - forgiven" },
  { label: "【英語・高校受験】", q: "「introduce」の意味は？", choices: ["〜を招待する", "〜を輸入する", "〜を紹介する"], answer: 2, explain: "Let me introduce my friend to you.（友達を紹介させてください）。introduce A to B" },
  { label: "【英語・高校受験】", q: "「deserve」の意味は？", choices: ["〜を保存する", "〜に値する", "〜に給仕する"], answer: 1, explain: "You deserve a long rest.（あなたは長い休みを取るに値する）" },
  { label: "【英語・高校受験】", q: "「cause」の意味は？", choices: ["〜を引き起こす、原因", "〜をつかまえる", "〜を休ませる"], answer: 0, explain: "Heavy rain caused the flood.（大雨が洪水を引き起こした）" },
  { label: "【英語・高校受験】", q: "「steal」の意味は？", choices: ["〜を盗む", "〜をだます", "〜を刺す"], answer: 0, explain: "Someone stole my bike.（誰かが私の自転車を盗んだ）。活用は steal - stole - stolen" },
  { label: "【英語・高校受験】", q: "「rent」の意味は？", choices: ["〜を引き裂く", "〜を修理する", "〜を有料で借りる、家賃"], answer: 2, explain: "We rent a house near the station.（私たちは駅の近くの家を借りている）。borrow は無料で借りるときに使う" },
  { label: "【英語・高校受験】", q: "「support」の意味は？", choices: ["〜を提案する", "〜を支える、支持する", "〜を押さえる"], answer: 1, explain: "My family always supports me.（家族はいつも私を支えてくれる）" },
  { label: "【英語・高校受験】", q: "「discount」の意味は？", choices: ["討論", "距離", "割引"], answer: 2, explain: "This shop gives a 10% discount.（この店は10％の割引をしてくれる）" },
  { label: "【英語・高校受験】", q: "「締め切り」を表す英単語は？", choices: ["headline", "deadline", "outline"], answer: 1, explain: "The deadline is next Friday.（締め切りは来週の金曜日だ）。headline は「見出し」、outline は「概要」" },
  { label: "【英語・高校受験】", q: "「delay」の意味は？", choices: ["遅れ、〜を遅らせる", "防衛", "配達"], answer: 0, explain: "The flight was delayed by two hours.（その便は2時間遅れた）" },
  { label: "【英語・高校受験】", q: "「direction」の意味は？", choices: ["発見", "訂正", "方向、道順"], answer: 2, explain: "Which direction is the station?（駅はどちらの方向ですか）。directions は「道順、使用説明」の意味でもよく使う" },
  { label: "【英語・高校受験】", q: "「地震」を表す英単語は？", choices: ["typhoon", "volcano", "earthquake"], answer: 2, explain: "A big earthquake hit the city.（大きな地震がその街を襲った）。typhoon は台風、volcano は火山" },
  { label: "【英語・高校受験】", q: "「emergency」の意味は？", choices: ["感情", "緊急事態", "帝国"], answer: 1, explain: "In an emergency, call 119.（緊急のときは119番に電話しなさい）" },
  { label: "【英語・高校受験】", q: "「洪水」を表す英単語は？", choices: ["blood", "flood", "floor"], answer: 1, explain: "The flood destroyed many houses.（洪水で多くの家が壊れた）。blood は「血」、floor は「床」" },
  { label: "【英語・高校受験】", q: "「weather forecast」の forecast の意味は？", choices: ["予算", "予定", "予報"], answer: 2, explain: "The forecast says it will be sunny tomorrow.（予報では明日は晴れだ）" },
  { label: "【英語・高校受験】", q: "「ごみ」を表す英単語は？", choices: ["garbage", "garden", "garage"], answer: 0, explain: "Please take out the garbage.（ごみを出してください）。garden は「庭」、garage は「車庫」" },
  { label: "【英語・高校受験】", q: "「height」の意味は？", choices: ["高さ、身長", "重さ", "幅"], answer: 0, explain: "What is the height of this tower?（この塔の高さはどれくらいですか）。発音は /haɪt/。重さは weight" },
  { label: "【英語・高校受験】", q: "「ingredient」の意味は？", choices: ["（料理の）材料", "道具", "指示"], answer: 0, explain: "Eggs are an important ingredient.（卵は大切な材料だ）" },
  { label: "【英語・高校受験】", q: "「昆虫」を表す英単語は？", choices: ["insect", "instinct", "inspect"], answer: 0, explain: "Ants are small insects.（アリは小さな昆虫だ）。instinct は「本能」、inspect は「〜を検査する」" },
  { label: "【英語・高校受験】", q: "「island」の意味は？", choices: ["岩", "氷", "島"], answer: 2, explain: "Okinawa is a beautiful island.（沖縄は美しい島だ）。s は発音しない（/ˈaɪlənd/）" },
  { label: "【英語・高校受験】", q: "「lawyer」の意味は？", choices: ["警察官", "裁判官", "弁護士"], answer: 2, explain: "My aunt is a lawyer.（私のおばは弁護士だ）" },
  { label: "【英語・高校受験】", q: "「lecture」の意味は？", choices: ["読書", "手紙", "講義、講演"], answer: 2, explain: "I attended a lecture on history.（歴史の講義に出席した）" },
  { label: "【英語・高校受験】", q: "「manners」（複数形）の意味は？", choices: ["市民", "地図", "作法、礼儀"], answer: 2, explain: "Good manners are important.（礼儀作法は大切だ）。manner（単数）は「方法」の意味" },
  { label: "【英語・高校受験】", q: "「間違い」を表す英単語は？", choices: ["mistake", "mission", "mixture"], answer: 0, explain: "I made a mistake.（私は間違えた）。mission は「任務」、mixture は「混ぜ合わせたもの」" },
  { label: "【英語・高校受験】", q: "「mystery」の意味は？", choices: ["歴史", "なぞ、不思議", "音楽"], answer: 1, explain: "The disappearance of the ship is still a mystery.（その船の失踪は今もなぞだ）" },
  { label: "【英語・高校受験】", q: "「平和」を表す英単語は？", choices: ["piece", "peace", "pace"], answer: 1, explain: "We all want world peace.（私たちはみんな世界平和を願っている）。piece は「一切れ」で、発音が同じ" },
  { label: "【英語・高校受験】", q: "「prize」の意味は？", choices: ["賞", "価格", "祈り"], answer: 0, explain: "He won first prize.（彼は1等賞を取った）。price は「価格」" },
  { label: "【英語・高校受験】", q: "「惑星」を表す英単語は？", choices: ["plant", "planet", "plane"], answer: 1, explain: "Earth is a planet.（地球は惑星だ）。plant は「植物」、plane は「飛行機」" },
  { label: "【英語・高校受験】", q: "「pleasure」の意味は？", choices: ["喜び、楽しみ", "圧力", "宝物"], answer: 0, explain: "It's a pleasure to meet you.（お会いできてうれしいです）。My pleasure. は「どういたしまして」" },
  { label: "【英語・高校受験】", q: "「brave」の意味は？", choices: ["勇敢な", "広い", "悲しい"], answer: 0, explain: "The firefighter was very brave.（その消防士はとても勇敢だった）" },
  { label: "【英語・高校受験】", q: "「空の」を表す英単語は？", choices: ["enemy", "empty", "entry"], answer: 1, explain: "The box is empty.（その箱は空だ）。enemy は「敵」、entry は「入場」" },
  { label: "【英語・高校受験】", q: "「gentle」の意味は？", choices: ["紳士", "遺伝の", "優しい、穏やかな"], answer: 2, explain: "He is gentle to animals.（彼は動物に優しい）" },
  { label: "【英語・高校受験】", q: "「lonely」の意味は？", choices: ["愛らしい", "孤独な、さびしい", "ひとりの"], answer: 1, explain: "She felt lonely in the new town.（彼女は新しい町でさびしく感じた）" },
  { label: "【英語・高校受験】", q: "「shy」の意味は？", choices: ["内気な、恥ずかしがりの", "浅い", "うれしい"], answer: 0, explain: "He is too shy to speak in public.（彼は内気で人前で話せない）" },
  { label: "【英語・高校受験】", q: "「sharp」の意味は？", choices: ["形の", "共有する", "鋭い、とがった"], answer: 2, explain: "Be careful. This knife is sharp.（気をつけて。このナイフは鋭いよ）" },
  { label: "【英語・高校受験】", q: "「silent」の意味は？", choices: ["類似の", "静かな、無言の", "署名"], answer: 1, explain: "The room was silent.（部屋は静まりかえっていた）。名詞は silence（静けさ）" },
  { label: "【英語・高校受験】", q: "「strict」の意味は？", choices: ["まっすぐな", "奇妙な", "厳しい"], answer: 2, explain: "Our teacher is strict.（私たちの先生は厳しい）" },
  { label: "【英語・高校受験】", q: "「terrible」の意味は？", choices: ["ひどい、恐ろしい", "すばらしい", "理にかなった"], answer: 0, explain: "The weather was terrible.（天気はひどかった）" },
  { label: "【英語・高校受験】", q: "「wealthy」の意味は？", choices: ["健康な", "裕福な", "弱い"], answer: 1, explain: "He comes from a wealthy family.（彼は裕福な家の出身だ）。名詞は wealth（富）" },
  { label: "【英語・高校受験】", q: "「local」の意味は？", choices: ["論理的な", "長い", "地元の"], answer: 2, explain: "a local newspaper（地元の新聞）" },
  { label: "【英語・高校受験】", q: "「positive」の意味は？", choices: ["前向きな、肯定的な", "ていねいな", "可能な"], answer: 0, explain: "Try to be positive.（前向きになるようにしなさい）。反対は negative" },
  { label: "【英語・高校受験】", q: "「hardly」の意味は？", choices: ["ほとんど〜ない", "一生懸命に", "すぐに"], answer: 0, explain: "I can hardly hear you.（あなたの声がほとんど聞こえない）。hard（一生懸命に）とは意味が違う" },
  { label: "【英語・高校受験】", q: "「seldom」の意味は？", choices: ["しばしば", "めったに〜ない", "たいてい"], answer: 1, explain: "She seldom eats breakfast.（彼女はめったに朝食を食べない）。頻度は often ＞ sometimes ＞ seldom ＞ never の順に低くなる" },
  { label: "【英語・高校受験】", q: "「eventually」の意味は？", choices: ["偶然に", "もっとも", "最終的に、ついに"], answer: 2, explain: "He eventually found a job.（彼はついに仕事を見つけた）" },
  { label: "【英語・高校受験】", q: "「gradually」の意味は？", choices: ["少しずつ、徐々に", "突然に", "まっすぐに"], answer: 0, explain: "The weather gradually got warmer.（天気は徐々に暖かくなった）" },
  { label: "【英語・高校受験】", q: "「immediately」の意味は？", choices: ["まもなく", "最近", "ただちに"], answer: 2, explain: "Please come immediately.（すぐに来てください）" },
  { label: "【英語・高校受験】", q: "「anyway」の意味は？", choices: ["どこでも", "とにかく、それでも", "いつでも"], answer: 1, explain: "Anyway, let's get started.（とにかく、始めよう）" },
  { label: "【英語・高校受験】", q: "「besides」の意味は？", choices: ["〜のそばに", "そのうえ、〜のほかに", "〜のあいだに"], answer: 1, explain: "It's too late. Besides, I'm tired.（遅すぎるし、そのうえ疲れている）。beside は「〜のそばに」" },
  { label: "【英語・高校受験】", q: "「regularly」の意味は？", choices: ["定期的に、規則正しく", "ゆっくりと", "おそらく"], answer: 0, explain: "He exercises regularly.（彼は定期的に運動している）" },
  { label: "【英語・高校受験】", q: "「bring up 〜」の意味は？", choices: ["〜を持ってくる", "〜を育てる、（話題を）持ち出す", "〜を見上げる"], answer: 1, explain: "She was brought up in Osaka.（彼女は大阪で育った）。bring up the topic で「話題を持ち出す」" },
  { label: "【英語・高校受験】", q: "「call off 〜」の意味は？", choices: ["〜を中止する", "〜に電話をかける", "〜を呼び出す"], answer: 0, explain: "The game was called off because of rain.（雨のため試合は中止になった）" },
  { label: "【英語・高校受験】", q: "「carry out 〜」の意味は？", choices: ["〜を延期する", "〜を実行する、やり遂げる", "〜を片づける"], answer: 1, explain: "We carried out the plan.（私たちはその計画を実行した）" },
  { label: "【英語・高校受験】", q: "「cheer up 〜」の意味は？", choices: ["〜を歓迎する", "〜をからかう", "〜を元気づける"], answer: 2, explain: "Cheer up! Everything will be fine.（元気を出して！すべてうまくいくよ）" },
  { label: "【英語・高校受験】", q: "「count on 〜」の意味は？", choices: ["〜を数える", "〜を頼りにする", "〜に反対する"], answer: 1, explain: "You can count on me.（私に任せて）。depend on とほぼ同じ意味" },
  { label: "【英語・高校受験】", q: "「deal with 〜」の意味は？", choices: ["〜に対処する、〜を扱う", "〜と取引をやめる", "〜を分ける"], answer: 0, explain: "How do you deal with stress?（ストレスにどう対処していますか）" },
  { label: "【英語・高校受験】", q: "「drop by」の意味は？", choices: ["〜を落とす", "立ち寄る", "〜をやめる"], answer: 1, explain: "Drop by my house anytime.（いつでもうちに立ち寄って）" },
  { label: "【英語・高校受験】", q: "「end up 〜ing」の意味は？", choices: ["〜を終わらせる", "〜をやめる", "結局〜することになる"], answer: 2, explain: "We ended up walking home.（結局、私たちは歩いて帰ることになった）" },
  { label: "【英語・高校受験】", q: "「figure out 〜」の意味は？", choices: ["〜を理解する、解き明かす", "〜を数字で表す", "〜を描く"], answer: 0, explain: "I can't figure out this problem.（この問題が解けない）" },
  { label: "【英語・高校受験】", q: "「get rid of 〜」の意味は？", choices: ["〜に追いつく", "〜を取り除く、処分する", "〜を乗り越える"], answer: 1, explain: "I got rid of my old clothes.（古い服を処分した）" },
  { label: "【英語・高校受験】", q: "「hang up」の意味は？", choices: ["電話に出る", "電話をかける", "電話を切る"], answer: 2, explain: "He hung up before I could answer.（私が答える前に彼は電話を切った）" },
  { label: "【英語・高校受験】", q: "「hear from 〜」の意味は？", choices: ["〜の話を聞き逃す", "〜から連絡をもらう", "〜を聞いて怒る"], answer: 1, explain: "I haven't heard from him for a month.（1か月、彼から連絡がない）" },
  { label: "【英語・高校受験】", q: "「keep up with 〜」の意味は？", choices: ["〜と連絡を絶つ", "〜と仲直りする", "〜に遅れずについていく"], answer: 2, explain: "It's hard to keep up with the class.（授業についていくのは大変だ）" },
  { label: "【英語・高校受験】", q: "「lead to 〜」の意味は？", choices: ["〜につながる、〜をもたらす", "〜を取り除く", "〜に似ている"], answer: 0, explain: "Hard work leads to success.（努力は成功につながる）" },
  { label: "【英語・高校受験】", q: "「point out 〜」の意味は？", choices: ["〜を取り出す", "〜を指摘する", "〜を消す"], answer: 1, explain: "She pointed out my mistake.（彼女は私の間違いを指摘した）" },
  { label: "【英語・高校受験】", q: "「pass away」の意味は？", choices: ["通り過ぎる", "合格する", "亡くなる"], answer: 2, explain: "His grandfather passed away last year.（彼の祖父は去年亡くなった）。die のていねいな言い方" },
  { label: "【英語・高校受験】", q: "「run into 〜」の意味は？", choices: ["〜に偶然出会う", "〜に走って入る", "〜を使い果たす"], answer: 0, explain: "I ran into my teacher at the station.（駅で先生にばったり会った）" },
  { label: "【英語・高校受験】", q: "「see off 〜」の意味は？", choices: ["〜を見逃す", "〜を見送る", "〜を見直す"], answer: 1, explain: "I went to the airport to see him off.（彼を見送りに空港へ行った）" },
  { label: "【英語・高校受験】", q: "「stay up」の意味は？", choices: ["滞在を延ばす", "立ち上がる", "夜更かしする"], answer: 2, explain: "I stayed up until midnight.（私は夜中まで起きていた）" },
  { label: "【英語・高校受験】", q: "「throw away 〜」の意味は？", choices: ["〜を捨てる", "〜を投げ返す", "〜を受け止める"], answer: 0, explain: "Don't throw away your trash here.（ここにごみを捨てないで）" },
  { label: "【英語・高校受験】", q: "「try on 〜」の意味は？", choices: ["〜を試す", "〜を身につけている", "〜を試着する"], answer: 2, explain: "May I try on this jacket?（このジャケットを試着してもいいですか）" },
  { label: "【英語・高校受験】", q: "「work out」の意味は？", choices: ["〜を働かせすぎる", "うまくいく、運動する", "〜を外で働く"], answer: 1, explain: "Everything worked out well.（すべてうまくいった）。I work out at the gym.（ジムで運動している）" },
  { label: "【英語・高校受験】", q: "「according to 〜」の意味は？", choices: ["〜によると", "〜に賛成して", "〜に近づいて"], answer: 0, explain: "According to the news, it will snow tonight.（ニュースによると、今夜は雪だ）" },
  { label: "【英語・高校受験】", q: "「in spite of 〜」の意味は？", choices: ["〜のおかげで", "〜にもかかわらず", "〜のかわりに"], answer: 1, explain: "We went out in spite of the rain.（雨にもかかわらず私たちは出かけた）。後ろは名詞" },
  { label: "【英語・高校受験】", q: "「by oneself」の意味は？", choices: ["ひとりで、自力で", "自分自身を", "自分から先に"], answer: 0, explain: "She lives by herself.（彼女はひとりで暮らしている）" },
  { label: "【英語・高校受験】", q: "「for a while」の意味は？", choices: ["ひさしぶりに", "一度に", "しばらくの間"], answer: 2, explain: "Let's rest for a while.（しばらく休もう）" },
  { label: "【英語・高校受験】", q: "「in charge of 〜」の意味は？", choices: ["〜を請求して", "〜を担当して、責任をもって", "〜を充電して"], answer: 1, explain: "Who is in charge of this project?（このプロジェクトの担当は誰ですか）" },
  { label: "【英語・高校受験】", q: "「out of order」の意味は？", choices: ["故障中で", "順番どおりに", "注文して"], answer: 0, explain: "The elevator is out of order.（エレベーターは故障中だ）" },
  { label: "【英語・高校受験】", q: "「one by one」の意味は？", choices: ["一対一で", "ひとりきりで", "ひとつずつ"], answer: 2, explain: "Enter the room one by one.（ひとりずつ部屋に入りなさい）" },
  { label: "【英語・高校受験】", q: "「a number of 〜」の意味は？", choices: ["〜の数", "たくさんの〜", "〜番目の"], answer: 1, explain: "A number of students were absent.（多くの生徒が欠席した）。後ろは複数形。the number of 〜 は「〜の数」" },
  { label: "【英語・高校受験】", q: "I have lived here ( ) 2015. 空所に入る語は？", choices: ["for", "since", "from"], answer: 1, explain: "since は「〜以来」で、後ろに過去の時点を置く。for は「〜のあいだ」で、期間を置く" },
  { label: "【英語・高校受験】", q: "She has been sick ( ) three days. 空所に入る語は？", choices: ["since", "from", "for"], answer: 2, explain: "for ＋ 期間（three days）で「3日間」。（彼女は3日間ずっと具合が悪い）" },
  { label: "【英語・高校受験】", q: "He enjoys ( ) the guitar. 空所に入る語（句）は？", choices: ["play", "playing", "to play"], answer: 1, explain: "enjoy の後ろは動名詞（〜ing）。（彼はギターを弾くことを楽しんでいる）" },
  { label: "【英語・高校受験】", q: "Would you mind ( ) the window? 空所に入る語（句）は？", choices: ["to open", "opened", "opening"], answer: 2, explain: "mind の後ろは動名詞（〜ing）。（窓を開けていただけませんか）" },
  { label: "【英語・高校受験】", q: "He stopped ( ) a cup of coffee. 空所に入る語（句）は？", choices: ["to drink", "drinking", "drank"], answer: 0, explain: "stop to 〜 は「〜するために立ち止まる」、stop 〜ing は「〜するのをやめる」。（彼はコーヒーを飲むために立ち止まった）" },
  { label: "【英語・高校受験】", q: "He ( ) me that he was busy. 空所に入る語は？", choices: ["said", "told", "spoke"], answer: 1, explain: "tell A that 〜 で「Aに〜と言う」。say は、後ろに「人」を直接置かない" },
  { label: "【英語・高校受験】", q: "I ( ) to music every night. 空所に入る語は？", choices: ["hear", "watch", "listen"], answer: 2, explain: "listen to 〜 は「（注意して）〜を聞く」。hear は、自然に耳に入ってくるときに使う" },
  { label: "【英語・高校受験】", q: "Can you ( ) me a favor? 空所に入る語は？", choices: ["do", "make", "give"], answer: 0, explain: "do A a favor で「Aの頼みを聞く、Aに親切にする」。（お願いを聞いてくれませんか）" },
  { label: "【英語・高校受験】", q: "The woman ( ) lives next door is a doctor. 空所に入る語は？", choices: ["which", "who", "whose"], answer: 1, explain: "先行詞が人で、後ろに動詞が続くので who（主格）を使う。（隣に住んでいる女性は医者だ）" },
  { label: "【英語・高校受験】", q: "The sun ( ) in the east. 空所に入る語は？", choices: ["raises", "arises", "rises"], answer: 2, explain: "rise は「上がる」（自動詞）、raise は「〜を上げる」（他動詞）。（太陽は東から昇る）" },

// ===== 英語（高校受験）401〜500問 =====
  { label: "【英語・高校受験】", q: "「energy」の意味は？", choices: ["エネルギー、活力", "技術者", "敵"], answer: 0, explain: "Solar energy is clean.（太陽エネルギーはクリーンだ）。「活力、元気」の意味もある" },
  { label: "【英語・高校受験】", q: "「furniture」の意味は？", choices: ["毛皮", "家具", "将来"], answer: 1, explain: "We bought new furniture.（新しい家具を買った）。数えられない名詞なので、furnitures とは言わない" },
  { label: "【英語・高校受験】", q: "「expense」の意味は？", choices: ["専門家", "経験", "費用"], answer: 2, explain: "Travel expenses are paid by the company.（旅費は会社が払う）" },
  { label: "【英語・高校受験】", q: "「ceremony」の意味は？", choices: ["式典、儀式", "世紀", "証明書"], answer: 0, explain: "the graduation ceremony（卒業式）" },
  { label: "【英語・高校受験】", q: "「patient」の意味は？", choices: ["通行人", "患者、辛抱強い", "市民"], answer: 1, explain: "The doctor is kind to every patient.（その医者はどの患者にも親切だ）。形容詞で「辛抱強い」の意味もある" },
  { label: "【英語・高校受験】", q: "「material」の意味は？", choices: ["数学", "記念", "材料、素材"], answer: 2, explain: "What material is this bag made of?（このかばんは何の素材でできていますか）" },
  { label: "【英語・高校受験】", q: "「chance」の意味は？", choices: ["変化", "機会、見込み", "選択"], answer: 1, explain: "I got a chance to study abroad.（留学する機会を得た）。Is there a chance of rain?（雨が降る見込みはある？）" },
  { label: "【英語・高校受験】", q: "「profit」の意味は？", choices: ["教授", "預言者", "利益"], answer: 2, explain: "The company made a big profit.（その会社は大きな利益を上げた）" },
  { label: "【英語・高校受験】", q: "「poverty」の意味は？", choices: ["貧困", "権力", "人口"], answer: 0, explain: "Many people live in poverty.（多くの人が貧困の中で暮らしている）" },
  { label: "【英語・高校受験】", q: "「palace」の意味は？", choices: ["場所", "宮殿", "舞台"], answer: 1, explain: "The king lives in a palace.（王は宮殿に住んでいる）" },
  { label: "【英語・高校受験】", q: "「anniversary」の意味は？", choices: ["年齢", "動物", "記念日"], answer: 2, explain: "It's our wedding anniversary today.（今日は私たちの結婚記念日だ）" },
  { label: "【英語・高校受験】", q: "「battery」の意味は？", choices: ["戦闘", "電池", "野球選手"], answer: 1, explain: "The battery is dead.（電池が切れている）" },
  { label: "【英語・高校受験】", q: "「bargain」の意味は？", choices: ["お買い得品、掘り出し物", "禁止", "大工"], answer: 0, explain: "This jacket was a bargain.（このジャケットはお買い得だった）" },
  { label: "【英語・高校受験】", q: "「breath」の意味は？", choices: ["パン", "息、呼吸", "兄弟"], answer: 1, explain: "Take a deep breath.（深呼吸して）。動詞 breathe は /briːð/ と発音する" },
  { label: "【英語・高校受験】", q: "「couple」の意味は？", choices: ["いとこ", "地方", "夫婦、カップル"], answer: 2, explain: "A young couple lives next door.（若い夫婦が隣に住んでいる）。a couple of 〜 は「2、3の〜」" },
  { label: "【英語・高校受験】", q: "「contest」の意味は？", choices: ["コンテスト、競争", "内容", "大陸"], answer: 0, explain: "She won the speech contest.（彼女はスピーチコンテストで優勝した）" },
  { label: "【英語・高校受験】", q: "「fuel」の意味は？", choices: ["果物", "燃料", "楽しみ"], answer: 1, explain: "The car ran out of fuel.（車は燃料が切れた）" },
  { label: "【英語・高校受験】", q: "「harbor」の意味は？", choices: ["硬さ", "収穫", "港"], answer: 2, explain: "The ship entered the harbor.（その船は港に入った）" },
  { label: "【英語・高校受験】", q: "「cover」の意味は？", choices: ["〜を覆う", "〜を発見する", "〜を数える"], answer: 0, explain: "Snow covered the mountain.（雪が山を覆った）。be covered with 〜 は「〜で覆われている」" },
  { label: "【英語・高校受験】", q: "「divide」の意味は？", choices: ["〜を決める", "〜を分ける", "〜を描写する"], answer: 1, explain: "Divide the cake into four pieces.（ケーキを4つに分けなさい）" },
  { label: "【英語・高校受験】", q: "「〜を注ぐ」を表す英単語は？", choices: ["push", "pull", "pour"], answer: 2, explain: "She poured tea into the cup.（彼女はカップにお茶を注いだ）。push は「押す」、pull は「引く」" },
  { label: "【英語・高校受験】", q: "「shake」の意味は？", choices: ["〜を振る、揺れる", "〜を作る", "〜を分け合う"], answer: 0, explain: "Shake the bottle well.（ボトルをよく振って）。shake hands で「握手する」" },
  { label: "【英語・高校受験】", q: "「shout」の意味は？", choices: ["〜を見せる", "〜を撃つ", "叫ぶ、大声で言う"], answer: 2, explain: "Don't shout at me.（私に怒鳴らないで）" },
  { label: "【英語・高校受験】", q: "「wonder」の意味は？", choices: ["〜に勝つ", "〜かなと思う", "〜を待つ"], answer: 1, explain: "I wonder what he is doing now.（彼は今何をしているのかな）" },
  { label: "【英語・高校受験】", q: "「worry」の意味は？", choices: ["〜を後悔する", "〜を祝う", "心配する"], answer: 2, explain: "Don't worry about me.（私のことは心配しないで）。be worried about 〜 も同じ意味" },
  { label: "【英語・高校受験】", q: "「employ」の意味は？", choices: ["〜を雇う", "〜を楽しむ", "〜を空にする"], answer: 0, explain: "The company employs 500 people.（その会社は500人を雇っている）" },
  { label: "【英語・高校受験】", q: "「reach」の意味は？", choices: ["〜を教える", "〜に着く、〜に手が届く", "〜を見つける"], answer: 1, explain: "We reached the top at noon.（私たちは正午に頂上に着いた）。reach の後ろに to は不要" },
  { label: "【英語・高校受験】", q: "「offer」の意味は？", choices: ["〜を断る", "〜を申し出る、提供する", "〜を無視する"], answer: 1, explain: "He offered me a ride.（彼は車で送ろうと申し出てくれた）" },
  { label: "【英語・高校受験】", q: "「obey」の意味は？", choices: ["〜を観察する", "〜に従う", "〜を拒む"], answer: 1, explain: "Children should obey their parents.（子どもは親に従うべきだ）" },
  { label: "【英語・高校受験】", q: "「quit」の意味は？", choices: ["〜を静かにする", "〜を引用する", "〜をやめる"], answer: 2, explain: "He quit smoking last year.（彼は去年タバコをやめた）。活用は quit - quit - quit" },
  { label: "【英語・高校受験】", q: "「rush」の意味は？", choices: ["〜を押しつぶす", "急ぐ、突進する", "〜を残す"], answer: 1, explain: "Don't rush. We have plenty of time.（急がなくていいよ。時間はたっぷりある）" },
  { label: "【英語・高校受験】", q: "「donate」の意味は？", choices: ["〜を寄付する", "〜を支配する", "〜を2倍にする"], answer: 0, explain: "She donated money to the hospital.（彼女は病院にお金を寄付した）。名詞は donation" },
  { label: "【英語・高校受験】", q: "「bitter」の意味は？", choices: ["苦い", "大きい", "美しい"], answer: 0, explain: "This coffee is too bitter.（このコーヒーは苦すぎる）" },
  { label: "【英語・高校受験】", q: "「thick」の意味は？", choices: ["薄い", "厚い、太い", "のどが渇いた"], answer: 1, explain: "a thick book（厚い本）。反対は thin" },
  { label: "【英語・高校受験】", q: "「tiny」の意味は？", choices: ["ひどい", "つまらない", "とても小さい"], answer: 2, explain: "a tiny insect（とても小さい虫）" },
  { label: "【英語・高校受験】", q: "「private」の意味は？", choices: ["公共の", "個人的な、私的な", "最初の"], answer: 1, explain: "This is private information.（これは個人情報だ）。反対は public" },
  { label: "【英語・高校受験】", q: "「visible」の意味は？", choices: ["訪問の", "不可能な", "目に見える"], answer: 2, explain: "Stars are visible at night.（夜は星が見える）。反対は invisible" },
  { label: "【英語・高校受験】", q: "「native」の意味は？", choices: ["生まれた土地の、母国の", "自然の", "新しい"], answer: 0, explain: "a native speaker of English（英語を母語とする人）" },
  { label: "【英語・高校受験】", q: "「annual」の意味は？", choices: ["動物の", "年配の", "毎年の"], answer: 2, explain: "an annual event（毎年の行事）" },
  { label: "【英語・高校受験】", q: "「rough」の意味は？", choices: ["丸い", "荒い、ざらざらした", "まっすぐな"], answer: 1, explain: "The sea was rough.（海は荒れていた）。発音は /rʌf/" },
  { label: "【英語・高校受験】", q: "「mild」の意味は？", choices: ["穏やかな、温和な", "野生の", "古い"], answer: 0, explain: "a mild winter（穏やかな冬）" },
  { label: "【英語・高校受験】", q: "「fair」の意味は？", choices: ["遠い", "農場の", "公平な、正当な"], answer: 2, explain: "It's not fair!（それは不公平だ）" },
  { label: "【英語・高校受験】", q: "「indeed」の意味は？", choices: ["とにかく", "本当に、実際", "まもなく"], answer: 1, explain: "Thank you very much indeed.（本当にありがとうございます）" },
  { label: "【英語・高校受験】", q: "「moreover」の意味は？", choices: ["そのうえ、さらに", "それにもかかわらず", "それゆえに"], answer: 0, explain: "The room is cheap. Moreover, it's clean.（その部屋は安いし、そのうえ清潔だ）" },
  { label: "【英語・高校受験】", q: "「nowadays」の意味は？", choices: ["毎日", "将来", "最近では、このごろは"], answer: 2, explain: "Nowadays, many people use smartphones.（最近は多くの人がスマホを使っている）" },
  { label: "【英語・高校受験】", q: "「mostly」の意味は？", choices: ["全部", "たいてい、おもに", "ときどき"], answer: 1, explain: "The students are mostly girls.（生徒はおもに女の子だ）" },
  { label: "【英語・高校受験】", q: "「break out」の意味は？", choices: ["（火事・戦争などが）起こる", "〜を借りる", "〜を取り除く"], answer: 0, explain: "A fire broke out last night.（昨夜、火事が起こった）" },
  { label: "【英語・高校受験】", q: "「calm down」の意味は？", choices: ["〜を調べる", "〜を暖める", "落ち着く"], answer: 2, explain: "Calm down. Everything is OK.（落ち着いて。大丈夫だよ）" },
  { label: "【英語・高校受験】", q: "「cut down on 〜」の意味は？", choices: ["〜を切り取る", "〜を減らす", "〜を増やす"], answer: 1, explain: "You should cut down on sugar.（砂糖を控えたほうがいい）" },
  { label: "【英語・高校受験】", q: "「fill out 〜」の意味は？", choices: ["〜を空にする", "〜に記入する", "〜をそろえる"], answer: 1, explain: "Please fill out this form.（この用紙に記入してください）" },
  { label: "【英語・高校受験】", q: "「get used to 〜」の意味は？", choices: ["〜を使い果たす", "〜を中古で買う", "〜に慣れる"], answer: 2, explain: "I got used to the new school.（新しい学校に慣れた）。get used to 〜ing の形でも使う" },
  { label: "【英語・高校受験】", q: "「hurry up」の意味は？", choices: ["遅れる", "〜を待つ", "急ぐ"], answer: 2, explain: "Hurry up, or we'll be late.（急いで、そうしないと遅れるよ）" },
  { label: "【英語・高校受験】", q: "「pick out 〜」の意味は？", choices: ["〜を取り除く", "〜を選び出す", "〜を引き出す"], answer: 1, explain: "She picked out a red dress.（彼女は赤いドレスを選んだ）" },
  { label: "【英語・高校受験】", q: "「put up with 〜」の意味は？", choices: ["〜を我慢する", "〜を設置する", "〜を身につける"], answer: 0, explain: "I can't put up with this noise.（この騒音は我慢できない）" },
  { label: "【英語・高校受験】", q: "「run away」の意味は？", choices: ["逃げ出す", "走って戻る", "走って入る"], answer: 0, explain: "The cat ran away from the dog.（猫は犬から逃げ出した）" },
  { label: "【英語・高校受験】", q: "「set out」の意味は？", choices: ["〜を片づける", "〜を読み上げる", "出発する"], answer: 2, explain: "We set out for Kyoto early in the morning.（私たちは朝早く京都へ出発した）" },
  { label: "【英語・高校受験】", q: "「show off 〜」の意味は？", choices: ["〜を見せびらかす", "〜を案内する", "〜を取り消す"], answer: 0, explain: "He likes to show off his new car.（彼は新しい車を見せびらかすのが好きだ）" },
  { label: "【英語・高校受験】", q: "「stand for 〜」の意味は？", choices: ["〜を表す、意味する", "〜に立ち向かう", "〜から離れる"], answer: 0, explain: "UN stands for United Nations.（UNは United Nations の略だ）" },
  { label: "【英語・高校受験】", q: "「take over 〜」の意味は？", choices: ["〜を引き継ぐ", "〜を持ち帰る", "〜を取り戻す"], answer: 0, explain: "She took over the shop from her father.（彼女は父から店を引き継いだ）" },
  { label: "【英語・高校受験】", q: "「turn out」の意味は？", choices: ["〜に変わる", "〜を断る", "〜だとわかる、結局〜になる"], answer: 2, explain: "It turned out that he was right.（結局、彼が正しいとわかった）" },
  { label: "【英語・高校受験】", q: "「watch out」の意味は？", choices: ["気をつける、用心する", "〜を見張る", "〜を見に行く"], answer: 0, explain: "Watch out for cars.（車に気をつけて）。watch out for 〜 の形でよく使う" },
  { label: "【英語・高校受験】", q: "「write down 〜」の意味は？", choices: ["〜を書き留める", "〜を書き直す", "〜を書き写す"], answer: 0, explain: "Write down your name here.（ここに名前を書きとめてください）" },
  { label: "【英語・高校受験】", q: "「look up to 〜」の意味は？", choices: ["〜を軽蔑する", "〜を調べる", "〜を尊敬する"], answer: 2, explain: "I look up to my father.（私は父を尊敬している）。反対は look down on 〜（〜を見下す）" },
  { label: "【英語・高校受験】", q: "「get together」の意味は？", choices: ["〜を手に入れる", "集まる", "仲直りする"], answer: 1, explain: "Let's get together this weekend.（今週末に集まろう）" },
  { label: "【英語・高校受験】", q: "「hand out 〜」の意味は？", choices: ["〜を提出する", "〜を配る", "〜を手伝う"], answer: 1, explain: "The teacher handed out the test.（先生はテスト用紙を配った）" },
  { label: "【英語・高校受験】", q: "「take up 〜」の意味は？", choices: ["〜をやめる", "〜を断る", "〜（趣味など）を始める"], answer: 2, explain: "I took up tennis last year.（私は去年テニスを始めた）" },
  { label: "【英語・高校受験】", q: "「thanks to 〜」の意味は？", choices: ["〜のおかげで", "〜に感謝して", "〜に反対して"], answer: 0, explain: "Thanks to your help, I finished the work.（あなたのおかげで仕事を終えられた）" },
  { label: "【英語・高校受験】", q: "「in addition to 〜」の意味は？", choices: ["〜の代わりに", "〜に加えて", "〜のおかげで"], answer: 1, explain: "In addition to English, she speaks French.（英語に加えて、彼女はフランス語も話す）" },
  { label: "【英語・高校受験】", q: "「in case of 〜」の意味は？", choices: ["〜の代わりに", "〜に加えて", "〜の場合には"], answer: 2, explain: "In case of fire, use the stairs.（火事の場合は、階段を使ってください）" },
  { label: "【英語・高校受験】", q: "「on foot」の意味は？", choices: ["足元に", "足をそろえて", "徒歩で"], answer: 2, explain: "I go to school on foot.（私は歩いて通学している）" },
  { label: "【英語・高校受験】", q: "「again and again」の意味は？", choices: ["やがて", "何度も、繰り返し", "突然"], answer: 1, explain: "I read the book again and again.（私はその本を何度も読んだ）" },
  { label: "【英語・高校受験】", q: "「all the time」の意味は？", choices: ["いつも、ずっと", "時間をかけて", "ちょうどよい時に"], answer: 0, explain: "She talks about him all the time.（彼女はいつも彼のことを話している）" },
  { label: "【英語・高校受験】", q: "This bag is ( ) than that one. 空所に入る語（句）は？", choices: ["heavy", "more heavy", "heavier"], answer: 2, explain: "短い形容詞の比較級は、語尾に -er をつける。（このかばんはあれより重い）。heavy は y を i に変えて heavier" },
  { label: "【英語・高校受験】", q: "She is the ( ) student in my class. 空所に入る語は？", choices: ["tall", "taller", "tallest"], answer: 2, explain: "the の後ろの最上級は -est をつける。（彼女はクラスでいちばん背が高い生徒だ）" },
  { label: "【英語・高校受験】", q: "He is as ( ) as his brother. 空所に入る語（句）は？", choices: ["tall", "taller", "more tall"], answer: 0, explain: "as ＋ 原級 ＋ as 〜 で「〜と同じくらい…」。（彼は兄と同じくらい背が高い）" },
  { label: "【英語・高校受験】", q: "The more you practice, the ( ) you will play. 空所に入る語は？", choices: ["better", "good", "best"], answer: 0, explain: "the ＋ 比較級, the ＋ 比較級 で「〜すればするほど…」。（練習すればするほど、上手になる）" },
  { label: "【英語・高校受験】", q: "English is ( ) in many countries. 空所に入る語は？", choices: ["spoken", "speaking", "spoke"], answer: 0, explain: "受け身は be動詞 ＋ 過去分詞。（英語は多くの国で話されている）。speak - spoke - spoken" },
  { label: "【英語・高校受験】", q: "Have you ( ) been to Hawaii? 空所に入る語は？", choices: ["ever", "still", "ago"], answer: 0, explain: "現在完了の疑問文で「今までに」は ever。（ハワイに行ったことがありますか）" },
  { label: "【英語・高校受験】", q: "I have ( ) finished my homework. 空所に入る語は？", choices: ["just", "ago", "yet"], answer: 0, explain: "have just ＋ 過去分詞 で「ちょうど〜したところだ」。（宿題をちょうど終えたところだ）" },
  { label: "【英語・高校受験】", q: "I haven't eaten lunch ( ). 空所に入る語は？", choices: ["already", "just", "yet"], answer: 2, explain: "否定文の「まだ（〜ない）」は yet。（まだ昼食を食べていない）。already は肯定文で「もう」" },
  { label: "【英語・高校受験】", q: "I want you ( ) me with this. 空所に入る語（句）は？", choices: ["help", "to help", "helping"], answer: 1, explain: "want A to 〜 で「Aに〜してほしい」。（これを手伝ってほしい）" },
  { label: "【英語・高校受験】", q: "My mother let me ( ) out at night. 空所に入る語（句）は？", choices: ["go", "to go", "going"], answer: 0, explain: "let A ＋ 動詞の原形 で「Aに〜させる（許す）」。（母は私が夜に外出するのを許してくれた）" },
  { label: "【英語・高校受験】", q: "The movie made me ( ). 空所に入る語（句）は？", choices: ["cry", "to cry", "crying"], answer: 0, explain: "make A ＋ 動詞の原形 で「Aを〜させる」。（その映画を見て泣いた）" },
  { label: "【英語・高校受験】", q: "It is hard ( ) me to get up early. 空所に入る語は？", choices: ["of", "for", "to"], answer: 1, explain: "It is 〜 for A to … で「Aが…するのは〜だ」。（私にとって早起きは難しい）" },
  { label: "【英語・高校受験】", q: "He is old ( ) to drive a car. 空所に入る語は？", choices: ["enough", "too", "very"], answer: 0, explain: "形容詞 ＋ enough to 〜 で「〜するのに十分…だ」。（彼は車を運転できる年齢だ）" },
  { label: "【英語・高校受験】", q: "It was ( ) cold that we stayed home. 空所に入る語は？", choices: ["so", "such", "too"], answer: 0, explain: "so ＋ 形容詞 ＋ that 〜 で「とても…なので〜」。（とても寒かったので、私たちは家にいた）" },
  { label: "【英語・高校受験】", q: "It was ( ) a nice day. 空所に入る語は？", choices: ["so", "such", "too"], answer: 1, explain: "such ＋ a ＋ 形容詞 ＋ 名詞 の語順。（とてもすてきな日だった）。so は形容詞の前に置く" },
  { label: "【英語・高校受験】", q: "If it ( ) tomorrow, we will stay home. 空所に入る語（句）は？", choices: ["rain", "rains", "will rain"], answer: 1, explain: "if の中は、未来のことでも現在形にする。（もし明日雨が降ったら、家にいよう）" },
  { label: "【英語・高校受験】", q: "If I ( ) you, I would take the job. 空所に入る語は？", choices: ["am", "are", "were"], answer: 2, explain: "仮定法過去では、主語が I でも be動詞は were を使う。（私があなたなら、その仕事を引き受ける）" },
  { label: "【英語・高校受験】", q: "I wish I ( ) a car. 空所に入る語（句）は？", choices: ["have", "had", "will have"], answer: 1, explain: "I wish ＋ 過去形 で「〜ならいいのに」（現実と違う願い）。（車を持っていたらなあ）" },
  { label: "【英語・高校受験】", q: "This is the book ( ) I bought yesterday. 空所に入る語は？", choices: ["who", "which", "whose"], answer: 1, explain: "先行詞が「物」で、後ろに「主語＋動詞」が続くので which（目的格）。（これは私が昨日買った本だ）" },
  { label: "【英語・高校受験】", q: "I know a boy ( ) father is a pilot. 空所に入る語は？", choices: ["who", "which", "whose"], answer: 2, explain: "「その〜の」の意味で、後ろに名詞が続くので whose。（父親がパイロットの男の子を知っている）" },
  { label: "【英語・高校受験】", q: "I don't know ( ) he said. 空所に入る語は？", choices: ["what", "that", "whose"], answer: 0, explain: "what he said で「彼が言ったこと」。（彼が何を言ったのかわからない）" },
  { label: "【英語・高校受験】", q: "He is good at ( ) pictures. 空所に入る語（句）は？", choices: ["draw", "drawing", "to draw"], answer: 1, explain: "前置詞（at）の後ろは動名詞（〜ing）。（彼は絵をかくのが得意だ）" },
  { label: "【英語・高校受験】", q: "How about ( ) to the park? 空所に入る語（句）は？", choices: ["go", "to go", "going"], answer: 2, explain: "How about 〜ing? で「〜するのはどう？」。（公園に行くのはどう？）" },
  { label: "【英語・高校受験】", q: "Thank you for ( ) me to your party. 空所に入る語（句）は？", choices: ["invite", "inviting", "to invite"], answer: 1, explain: "Thank you for 〜ing で「〜してくれてありがとう」。（パーティーに招待してくれてありがとう）" },
  { label: "【英語・高校受験】", q: "He left without ( ) goodbye. 空所に入る語（句）は？", choices: ["say", "to say", "saying"], answer: 2, explain: "without の後ろは動名詞（〜ing）。（彼はさよならも言わずに去った）" },
  { label: "【英語・高校受験】", q: "The boy ( ) over there is my brother. 空所に入る語は？", choices: ["stand", "stood", "standing"], answer: 2, explain: "名詞を後ろから説明する現在分詞（〜ing）で「〜している」。（あそこに立っている男の子は私の弟だ）" },
  { label: "【英語・高校受験】", q: "This is a book ( ) in English. 空所に入る語は？", choices: ["write", "wrote", "written"], answer: 2, explain: "名詞を後ろから説明する過去分詞で「〜された」。（これは英語で書かれた本だ）" },
  { label: "【英語・高校受験】", q: "You are a student, ( )? 空所に入る語（句）は？", choices: ["are you", "don't you", "aren't you"], answer: 2, explain: "付加疑問文は、肯定文なら否定の形を、否定文なら肯定の形をつける。You are 〜 には aren't you" },


  
  { label: "【英語・高校在学】", q: "「contribute」の意味は？", choices: ["〜に貢献する、寄付する", "〜を競争する", "〜を含む"], answer: 0, explain: "She contributed a lot to the team.（彼女はチームに大いに貢献した）。名詞は contribution。contribute to 〜 の形でよく使う" },
  { label: "【英語・高校在学】", q: "「demonstrate」の意味は？", choices: ["〜を隠す", "〜を実演する、証明する", "〜を要求する"], answer: 1, explain: "The experiment demonstrated that the theory was correct.（その実験は理論が正しいことを証明した）。名詞は demonstration" },
  { label: "【英語・高校在学】", q: "「emphasize」の意味は？", choices: ["〜を空にする", "〜に共感する", "〜を強調する"], answer: 2, explain: "The teacher emphasized the importance of practice.（先生は練習の大切さを強調した）。名詞は emphasis" },
  { label: "【英語・高校在学】", q: "「estimate」の意味は？", choices: ["〜を尊重する", "〜を設立する", "〜を見積もる、推定する"], answer: 2, explain: "They estimate the cost at 5 million yen.（費用は500万円と見積もられている）" },
  { label: "【英語・高校在学】", q: "「evaluate」の意味は？", choices: ["〜を避ける", "〜を評価する", "〜を排除する"], answer: 1, explain: "Teachers evaluate students' work fairly.（教師は生徒の作品を公平に評価する）。名詞は evaluation" },
  { label: "【英語・高校在学】", q: "「indicate」の意味は？", choices: ["〜を示す、指し示す", "〜を無視する", "〜を説得する"], answer: 0, explain: "The data indicates that sales are rising.（データは売り上げが伸びていることを示している）" },
  { label: "【英語・高校在学】", q: "「reveal」の意味は？", choices: ["〜を隠す", "〜を繰り返す", "〜を明らかにする"], answer: 2, explain: "The survey revealed a surprising result.（調査は驚くべき結果を明らかにした）" },
  { label: "【英語・高校在学】", q: "「conclude」の意味は？", choices: ["〜を含む", "結論づける、〜を終える", "〜を集中させる"], answer: 1, explain: "We concluded that the plan was too risky.（私たちはその計画は危険すぎると結論づけた）。名詞は conclusion" },
  { label: "【英語・高校在学】", q: "「acquire」の意味は？", choices: ["〜を獲得する、身につける", "〜を要求する", "〜に同意する"], answer: 0, explain: "He acquired a new skill.（彼は新しい技術を身につけた）。名詞は acquisition" },
  { label: "【英語・高校在学】", q: "「adapt」の意味は？", choices: ["〜を採用する", "適応する、〜を適応させる", "〜を認める"], answer: 1, explain: "Animals adapt to their environment.（動物は環境に適応する）。adapt to 〜 の形で使う。adopt（採用する）と混同しないこと" },
  { label: "【英語・高校在学】", q: "「assume」の意味は？", choices: ["〜を保証する", "〜を達成する", "〜を仮定する、思い込む"], answer: 2, explain: "I assumed he would come.（彼は来るものと思い込んでいた）" },
  { label: "【英語・高校在学】", q: "「maintain」の意味は？", choices: ["〜を混ぜる", "〜を維持する", "〜を拒否する"], answer: 1, explain: "It is hard to maintain a healthy lifestyle.（健康的な生活を維持するのは難しい）。名詞は maintenance" },
  { label: "【英語・高校在学】", q: "「reflect」の意味は？", choices: ["〜を拒絶する", "〜を補充する", "〜を反映する、熟考する"], answer: 2, explain: "The result reflects his effort.（その結果は彼の努力を反映している）。reflect on 〜 で「〜をじっくり考える」" },
  { label: "【英語・高校在学】", q: "「enhance」の意味は？", choices: ["〜を高める、強化する", "〜を入れる", "〜を楽しむ"], answer: 0, explain: "Music can enhance your mood.（音楽は気分を高めてくれる）" },
  { label: "【英語・高校在学】", q: "「inevitable」の意味は？", choices: ["目に見えない", "避けられない", "本質的な"], answer: 1, explain: "Change is inevitable.（変化は避けられない）。副詞は inevitably" },
  { label: "【英語・高校在学】", q: "「ambiguous」の意味は？", choices: ["野心的な", "明確な", "あいまいな、多義的な"], answer: 2, explain: "His answer was ambiguous.（彼の答えはあいまいだった）。名詞は ambiguity" },
  { label: "【英語・高校在学】", q: "「sufficient」の意味は？", choices: ["十分な", "効率的な", "突然の"], answer: 0, explain: "We don't have sufficient time.（十分な時間がない）。反対は insufficient" },
  { label: "【英語・高校在学】", q: "「reluctant」の意味は？", choices: ["信頼できる", "気が進まない", "関連する"], answer: 1, explain: "She was reluctant to speak in public.（彼女は人前で話すのに気が進まなかった）。be reluctant to 〜 の形で使う" },
  { label: "【英語・高校在学】", q: "「objective」（形容詞）の意味は？", choices: ["主観的な", "客観的な", "反対の"], answer: 1, explain: "Try to give an objective opinion.（客観的な意見を述べるようにしなさい）。反対は subjective。名詞では「目的、目標」の意味" },
  { label: "【英語・高校在学】", q: "「phenomenon」の意味は？", choices: ["哲学", "現実", "現象"], answer: 2, explain: "El Niño is a natural phenomenon.（エルニーニョは自然現象だ）。複数形は phenomena" },
  { label: "【英語・高校在学】", q: "「hypothesis」の意味は？", choices: ["仮説", "仮面", "理論の証明"], answer: 0, explain: "The scientist tested her hypothesis.（その科学者は自分の仮説を検証した）。複数形は hypotheses" },
  { label: "【英語・高校在学】", q: "「consequence」の意味は？", choices: ["良心", "結果、重大さ", "相談"], answer: 1, explain: "You must accept the consequences.（結果を受け入れなければならない）。as a consequence で「その結果として」" },
  { label: "【英語・高校在学】", q: "「priority」の意味は？", choices: ["特権", "プライバシー", "優先事項"], answer: 2, explain: "Safety is our top priority.（安全が最優先事項だ）。動詞 prioritize は「優先する」" },
  { label: "【英語・高校在学】", q: "「criticism」の意味は？", choices: ["批判、批評", "危機", "循環"], answer: 0, explain: "He didn't accept the criticism.（彼はその批判を受け入れなかった）。動詞は criticize" },
  { label: "【英語・高校在学】", q: "「resource」の意味は？", choices: ["決心", "尊敬", "資源"], answer: 2, explain: "Water is a precious natural resource.（水は貴重な天然資源だ）。ふつう複数形 resources で使う" },
  { label: "【英語・高校在学】", q: "「tendency」の意味は？", choices: ["緊張", "意図", "傾向"], answer: 2, explain: "He has a tendency to talk too much.（彼は話しすぎる傾向がある）。have a tendency to 〜 の形で使う" },
  { label: "【英語・高校在学】", q: "「perspective」の意味は？", choices: ["観点、見通し", "許可", "人格"], answer: 0, explain: "Try to see it from a different perspective.（別の観点から見てみなさい）" },
  { label: "【英語・高校在学】", q: "「sustainable」の意味は？", choices: ["適した", "驚くべき", "持続可能な"], answer: 2, explain: "We need sustainable energy.（持続可能なエネルギーが必要だ）。SDGs は Sustainable Development Goals の略" },
  { label: "【英語・高校在学】", q: "「substantial」の意味は？", choices: ["補助的な", "かなりの、実質的な", "主題の"], answer: 1, explain: "There was a substantial increase in prices.（物価がかなり上昇した）" },
  { label: "【英語・高校在学】", q: "「approximately」の意味は？", choices: ["おおよそ", "適切に", "明らかに"], answer: 0, explain: "The trip takes approximately two hours.（その旅はおよそ2時間かかる）。about と同じ意味で、よりかたい語" },
  { label: "【英語・高校在学】", q: "「nevertheless」の意味は？", choices: ["さらに", "その結果", "それにもかかわらず"], answer: 2, explain: "It was raining. Nevertheless, we went out.（雨だった。それにもかかわらず私たちは出かけた）" },
  { label: "【英語・高校在学】", q: "「consequently」の意味は？", choices: ["同時に", "その結果として", "幸運にも"], answer: 1, explain: "He didn't study. Consequently, he failed the exam.（彼は勉強しなかった。その結果、試験に落ちた）" },
  { label: "【英語・高校在学】", q: "「whereas」の意味は？", choices: ["〜するときはいつも", "〜だから", "〜である一方で"], answer: 2, explain: "He is outgoing, whereas his sister is shy.（彼は社交的である一方、妹は内気だ）。対比を表す接続詞" },
  { label: "【英語・高校在学】", q: "「reliable」の意味は？", choices: ["関連する", "信頼できる", "気が進まない"], answer: 1, explain: "He is a reliable friend.（彼は頼りになる友人だ）。動詞は rely（頼る）" },
  { label: "【英語・高校在学】", q: "「appropriate」の意味は？", choices: ["適切な", "おおよその", "承認された"], answer: 0, explain: "Wear appropriate clothes for the interview.（面接にふさわしい服装をしなさい）。反対は inappropriate" },
  { label: "【英語・高校在学】", q: "「account for 〜」の意味は？", choices: ["〜を口座に預ける", "〜を計算に入れない", "〜を説明する、〜の割合を占める"], answer: 2, explain: "Young people account for 30% of the users.（若者が利用者の30％を占める）。Nobody can account for it.（誰もそれを説明できない）" },
  { label: "【英語・高校在学】", q: "The accident ( ) careless driving. 空所に入る語（句）は？", choices: ["resulted in", "resulted from", "resulted with"], answer: 1, explain: "result from 〜 は「〜が原因で起こる」、result in 〜 は「〜という結果になる」。（その事故は不注意な運転が原因だった）" },
  { label: "【英語・高校在学】", q: "「bring about 〜」の意味は？", choices: ["〜を引き起こす", "〜を持ち去る", "〜を育てる"], answer: 0, explain: "The new law brought about big changes.（その新しい法律は大きな変化をもたらした）" },
  { label: "【英語・高校在学】", q: "We regard him ( ) a genius. 空所に入る語は？", choices: ["to be", "as", "for"], answer: 1, explain: "regard A as B で「AをBとみなす」。（私たちは彼を天才だとみなしている）" },
  { label: "【英語・高校在学】", q: "「be responsible for 〜」の意味は？", choices: ["〜に反応する", "〜に興味がある", "〜に責任がある"], answer: 2, explain: "Who is responsible for this mistake?（この間違いは誰の責任ですか）" },
  { label: "【英語・高校在学】", q: "「on behalf of 〜」の意味は？", choices: ["〜に反対して", "〜を代表して、〜に代わって", "〜の側面に"], answer: 1, explain: "I'd like to thank you on behalf of everyone.（皆を代表してお礼を申し上げます）" },
  { label: "【英語・高校在学】", q: "「in terms of 〜」の意味は？", choices: ["〜の点から見ると", "〜の期間で", "〜の条件つきで"], answer: 0, explain: "In terms of price, this one is better.（価格の点では、こちらのほうがよい）" },
  { label: "【英語・高校在学】", q: "「to some extent」の意味は？", choices: ["まったく", "広範囲にわたって", "ある程度は"], answer: 2, explain: "I agree with you to some extent.（ある程度はあなたに賛成だ）" },
  { label: "【英語・高校在学】", q: "「by no means」の意味は？", choices: ["かならず", "決して〜ない", "手段として"], answer: 1, explain: "He is by no means stupid.（彼は決して愚かではない）。否定の強調表現" },
  { label: "【英語・高校在学】", q: "「take A for granted」の意味は？", choices: ["Aを許可する", "Aを与える", "Aを当然のことと思う"], answer: 2, explain: "Don't take your health for granted.（健康を当たり前だと思ってはいけない）" },
  { label: "【英語・高校在学】", q: "「in the long run」の意味は？", choices: ["長い目で見れば", "遠くまで走って", "長距離で"], answer: 0, explain: "Hard work pays off in the long run.（努力は長い目で見れば報われる）" },
  { label: "【英語・高校在学】", q: "「come across 〜」の意味は？", choices: ["〜を横切って走る", "〜に偶然出くわす", "〜を理解させる"], answer: 1, explain: "I came across an old photo in the drawer.（引き出しの中で古い写真を偶然見つけた）" },
  { label: "【英語・高校在学】", q: "If I had known the truth, I ( ) have told you. 空所に入る語は？", choices: ["will", "would", "could not"], answer: 1, explain: "仮定法過去完了は If ＋ 主語 ＋ had ＋ 過去分詞, 主語 ＋ would（could / might）＋ have ＋ 過去分詞。過去の事実と反対の仮定を表す" },
  { label: "【英語・高校在学】", q: "( ) I known the truth, I would have acted differently. 空所に入る語は？", choices: ["Did", "Have", "Had"], answer: 2, explain: "If I had known の if を省略すると倒置が起こり、Had I known になる。（真実を知っていたら、違う行動をとっていただろう）" },
  { label: "【英語・高校在学】", q: "I wish I ( ) studied harder when I was a student. 空所に入る語（句）は？", choices: ["had", "have", "would"], answer: 0, explain: "I wish ＋ 過去完了 で「〜だったらよかったのに」（過去の事実と反対の願望）" },
  { label: "【英語・高校在学】", q: "He talks as if he ( ) everything about it. 空所に入る語は？", choices: ["knows", "knew", "will know"], answer: 1, explain: "as if ＋ 仮定法過去 で「まるで〜であるかのように」。（彼はまるでそれについて何でも知っているかのように話す）" },
  { label: "【英語・高校在学】", q: "( ) along the street, I met an old friend. 空所に入る語は？", choices: ["Walk", "Walking", "Walked"], answer: 1, explain: "分詞構文。「通りを歩いていると」＝ When I was walking along the street。主語（I）が「歩く」側なので現在分詞を使う" },
  { label: "【英語・高校在学】", q: "( ) finished the work, he went home. 空所に入る語は？", choices: ["Finishing", "Having", "Been"], answer: 1, explain: "Having ＋ 過去分詞 は、主節より前に起こったことを表す完了形の分詞構文。（仕事を終えたあと、彼は帰宅した）" },
  { label: "【英語・高校在学】", q: "He sat there with his arms ( ). 空所に入る語は？", choices: ["crossing", "crossed", "cross"], answer: 1, explain: "with ＋ O ＋ 分詞 で「Oを〜した（している）まま」。腕は「組まれる」側なので過去分詞を使う" },
  { label: "【英語・高校在学】", q: "This is the house ( ) I was born. 空所に入る語は？", choices: ["which", "where", "what"], answer: 1, explain: "場所を表す先行詞のあとは関係副詞 where。This is the house in which I was born. と書き換えられる" },
  { label: "【英語・高校在学】", q: "This is the way ( ) he solved the problem. 空所に入る語（句）は？", choices: ["in which", "where", "what"], answer: 0, explain: "「方法」は the way in which 〜 または the way 〜 の形。（これが彼がその問題を解いた方法だ）。the way how とは言わない" },
  { label: "【英語・高校在学】", q: "He passed the exam, ( ) surprised everyone. 空所に入る語は？", choices: ["that", "which", "what"], answer: 1, explain: "関係代名詞の非制限用法で、前の文全体を先行詞にできる。コンマのあとに that は使えない" },
  { label: "【英語・高校在学】", q: "It was Tom ( ) broke the window. 空所に入る語は？", choices: ["what", "whom", "that"], answer: 2, explain: "強調構文 It is ＋ 強調したい語句 ＋ that 〜。（窓を割ったのはトムだった）。人のときは who も使える" },
  { label: "【英語・高校在学】", q: "Never ( ) I seen such a beautiful sight. 空所に入る語は？", choices: ["have", "did", "had been"], answer: 0, explain: "否定語（never）が文頭に出ると倒置が起こり、〈never ＋ 助動詞 ＋ 主語 ＋ 動詞〉の語順になる" },
  { label: "【英語・高校在学】", q: "Not only ( ) he sing well, but he also dances well. 空所に入る語は？", choices: ["do", "does", "is"], answer: 1, explain: "Not only が文頭にくると倒置になる。he は三人称単数の現在形なので does を使う" },
  { label: "【英語・高校在学】", q: "Hardly had I arrived ( ) it began to rain. 空所に入る語は？", choices: ["than", "when", "while"], answer: 1, explain: "Hardly ＋ had ＋ 主語 ＋ 過去分詞 ＋ when 〜 で「〜するとすぐに…」。No sooner 〜 than … も同じ意味" },
  { label: "【英語・高校在学】", q: "She said, 「I am tired.」 を間接話法にすると、She said that she ( ) tired. 空所に入る語は？", choices: ["is", "was", "will be"], answer: 1, explain: "伝える動詞（said）が過去なので、時制の一致で am が was に変わる" },
  { label: "【英語・高校在学】", q: "He has no more than 1,000 yen. この文の意味は？", choices: ["1000円もある", "1000円以上ある", "1000円しかない"], answer: 2, explain: "no more than 〜 は「〜しかない（only）」。not more than 〜 は「多くても〜」。no less than 〜 は「〜も（as many as）」" },
  { label: "【英語・高校在学】", q: "This box is twice as ( ) as that one. 空所に入る語は？", choices: ["heavy", "heavier", "heaviest"], answer: 0, explain: "倍数表現は 〜 times as ＋ 原級 ＋ as …。（この箱はあれの2倍の重さだ）" },
  { label: "【英語・高校在学】", q: "( ) happens, I won't change my mind. 空所に入る語は？", choices: ["Whichever", "Whatever", "However"], answer: 1, explain: "Whatever 〜 は「何が〜しようとも」（No matter what 〜）。譲歩を表す" },
  { label: "【英語・高校在学】", q: "It is high time you ( ) to bed. 空所に入る語は？", choices: ["go", "went", "will go"], answer: 1, explain: "It is (high) time ＋ 主語 ＋ 仮定法過去 で「もう〜してもよい（する）時間だ」" },
  { label: "【英語・高校在学】", q: "The street is wet. It ( ) have rained last night. 空所に入る語（句）は？", choices: ["must", "should", "cannot"], answer: 0, explain: "must have ＋ 過去分詞 は「〜したにちがいない」（過去についての強い推量）" },
  { label: "【英語・高校在学】", q: "You ( ) have told me the truth earlier. 空所に入る語（句）は？", choices: ["should", "must", "can"], answer: 0, explain: "should have ＋ 過去分詞 は「〜すべきだったのに（しなかった）」という後悔・非難を表す" },
  { label: "【英語・高校在学】", q: "He ( ) have said such a thing. He is a kind person. 空所に入る語（句）は？", choices: ["must", "should", "cannot"], answer: 2, explain: "cannot have ＋ 過去分詞 は「〜したはずがない」（過去についての強い否定の推量）" },
  { label: "【英語・高校在学】", q: "I had my bag ( ) on the train. 空所に入る語は？", choices: ["steal", "stolen", "stealing"], answer: 1, explain: "have ＋ O ＋ 過去分詞 は「Oを〜される（してもらう）」。ここは被害の意味で「バッグを盗まれた」" },
  { label: "【英語・高校在学】", q: "I remember ( ) him at the station last year. 空所に入る語（句）は？", choices: ["to meet", "meeting", "meet"], answer: 1, explain: "remember ～ing は「〜したことを覚えている」、remember to 〜 は「忘れずに〜する」" },
  { label: "【英語・高校在学】", q: "He is said ( ) rich when he was young. 空所に入る語（句）は？", choices: ["to be", "to have been", "being"], answer: 1, explain: "「〜だったと言われている」のように、述べている時より前のことは to have ＋ 過去分詞 で表す" },
  { label: "【英語・高校在学】", q: "She seems ( ) been busy yesterday. 空所に入る語（句）は？", choices: ["to have", "to be", "having"], answer: 0, explain: "seem to have ＋ 過去分詞 で「〜だった（した）ようだ」。（彼女は昨日忙しかったようだ）" },
  { label: "【英語・高校在学】", q: "I would rather stay home ( ) go out in this weather. 空所に入る語は？", choices: ["to", "than", "then"], answer: 1, explain: "would rather A than B で「BよりむしろAしたい」。A、Bともに動詞の原形" },
  { label: "【英語・高校在学】", q: "I couldn't help ( ) when I heard the news. 空所に入る語は？", choices: ["laugh", "to laugh", "laughing"], answer: 2, explain: "cannot help ～ing は「〜せずにはいられない」。（その知らせを聞いて笑わずにはいられなかった）" },
  { label: "【英語・高校在学】", q: "It is no use ( ) over spilled milk. 空所に入る語は？", choices: ["cry", "crying", "to cry"], answer: 1, explain: "It is no use ～ing は「〜しても無駄だ」。（覆水盆に返らず）という意味のことわざでもある" },
  { label: "【英語・高校在学】", q: "You may go out ( ) you finish your homework first. 空所に入る語（句）は？", choices: ["provided that", "in spite of", "because of"], answer: 0, explain: "provided (that) 〜 は「もし〜ならば、〜という条件で」。if より条件を強調する" },
  { label: "【英語・高校在学】", q: "Not all students like math. この文の意味は？", choices: ["数学が好きな生徒はいない", "全員が数学を嫌いだ", "すべての生徒が数学を好きなわけではない"], answer: 2, explain: "not all 〜 は部分否定で「すべてが〜というわけではない」。全否定は No students like math." },
  { label: "【英語・高校在学】", q: "What made you decide to study abroad? この文の意味に最も近いものは？", choices: ["なぜ留学しようと決めたのですか", "誰があなたを留学させたのですか", "何を留学で学びましたか"], answer: 0, explain: "無生物主語の文。直訳は「何があなたに留学を決意させたのか」で、自然な日本語では「なぜ〜しようと決めたのか」となる" },
  { label: "【英語・高校在学】", q: "He spoke slowly ( ) everyone could understand him. 空所に入る語（句）は？", choices: ["so that", "such that", "too"], answer: 0, explain: "so that ＋ 主語 ＋ can / could 〜 は「〜するために、〜できるように」（目的）" },
  { label: "【英語・高校在学】", q: "I don't like coffee. ―( ) do I. 空所に入る語は？", choices: ["So", "Neither", "Either"], answer: 1, explain: "否定文に対して「〜もそうだ」は Neither ＋ 助動詞 ＋ 主語。肯定文なら So ＋ 助動詞 ＋ 主語" },
  { label: "【英語・高校在学】", q: "This is by far the ( ) book I have ever read. 空所に入る語は？", choices: ["good", "better", "best"], answer: 2, explain: "by far は最上級を強める。（これは今まで読んだ中で、ずば抜けていちばんの本だ）" },
  { label: "【英語・高校在学】", q: "It is kind ( ) you to help me. 空所に入る語は？", choices: ["for", "of", "to"], answer: 1, explain: "人の性質を表す形容詞（kind, nice, careful など）は It is 〜 of A to … の形をとる" },
  { label: "【英語・高校在学】", q: "He demanded that she ( ) at once. 空所に入る語は？", choices: ["leaves", "left", "leave"], answer: 2, explain: "要求・提案・命令を表す動詞のあとの that 節では、動詞は原形（仮定法現在）になる。主語が三人称単数でも -s はつかない" },
  { label: "【英語・高校在学】", q: "She suggested that he ( ) a doctor. 空所に入る語（句）は？", choices: ["sees", "see", "saw"], answer: 1, explain: "suggest（提案する）のあとの that 節も、動詞は原形（または should ＋ 原形）になる" },
  { label: "【英語・高校在学】", q: "並べ替え：「もし彼が真実を知っていたら、私たちに話していただろう」正しい文は？", choices: ["If he had known the truth, he would have told us.", "If he knew the truth, he would have told us.", "If he had known the truth, he will tell us."], answer: 0, explain: "仮定法過去完了：If ＋ 主語 ＋ had ＋ 過去分詞, 主語 ＋ would have ＋ 過去分詞" },
  { label: "【英語・高校在学】", q: "並べ替え：「その問題を解くのに3時間かかった」正しい文は？", choices: ["I took three hours to solve the problem.", "It took me three hours to solve the problem.", "It took three hours me to solve the problem."], answer: 1, explain: "It takes ＋ 人 ＋ 時間 ＋ to 〜 で「（人が）〜するのに（時間）かかる」" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼が何を言おうとしているのか理解できない」正しい文は？", choices: ["I can't understand what is he trying to say.", "I can't understand what he is trying to say.", "I can't understand he is trying to say what."], answer: 1, explain: "間接疑問では〈疑問詞 ＋ 主語 ＋ 動詞〉の語順になり、疑問文の倒置は起こらない" },
  { label: "【英語・高校在学】", q: "並べ替え：「ここは私が育った町だ」正しい文は？", choices: ["This is the town where I grew up.", "This is where the town I grew up.", "This is the town which I grew up."], answer: 0, explain: "場所を表す先行詞（the town）のあとは関係副詞 where を使う" },
  { label: "【英語・高校在学】", q: "並べ替え：「この本は読む価値がある」正しい文は？", choices: ["This book is worth to read.", "This book is worth reading.", "This book is worth of reading."], answer: 1, explain: "be worth ～ing は「〜する価値がある」。worth の後ろは動名詞で、to 不定詞や of は使わない" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼はとても疲れていたので宿題ができなかった」正しい文は？", choices: ["He was so tired that he couldn't do his homework.", "He was too tired that he couldn't do his homework.", "He was such tired that he couldn't do his homework."], answer: 0, explain: "so ＋ 形容詞 ＋ that 〜 で「とても…なので〜」。such は名詞を伴うときに使う" },
  { label: "【英語・高校在学】", q: "並べ替え：「私は電車で財布を盗まれた」正しい文は？", choices: ["I had stolen my wallet on the train.", "I had my wallet stolen on the train.", "I had my wallet steal on the train."], answer: 1, explain: "have ＋ O ＋ 過去分詞 で「Oを〜される」。財布は「盗まれる」側なので過去分詞 stolen を使う" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼がそんなことを言うとは思いもしなかった」正しい文は？", choices: ["I never thought that he would say such a thing.", "I never thought that he would say a such thing.", "I never thought that would he say such a thing."], answer: 0, explain: "such ＋ a ＋ 名詞 の語順。間接的な内容を表す that 節の中では倒置は起こらない" },
  { label: "【英語・高校在学】", q: "( ) tired, she kept working until midnight. 空所に入る語（句）は？", choices: ["Despite being", "In spite", "Although being of"], answer: 0, explain: "despite の後ろは名詞か動名詞。Despite being tired は Although she was tired と同じ意味" },
  { label: "【英語・高校在学】", q: "He is one ( ) the best players in the team. 空所に入る語は？", choices: ["in", "for", "of"], answer: 2, explain: "one of the ＋ 最上級 ＋ 複数名詞 で「最も〜な…のひとつ」" },
  { label: "【英語・高校在学】", q: "Of the two, he is the ( ) careful. 空所に入る語は？", choices: ["more", "most", "much"], answer: 0, explain: "2者の比較では、最上級ではなく比較級を使い、the を付けることがある。（2人のうちでは、彼のほうが注意深い）" },
  { label: "【英語・高校在学】", q: "I'm looking forward to ( ) from you soon. 空所に入る語は？", choices: ["hear", "hearing", "heard"], answer: 1, explain: "look forward to の to は前置詞なので、後ろは名詞か動名詞（〜ing）になる" },
  { label: "【英語・高校在学】", q: "The book ( ) cover is red is mine. 空所に入る語は？", choices: ["who", "whose", "which"], answer: 1, explain: "「その〜の」の意味の所有格の関係代名詞は whose。the book whose cover 〜 で「表紙が〜の本」" },
  { label: "【英語・高校在学】", q: "( ) you like it or not, you have to do it. 空所に入る語は？", choices: ["Whether", "If", "Unless"], answer: 0, explain: "Whether A or B で「AであろうとBであろうと」（譲歩）。この意味では if は使えない" },


  
  { label: "【英語・高校在学】", q: "「abandon」の意味は？", choices: ["〜を捨てる、断念する", "〜を吸収する", "〜を加える"], answer: 0, explain: "They abandoned the plan.（彼らはその計画を断念した）。The car was abandoned.（その車は放置された）" },
  { label: "【英語・高校在学】", q: "「abstract」（形容詞）の意味は？", choices: ["具体的な", "抽象的な", "絶対の"], answer: 1, explain: "Love is an abstract idea.（愛は抽象的な概念だ）。反対は concrete（具体的な）" },
  { label: "【英語・高校在学】", q: "「accumulate」の意味は？", choices: ["〜を告発する", "〜を正確にする", "〜を蓄積する、たまる"], answer: 2, explain: "Dust accumulated on the shelf.（棚にほこりがたまった）" },
  { label: "【英語・高校在学】", q: "「alter」の意味は？", choices: ["〜を変える、変わる", "〜を交互にする", "〜を許す"], answer: 0, explain: "She altered her plans.（彼女は計画を変更した）。名詞は alteration" },
  { label: "【英語・高校在学】", q: "「anticipate」の意味は？", choices: ["〜に参加する", "〜を予期する、見越す", "〜を古くする"], answer: 1, explain: "We anticipate heavy traffic tomorrow.（明日は交通渋滞が予想される）。expect より「先を見越して備える」ニュアンス" },
  { label: "【英語・高校在学】", q: "「apparent」の意味は？", choices: ["親の", "外見の", "明らかな、見かけ上の"], answer: 2, explain: "It was apparent that he was lying.（彼がうそをついているのは明らかだった）。副詞 apparently は「見たところ〜らしい」" },
  { label: "【英語・高校在学】", q: "「aspect」の意味は？", choices: ["側面、面", "期待", "主張"], answer: 0, explain: "We must consider every aspect of the problem.（その問題のあらゆる側面を考えなければならない）" },
  { label: "【英語・高校在学】", q: "「assess」の意味は？", choices: ["〜を主張する", "〜を評価する、査定する", "〜を集める"], answer: 1, explain: "The doctor assessed the damage.（医者は損傷の程度を判断した）。名詞は assessment" },
  { label: "【英語・高校在学】", q: "「attribute A to B」の意味は？", choices: ["AをBに分配する", "AをBと区別する", "AをBのおかげ（せい）だと考える"], answer: 2, explain: "He attributes his success to hard work.（彼は成功を努力のおかげだと考えている）" },
  { label: "【英語・高校在学】", q: "「bias」の意味は？", choices: ["偏見、かたより", "自転車", "請求書"], answer: 0, explain: "The report shows a strong bias.（その報告書には強い偏りがある）。形容詞 biased は「偏った」" },
  { label: "【英語・高校在学】", q: "She is capable ( ) solving the problem. 空所に入る語は？", choices: ["to", "of", "for"], answer: 1, explain: "be capable of 〜ing は「〜する能力がある」。be able to ＋ 動詞の原形 と形が違うので注意" },
  { label: "【英語・高校在学】", q: "「clarify」の意味は？", choices: ["〜を分類する", "〜を拍手する", "〜を明確にする"], answer: 2, explain: "Could you clarify your point?（あなたの主張を明確にしてもらえますか）。形容詞は clear" },
  { label: "【英語・高校在学】", q: "「collapse」の意味は？", choices: ["崩壊する、倒れる", "〜を集める", "〜を衝突させる"], answer: 0, explain: "The old bridge collapsed.（古い橋が崩れ落ちた）" },
  { label: "【英語・高校在学】", q: "「comprehensive」の意味は？", choices: ["理解できる", "包括的な、総合的な", "圧縮された"], answer: 1, explain: "a comprehensive study（包括的な研究）。動詞 comprehend は「〜を理解する」" },
  { label: "【英語・高校在学】", q: "「concept」の意味は？", choices: ["協奏曲", "集中", "概念、考え方"], answer: 2, explain: "She explained the concept of time.（彼女は時間の概念を説明した）" },
  { label: "【英語・高校在学】", q: "「confirm」の意味は？", choices: ["〜を確認する、裏づける", "〜を混乱させる", "〜を対立させる"], answer: 0, explain: "Please confirm your reservation.（予約を確認してください）。名詞は confirmation" },
  { label: "【英語・高校在学】", q: "「conscious」の意味は？", choices: ["良心的な", "意識している、気づいている", "慎重な"], answer: 1, explain: "He was conscious of being watched.（彼は見られていることに気づいていた）。be conscious of 〜 の形で使う" },
  { label: "【英語・高校在学】", q: "「constant」の意味は？", choices: ["建設的な", "かたい", "絶え間ない、一定の"], answer: 2, explain: "the constant noise of traffic（絶え間ない交通の騒音）。副詞は constantly" },
  { label: "【英語・高校在学】", q: "「constitute」の意味は？", choices: ["〜を構成する、〜にあたる", "〜を禁止する", "〜を競う"], answer: 0, explain: "Women constitute half of the staff.（女性がスタッフの半分を占める）。名詞 constitution は「憲法、体質」" },
  { label: "【英語・高校在学】", q: "「convey」の意味は？", choices: ["〜を隠す", "〜を伝える、運ぶ", "〜を説得する"], answer: 1, explain: "Words cannot convey my feelings.（言葉では私の気持ちを伝えられない）" },
  { label: "【英語・高校在学】", q: "「crucial」の意味は？", choices: ["残酷な", "透明な", "極めて重要な"], answer: 2, explain: "Sleep is crucial for your health.（睡眠は健康にとって極めて重要だ）" },
  { label: "【英語・高校在学】", q: "「deliberate」（形容詞）の意味は？", choices: ["故意の、慎重な", "繊細な", "遅れた"], answer: 0, explain: "It was a deliberate act.（それは故意の行為だった）。副詞 deliberately は「わざと」" },
  { label: "【英語・高校在学】", q: "「distinguish」の意味は？", choices: ["〜を消す", "〜を区別する", "〜を配る"], answer: 1, explain: "It is hard to distinguish A from B.（AとBを区別するのは難しい）" },
  { label: "【英語・高校在学】", q: "「diverse」の意味は？", choices: ["方向を変えた", "分割された", "多様な"], answer: 2, explain: "Japan has a diverse culture.（日本には多様な文化がある）。名詞は diversity" },
  { label: "【英語・高校在学】", q: "「dominant」の意味は？", choices: ["支配的な、優勢な", "寄付の", "憂うつな"], answer: 0, explain: "English is the dominant language in business.（ビジネスでは英語が支配的な言語だ）。動詞は dominate" },
  { label: "【英語・高校在学】", q: "「eliminate」の意味は？", choices: ["〜を引き出す", "〜を取り除く、排除する", "〜を省略する"], answer: 1, explain: "We must eliminate waste.（無駄を取り除かなければならない）" },
  { label: "【英語・高校在学】", q: "「emerge」の意味は？", choices: ["〜を押し込む", "緊急の", "現れる、浮かび上がる"], answer: 2, explain: "A new problem emerged.（新しい問題が浮上した）。名詞 emergency は「緊急事態」" },
  { label: "【英語・高校在学】", q: "「enormous」の意味は？", choices: ["莫大な、巨大な", "通常の", "熱心な"], answer: 0, explain: "an enormous amount of money（莫大な金額）" },
  { label: "【英語・高校在学】", q: "「exceed」の意味は？", choices: ["〜を除く", "〜を超える", "〜を交換する"], answer: 1, explain: "The cost exceeded our budget.（費用が予算を超えた）。excess は「超過」" },
  { label: "【英語・高校在学】", q: "「exhibit」の意味は？", choices: ["〜を出口へ導く", "〜を禁止する", "〜を展示する"], answer: 2, explain: "The museum exhibits old paintings.（その美術館は古い絵画を展示している）。名詞は exhibition（展覧会）" },
  { label: "【英語・高校在学】", q: "「expose」の意味は？", choices: ["〜をさらす、暴露する", "〜を輸出する", "〜を説明する"], answer: 0, explain: "Don't expose the film to light.（フィルムを光にさらしてはいけない）。be exposed to 〜 で「〜にさらされる」" },
  { label: "【英語・高校在学】", q: "「flexible」の意味は？", choices: ["曲がらない", "柔軟な", "浮かぶ"], answer: 1, explain: "My schedule is flexible.（私の予定は融通がきく）" },
  { label: "【英語・高校在学】", q: "「fundamental」の意味は？", choices: ["楽しい", "基金の", "基本的な、根本的な"], answer: 2, explain: "a fundamental right（基本的人権）。副詞は fundamentally" },
  { label: "【英語・高校在学】", q: "「genuine」の意味は？", choices: ["本物の、心からの", "天才の", "穏やかな"], answer: 0, explain: "This is a genuine diamond.（これは本物のダイヤモンドだ）" },
  { label: "【英語・高校在学】", q: "「impose」の意味は？", choices: ["〜を輸入する", "〜を課す、押しつける", "〜を印象づける"], answer: 1, explain: "Don't impose your opinion on others.（自分の意見を他人に押しつけてはいけない）" },
  { label: "【英語・高校在学】", q: "「inhabit」の意味は？", choices: ["〜を禁止する", "〜を相続する", "〜に住む、生息する"], answer: 2, explain: "Many birds inhabit this island.（この島には多くの鳥が生息している）。名詞 inhabitant は「住民」" },
  { label: "【英語・高校在学】", q: "「interpret」の意味は？", choices: ["〜を解釈する、通訳する", "〜を中断する", "〜に干渉する"], answer: 0, explain: "How do you interpret this poem?（この詩をどう解釈しますか）。名詞は interpretation" },
  { label: "【英語・高校在学】", q: "「invest」の意味は？", choices: ["〜を発明する", "〜を投資する", "〜を調査する"], answer: 1, explain: "He invested money in a new company.（彼は新しい会社に投資した）。invent（発明する）、investigate（調査する）と区別" },
  { label: "【英語・高校在学】", q: "「mature」の意味は？", choices: ["物質の", "最大の", "成熟した、大人びた"], answer: 2, explain: "She is mature for her age.（彼女は年のわりに大人びている）。反対は immature" },
  { label: "【英語・高校在学】", q: "「neglect」の意味は？", choices: ["〜を怠る、無視する", "〜を交渉する", "〜を否定する"], answer: 0, explain: "Don't neglect your duties.（義務を怠ってはいけない）" },
  { label: "【英語・高校在学】", q: "「obtain」の意味は？", choices: ["〜を観察する", "〜を入手する、獲得する", "〜を妨げる"], answer: 1, explain: "He obtained a license last year.（彼は去年免許を取得した）。get のかたい言い方" },
  { label: "【英語・高校在学】", q: "「overcome」の意味は？", choices: ["〜を追い越す", "〜を見渡す", "〜を克服する"], answer: 2, explain: "She overcame many difficulties.（彼女は多くの困難を克服した）。活用は overcome - overcame - overcome" },
  { label: "【英語・高校在学】", q: "「participate」の意味は？", choices: ["参加する", "〜を分割する", "〜を部分的に支払う"], answer: 0, explain: "Everyone participated in the discussion.（全員が議論に参加した）。participate in 〜 の形で使う" },
  { label: "【英語・高校在学】", q: "「persuade」の意味は？", choices: ["〜を迫害する", "〜を説得する", "〜を許可する"], answer: 1, explain: "I persuaded him to see a doctor.（私は彼を説得して医者に診てもらった）。persuade A to 〜" },
  { label: "【英語・高校在学】", q: "「predict」の意味は？", choices: ["〜を禁止する", "〜を防ぐ", "〜を予測する"], answer: 2, explain: "No one can predict the future.（誰も未来を予測できない）。名詞は prediction" },
  { label: "【英語・高校在学】", q: "「pursue」の意味は？", choices: ["〜を追求する、追いかける", "〜を購入する", "〜を押す"], answer: 0, explain: "She pursued her dream of becoming a singer.（彼女は歌手になる夢を追い続けた）。名詞は pursuit" },
  { label: "【英語・高校在学】", q: "「reject」の意味は？", choices: ["〜を喜ぶ", "〜を拒絶する、却下する", "〜を投影する"], answer: 1, explain: "The company rejected his proposal.（会社は彼の提案を却下した）" },
  { label: "【英語・高校在学】", q: "「stimulate」の意味は？", choices: ["〜を刺激する、促す", "〜を模倣する", "〜を安定させる"], answer: 0, explain: "Good teachers stimulate students' interest.（よい教師は生徒の興味を刺激する）。名詞は stimulus" },
  { label: "【英語・高校在学】", q: "「transform」の意味は？", choices: ["〜を翻訳する", "〜を移す", "〜を一変させる、変形させる"], answer: 2, explain: "The Internet has transformed our lives.（インターネットは私たちの生活を一変させた）" },
  { label: "【英語・高校在学】", q: "「vague」の意味は？", choices: ["あいまいな、漠然とした", "むなしい", "価値のある"], answer: 0, explain: "He gave a vague answer.（彼は漠然とした答えをした）。反対は clear" },
  { label: "【英語・高校在学】", q: "「be faced with 〜」の意味は？", choices: ["〜に背を向ける", "〜に直面している", "〜に顔を洗う"], answer: 1, explain: "We are faced with a difficult problem.（私たちは難しい問題に直面している）。be confronted with 〜 とほぼ同じ" },
  { label: "【英語・高校在学】", q: "「contrary to 〜」の意味は？", choices: ["〜に従って", "〜の代わりに", "〜に反して"], answer: 2, explain: "Contrary to my expectations, the movie was boring.（予想に反して、その映画は退屈だった）" },
  { label: "【英語・高校在学】", q: "「owing to 〜」の意味は？", choices: ["〜のために、〜が原因で", "〜を所有して", "〜のおかげで借りがある"], answer: 0, explain: "The train was late owing to the snow.（雪のために電車が遅れた）。due to 〜 とほぼ同じ意味" },
  { label: "【英語・高校在学】", q: "「on the contrary」の意味は？", choices: ["それに加えて", "それどころか、逆に", "契約によって"], answer: 1, explain: "I'm not angry. On the contrary, I'm glad.（怒っていない。それどころか、うれしい）" },
  { label: "【英語・高校在学】", q: "「make up for 〜」の意味は？", choices: ["〜を化粧する", "〜をでっち上げる", "〜の埋め合わせをする"], answer: 2, explain: "I'll work hard to make up for lost time.（失った時間の埋め合わせをするために一生懸命働く）" },
  { label: "【英語・高校在学】", q: "「make the most of 〜」の意味は？", choices: ["〜を最大限に活用する", "〜を最も作る", "〜をほとんど作らない"], answer: 0, explain: "Make the most of your time at school.（学校での時間を最大限に生かしなさい）" },
  { label: "【英語・高校在学】", q: "「keep 〜 in mind」の意味は？", choices: ["〜を忘れる", "〜を心にとどめておく", "〜を気にしない"], answer: 1, explain: "Keep this in mind when you decide.（決めるときはこのことを心にとどめておきなさい）" },
  { label: "【英語・高校在学】", q: "「give rise to 〜」の意味は？", choices: ["〜を持ち上げる", "〜を育てる", "〜を引き起こす"], answer: 2, explain: "The decision gave rise to a heated debate.（その決定は激しい議論を引き起こした）。bring about とほぼ同じ" },
  { label: "【英語・高校在学】", q: "「play a role in 〜」の意味は？", choices: ["〜で役割を果たす", "〜の役を演じない", "〜で遊ぶ"], answer: 0, explain: "Sleep plays an important role in learning.（睡眠は学習で重要な役割を果たす）" },
  { label: "【英語・高校在学】", q: "「be involved in 〜」の意味は？", choices: ["〜から進化する", "〜に関わっている、巻き込まれている", "〜を発明している"], answer: 1, explain: "He is involved in a volunteer project.（彼はボランティア活動に関わっている）" },
  { label: "【英語・高校在学】", q: "「stand out」の意味は？", choices: ["外で立つ", "〜に我慢する", "目立つ、際立つ"], answer: 2, explain: "Her red coat stood out in the crowd.（彼女の赤いコートは人ごみの中で目立った）" },
  { label: "【英語・高校在学】", q: "「apply for 〜」の意味は？", choices: ["〜に応募する、申し込む", "〜を応用する", "〜に当てはまる"], answer: 0, explain: "I applied for a scholarship.（私は奨学金に申し込んだ）。apply A to B は「AをBに応用する」" },
  { label: "【英語・高校在学】", q: "( ) I need is more time. 空所に入る語は？", choices: ["That", "What", "Which"], answer: 1, explain: "関係代名詞 what は「〜するもの（こと）」。what I need は「私が必要とするもの」という名詞のかたまり" },
  { label: "【英語・高校在学】", q: "This table is made ( ) wood. 空所に入る語は？", choices: ["from", "by", "of"], answer: 2, explain: "材料が見た目でわかる（性質が変わらない）ときは be made of 〜。原料が変化するときは be made from 〜" },
  { label: "【英語・高校在学】", q: "Cheese is made ( ) milk. 空所に入る語は？", choices: ["from", "of", "in"], answer: 0, explain: "原料が見た目では判別できないほど変化するときは be made from 〜。（チーズは牛乳から作られる）" },
  { label: "【英語・高校在学】", q: "He was laughed ( ) by everyone. 空所に入る語は？", choices: ["to", "at", "of"], answer: 1, explain: "laugh at 〜（〜を笑う）のように、群動詞を受け身にするときは、前置詞を残して was laughed at とする" },
  { label: "【英語・高校在学】", q: "I ( ) been studying since this morning. 空所に入る語（句）は？", choices: ["am", "was", "have"], answer: 2, explain: "現在完了進行形は have（has）been ＋ 〜ing。「ずっと〜している」と動作の継続を表す" },
  { label: "【英語・高校在学】", q: "When I arrived at the station, the train ( ) already left. 空所に入る語は？", choices: ["has", "had", "was"], answer: 1, explain: "過去のある時点（到着した時）より前に起こったことは過去完了（had ＋ 過去分詞）で表す" },
  { label: "【英語・高校在学】", q: "By next year, I ( ) lived here for ten years. 空所に入る語（句）は？", choices: ["will have", "have", "had"], answer: 0, explain: "未来のある時点までの継続・完了は未来完了（will have ＋ 過去分詞）。by next year がヒント" },
  { label: "【英語・高校在学】", q: "You need not ( ) hurried. We had plenty of time. 空所に入る語は？", choices: ["be", "have", "to"], answer: 1, explain: "need not have ＋ 過去分詞 は「〜する必要はなかったのに（してしまった）」" },
  { label: "【英語・高校在学】", q: "She may well be proud of her son. この文の意味は？", choices: ["彼女が息子を誇りに思うのももっともだ", "彼女はたぶん息子を誇りに思っていない", "彼女は息子を誇りに思ってもよい"], answer: 0, explain: "may well 〜 は「〜するのももっともだ、たぶん〜だろう」。You may well say so. は「そう言うのももっともだ」" },
  { label: "【英語・高校在学】", q: "You might as well go home. この文の意味は？", choices: ["家に帰ってはいけない", "（どうせなら）家に帰ったほうがよさそうだ", "家に帰れるはずがない"], answer: 1, explain: "might as well 〜 は「〜したほうがましだ、〜してもいいだろう」。had better より弱い言い方" },
  { label: "【英語・高校在学】", q: "He is not so much a teacher as a friend. この文の意味は？", choices: ["教師であり友人でもある", "教師でも友人でもない", "教師というより友人だ"], answer: 2, explain: "not so much A as B は「AというよりむしろB」(= B rather than A)" },
  { label: "【英語・高校在学】", q: "However ( ) he is, he can't lift that rock. 空所に入る語は？", choices: ["strongly", "strong", "strength"], answer: 1, explain: "However ＋ 形容詞（副詞）＋ 主語 ＋ 動詞 で「どんなに〜でも」（No matter how strong he is）" },
  { label: "【英語・高校在学】", q: "I was surprised at the fact ( ) he had lied. 空所に入る語は？", choices: ["that", "what", "which"], answer: 0, explain: "the fact that 〜 は「〜という事実」（同格の that）。that 以下で fact の内容を説明している" },
  { label: "【英語・高校在学】", q: "I was very ( ) in the story. 空所に入る語は？", choices: ["interesting", "interested", "interest"], answer: 1, explain: "人が「興味を持つ」は interested、物事が「おもしろい」は interesting。be interested in 〜" },
  { label: "【英語・高校在学】", q: "I was ( ) by the long speech. 空所に入る語は？", choices: ["boring", "bore", "bored"], answer: 2, explain: "人が「退屈した」は bored。speech が「退屈な」と言うなら boring。感情を表す分詞の使い分けに注意" },
  { label: "【英語・高校在学】", q: "He hates ( ) laughed at. 空所に入る語は？", choices: ["being", "to being", "be"], answer: 0, explain: "動名詞の受動態は being ＋ 過去分詞。hate の後ろは動名詞なので being laughed at となる" },
  { label: "【英語・高校在学】", q: "He was kind ( ) to lend me his umbrella. 空所に入る語は？", choices: ["so", "enough", "too"], answer: 1, explain: "形容詞 ＋ enough to 〜 で「〜するほど…だ、親切にも〜する」" },
  { label: "【英語・高校在学】", q: "I don't know ( ) to do next. 空所に入る語は？", choices: ["what", "that", "whether"], answer: 0, explain: "疑問詞 ＋ to 不定詞 は名詞のはたらき。what to do は「何をすべきか」" },
  { label: "【英語・高校在学】", q: "( ) rich are not always happy. 空所に入る語は？", choices: ["Rich", "The", "A"], answer: 1, explain: "the ＋ 形容詞 で「〜な人々」を表す。the rich = rich people（裕福な人々）" },
  { label: "【英語・高校在学】", q: "I lost my pen, so I must buy ( ). 空所に入る語は？", choices: ["it", "another", "one"], answer: 2, explain: "不特定の「ひとつ」を表すときは one を使う。it は同じ特定のもの（なくした本人のペン）を指すので不適切" },
  { label: "【英語・高校在学】", q: "One is red and the ( ) is blue. 空所に入る語は？", choices: ["another", "other", "others"], answer: 1, explain: "2つのうち「ひとつ」と「残りのひとつ」は One 〜, the other …" },
  { label: "【英語・高校在学】", q: "( ) your advice, I would have made a mistake. 空所に入る語（句）は？", choices: ["But for", "Because", "Unless"], answer: 0, explain: "But for 〜 / Without 〜 は「〜がなかったら」。仮定法過去完了とともに使うと、「（あのとき）〜がなかったら…だっただろう」" },
  { label: "【英語・高校在学】", q: "If it ( ) not for your help, I would fail. 空所に入る語は？", choices: ["is", "were", "had been"], answer: 1, explain: "If it were not for 〜 は「（今）〜がなければ」（仮定法過去）。過去なら If it had not been for 〜" },
  { label: "【英語・高校在学】", q: "( ) I to live to be 100, I would see many changes. 空所に入る語は？", choices: ["Was", "Were", "Had"], answer: 1, explain: "Were ＋ 主語 ＋ to 〜 は、実現しにくい仮定を表す仮定法の倒置表現。If I were to 〜 の if を省略した形" },
  { label: "【英語・高校在学】", q: "If it ( ) rain tomorrow, the game will be canceled. 空所に入る語は？", choices: ["would", "should", "shall"], answer: 1, explain: "If 〜 should ... は「万一〜なら」。可能性が低いと感じる未来の仮定を表す" },
  { label: "【英語・高校在学】", q: "It was not until midnight ( ) he came home. 空所に入る語は？", choices: ["when", "that", "which"], answer: 1, explain: "It is not until 〜 that ... は「〜になってはじめて…する」。（真夜中になってやっと彼は帰宅した）" },
  { label: "【英語・高校在学】", q: "( ) a beautiful view this is! 空所に入る語は？", choices: ["How", "What", "So"], answer: 1, explain: "What ＋ a ＋ 形容詞 ＋ 名詞 ＋ 主語 ＋ 動詞！ の語順。How は形容詞・副詞の前に置く" },
  { label: "【英語・高校在学】", q: "She ( ) the book on the table and left. 空所に入る語は？", choices: ["lay", "laid", "lied"], answer: 1, explain: "lay（置く）- laid - laid。lie（横たわる）- lay - lain。lie（うそをつく）- lied - lied。混同しやすい" },
  { label: "【英語・高校在学】", q: "Hand in the report ( ) Friday. 空所に入る語は？", choices: ["until", "by", "for"], answer: 1, explain: "by は「〜までに」（期限）、until は「〜までずっと」（継続）。提出は一度なので by を使う" },
  { label: "【英語・高校在学】", q: "No sooner had he left ( ) it began to rain. 空所に入る語は？", choices: ["when", "than", "then"], answer: 1, explain: "No sooner ＋ had ＋ 主語 ＋ 過去分詞 ＋ than 〜 で「〜するとすぐに…」。Hardly 〜 when … と対応させて覚える" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼女は私にパーティーに来るように頼んだ」正しい文は？", choices: ["She asked me to come to the party.", "She asked me come to the party.", "She asked to me to come the party."], answer: 0, explain: "ask ＋ 人 ＋ to 不定詞 で「人に〜するように頼む」" },
  { label: "【英語・高校在学】", q: "並べ替え：「私は彼にそれを手伝ってもらった」正しい文は？", choices: ["I got him help me with it.", "I got helped him with it.", "I got him to help me with it."], answer: 2, explain: "get ＋ 人 ＋ to 不定詞 で「人に〜してもらう」。have ＋ 人 ＋ 原形 と同じ意味だが、get は to が必要" },
  { label: "【英語・高校在学】", q: "並べ替え：「何が起ころうと、私はあなたを支える」正しい文は？", choices: ["Whatever happens, I will support you.", "Whatever will happen, I support you.", "What happens ever, I will support you."], answer: 0, explain: "Whatever ＋ 現在形 で「何が起ころうとも」。時や条件を表す副詞節では未来のことでも現在形を使う" },
  { label: "【英語・高校在学】", q: "並べ替え：「この問題は彼には難しすぎて解けない」正しい文は？", choices: ["This problem is too difficult for him to solve it.", "This problem is too difficult for him to solve.", "This problem is difficult too for him to solve."], answer: 1, explain: "too 〜 for A to … で「Aには〜すぎて…できない」。to 以下の動詞の目的語（it）は、主語と同じなので入れない" },
  { label: "【英語・高校在学】", q: "並べ替え：「窓が開けっぱなしになっていた」正しい文は？", choices: ["The window was left open.", "The window was left opened.", "The window left was open."], answer: 0, explain: "leave ＋ O ＋ C（Oを〜のままにしておく）の受動態。leave the window open → The window was left open." },
  { label: "【英語・高校在学】", q: "並べ替え：「試験に落ちたのは彼のせいではない」正しい文は？", choices: ["It is not his fault which he failed the exam.", "That he failed the exam is not his fault it.", "It is not his fault that he failed the exam."], answer: 2, explain: "形式主語 It ＋ is not his fault ＋ that 〜 の形。真主語（that 節）を後ろに置く" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼女は彼が来るのを待っているところだ」正しい文は？", choices: ["She is waiting for him to come.", "She is waiting him to come.", "She is waiting for he to come."], answer: 0, explain: "wait for ＋ 人 ＋ to 不定詞 で「人が〜するのを待つ」。for の後ろは目的格（him）" },
  { label: "【英語・高校在学】", q: "並べ替え：「私は彼が約束を守ると信じている」正しい文は？", choices: ["I believe that he keeps will his promise.", "I believe that he will keep his promise.", "I believe he will his promise keep."], answer: 1, explain: "believe ＋ (that) ＋ 主語 ＋ 動詞。助動詞 will のあとは動詞の原形 keep、その後ろに目的語 his promise が続く" },

// ===== 英語（高校在学）201〜300問 =====
  { label: "【英語・高校在学】", q: "「accommodate」の意味は？", choices: ["〜を収容する、〜に応じる", "〜を達成する", "〜を加速させる"], answer: 0, explain: "The hotel can accommodate 500 guests.（そのホテルは500人を収容できる）。名詞は accommodation（宿泊施設）" },
  { label: "【英語・高校在学】", q: "「advocate」の意味は？", choices: ["〜を放棄する", "〜を前進させる", "〜を擁護する、提唱する"], answer: 2, explain: "She advocates equal rights for all.（彼女はすべての人の平等な権利を主張している）。名詞では「支持者」の意味" },
  { label: "【英語・高校在学】", q: "「allocate」の意味は？", choices: ["〜を位置づける", "〜を割り当てる、配分する", "〜を許可する"], answer: 1, explain: "The city allocated funds for the new library.（市は新しい図書館に資金を割り当てた）" },
  { label: "【英語・高校在学】", q: "「arbitrary」の意味は？", choices: ["任意の、恣意的な", "好戦的な", "武器の"], answer: 0, explain: "It was an arbitrary decision.（それは恣意的な決定だった）。理由や規則に基づかない、気まぐれな様子を表す" },
  { label: "【英語・高校在学】", q: "「collaborate」の意味は？", choices: ["〜を集める", "〜を比較する", "協力する、共同で作る"], answer: 2, explain: "The two companies collaborated on the project.（2社はそのプロジェクトで協力した）。名詞は collaboration" },
  { label: "【英語・高校在学】", q: "「compensate」の意味は？", choices: ["〜を補う、償う", "〜を競争する", "〜を完成させる"], answer: 0, explain: "Nothing can compensate for the loss.（何もその損失を埋め合わせることはできない）。compensate for 〜 の形で使う" },
  { label: "【英語・高校在学】", q: "「comply」の意味は？", choices: ["〜を実行する", "（規則などに）従う", "不満を言う"], answer: 1, explain: "All drivers must comply with the law.（すべての運転者は法律に従わなければならない）。comply with 〜 の形で使う" },
  { label: "【英語・高校在学】", q: "「consent」の意味は？", choices: ["相談", "意識", "同意、承諾"], answer: 2, explain: "You need your parents' consent.（親の同意が必要だ）。動詞では「同意する」の意味" },
  { label: "【英語・高校在学】", q: "「consume」の意味は？", choices: ["〜を相談する", "〜を消費する、食べる", "〜を保つ"], answer: 1, explain: "Japan consumes a lot of rice.（日本は多くの米を消費する）。名詞は consumption、「消費者」は consumer" },
  { label: "【英語・高校在学】", q: "「contradict」の意味は？", choices: ["〜と矛盾する、〜に反論する", "〜に貢献する", "〜を管理する"], answer: 0, explain: "His actions contradict his words.（彼の行動は言葉と矛盾している）。名詞は contradiction" },
  { label: "【英語・高校在学】", q: "「controversy」の意味は？", choices: ["対比", "会話", "論争、議論"], answer: 2, explain: "The plan caused a great controversy.（その計画は大きな論争を引き起こした）。形容詞は controversial" },
  { label: "【英語・高校在学】", q: "「convince」の意味は？", choices: ["〜を運ぶ", "〜を納得させる、確信させる", "〜を集める"], answer: 1, explain: "I'm convinced that he is innocent.（彼は無実だと確信している）。convince A that 〜 / be convinced of 〜" },
  { label: "【英語・高校在学】", q: "「credible」の意味は？", choices: ["信用できる、信じられる", "信用貸しの", "創造的な"], answer: 0, explain: "She gave a credible explanation.（彼女は信憑性のある説明をした）。名詞は credibility（信頼性）" },
  { label: "【英語・高校在学】", q: "「deficit」の意味は？", choices: ["決定", "欠陥", "赤字、不足"], answer: 2, explain: "The company has a large deficit.（その会社は大きな赤字を抱えている）。budget deficit は「財政赤字」" },
  { label: "【英語・高校在学】", q: "「deprive A of B」の意味は？", choices: ["AにBを与える", "AからBを奪う", "AをBと比べる"], answer: 1, explain: "The noise deprived me of sleep.（その騒音のせいで私は眠れなかった）。rob A of B と同じ形" },
  { label: "【英語・高校在学】", q: "「derive from 〜」の意味は？", choices: ["〜に由来する", "〜を運転する", "〜を持ち去る"], answer: 0, explain: "Many English words derive from Latin.（多くの英単語はラテン語に由来する）" },
  { label: "【英語・高校在学】", q: "「diminish」の意味は？", choices: ["〜を倍にする", "〜を消化する", "減少する、〜を減らす"], answer: 2, explain: "Her interest in the hobby diminished over time.（その趣味への彼女の関心は時とともに薄れた）" },
  { label: "【英語・高校在学】", q: "「discriminate」の意味は？", choices: ["差別する、区別する", "〜を発見する", "〜を話し合う"], answer: 0, explain: "It is wrong to discriminate against people.（人を差別するのは間違っている）。名詞は discrimination" },
  { label: "【英語・高校在学】", q: "「distort」の意味は？", choices: ["〜を分配する", "〜を引き離す", "〜をゆがめる"], answer: 2, explain: "The media distorted the facts.（メディアは事実をゆがめて伝えた）" },
  { label: "【英語・高校在学】", q: "「domestic」の意味は？", choices: ["国内の、家庭の", "国際的な", "野生の"], answer: 0, explain: "domestic flights（国内線）、domestic animals（家畜）、domestic work（家事）。反対は international / foreign" },
  { label: "【英語・高校在学】", q: "「durable」の意味は？", choices: ["地味な", "耐久性のある、丈夫な", "とても乾いた"], answer: 1, explain: "This bag is made of durable material.（このかばんは丈夫な素材でできている）。名詞は durability" },
  { label: "【英語・高校在学】", q: "「elaborate」（形容詞）の意味は？", choices: ["簡単な", "すぐれた", "入念な、精巧な"], answer: 2, explain: "They made an elaborate plan.（彼らは入念な計画を立てた）。動詞では「詳しく述べる」の意味（発音が変わる）" },
  { label: "【英語・高校在学】", q: "「endure」の意味は？", choices: ["〜に耐える", "〜を保証する", "〜を終了する"], answer: 0, explain: "She endured the pain for a long time.（彼女は長い間その痛みに耐えた）。名詞は endurance（忍耐力）" },
  { label: "【英語・高校在学】", q: "「evolve」の意味は？", choices: ["〜を革命する", "進化する、発展する", "〜を排除する"], answer: 1, explain: "Technology evolves very quickly.（技術は非常に速く進化する）。名詞は evolution" },
  { label: "【英語・高校在学】", q: "「exaggerate」の意味は？", choices: ["〜を誇張する", "〜を試験する", "〜を過小評価する"], answer: 0, explain: "Don't exaggerate. It wasn't that bad.（大げさに言わないで。そんなにひどくなかった）" },
  { label: "【英語・高校在学】", q: "「exclude」の意味は？", choices: ["〜を含める", "〜を実行する", "〜を除外する"], answer: 2, explain: "Children are excluded from this event.（子どもはこの行事から除外されている）。反対は include" },
  { label: "【英語・高校在学】", q: "「facilitate」の意味は？", choices: ["〜を容易にする、促進する", "〜を設備する", "〜を不可能にする"], answer: 0, explain: "The new system facilitates communication.（その新しいシステムは意思疎通を容易にする）" },
  { label: "【英語・高校在学】", q: "「feasible」の意味は？", choices: ["気楽な", "実現可能な", "肥沃な"], answer: 1, explain: "Is the plan feasible?（その計画は実現可能ですか）。possible より「現実的に実行できる」ニュアンス" },
  { label: "【英語・高校在学】", q: "「foster」の意味は？", choices: ["〜を邪魔する", "〜を許す", "〜を育てる、促進する"], answer: 2, explain: "Schools should foster creativity.（学校は創造性を育てるべきだ）" },
  { label: "【英語・高校在学】", q: "「hinder」の意味は？", choices: ["〜を妨げる", "〜を後ろへ置く", "〜を助ける"], answer: 0, explain: "Bad weather hindered the rescue work.（悪天候が救助活動を妨げた）。hinder A from ～ing の形でも使う" },
  { label: "【英語・高校在学】", q: "「implement」の意味は？", choices: ["〜を暗示する", "〜を実行する、実施する", "〜を輸入する"], answer: 1, explain: "The school implemented a new rule.（学校は新しい規則を実施した）" },
  { label: "【英語・高校在学】", q: "「inherit」の意味は？", choices: ["〜を禁止する", "〜を投資する", "〜を相続する、受け継ぐ"], answer: 2, explain: "She inherited a large house from her uncle.（彼女はおじから大きな家を相続した）。名詞は inheritance" },
  { label: "【英語・高校在学】", q: "「initiative」の意味は？", choices: ["調査", "主導権、率先", "情報"], answer: 1, explain: "take the initiative で「率先して行動する」。He took the initiative in organizing the event.（彼は率先してそのイベントを企画した）" },
  { label: "【英語・高校在学】", q: "「integrate」の意味は？", choices: ["〜を統合する", "〜を絶縁する", "〜を禁じる"], answer: 0, explain: "The company integrated the two systems.（その会社は2つのシステムを統合した）。名詞は integration" },
  { label: "【英語・高校在学】", q: "「intense」の意味は？", choices: ["意図的な", "相互の", "激しい、強烈な"], answer: 2, explain: "intense heat（強烈な暑さ）、intense competition（激しい競争）。名詞は intensity" },
  { label: "【英語・高校在学】", q: "「legitimate」の意味は？", choices: ["伝説的な", "合法の、正当な", "立法の"], answer: 1, explain: "He has a legitimate reason for being late.（彼には遅れた正当な理由がある）" },
  { label: "【英語・高校在学】", q: "「manipulate」の意味は？", choices: ["〜を操作する、操る", "〜を製造する", "〜を管理する"], answer: 0, explain: "He manipulated public opinion.（彼は世論を操った）。機械を巧みに扱う意味でも使う" },
  { label: "【英語・高校在学】", q: "「negotiate」の意味は？", choices: ["〜を無視する", "〜を否定する", "交渉する"], answer: 2, explain: "They negotiated with the company about prices.（彼らは価格について会社と交渉した）。名詞は negotiation" },
  { label: "【英語・高校在学】", q: "「obligation」の意味は？", choices: ["義務", "観察", "機会"], answer: 0, explain: "You have an obligation to pay taxes.（あなたには納税の義務がある）。動詞は oblige、be obliged to 〜 は「〜せざるを得ない」" },
  { label: "【英語・高校在学】", q: "「ongoing」の意味は？", choices: ["外向的な", "進行中の", "外へ行く"], answer: 1, explain: "The investigation is still ongoing.（調査はまだ進行中だ）" },
  { label: "【英語・高校在学】", q: "「prevail」の意味は？", choices: ["予防する", "〜を準備する", "広まる、普及する、勝つ"], answer: 2, explain: "Peace prevailed in the region.（その地域では平和が広まった）。形容詞 prevailing は「広く行きわたった」" },
  { label: "【英語・高校在学】", q: "「prohibit」の意味は？", choices: ["〜を禁止する", "〜を進める", "〜を約束する"], answer: 0, explain: "Smoking is prohibited here.（ここでは喫煙が禁止されている）。prohibit A from ～ing の形でも使う" },
  { label: "【英語・高校在学】", q: "「reinforce」の意味は？", choices: ["〜を取り除く", "〜を強化する、補強する", "〜を強制する"], answer: 1, explain: "The results reinforced my opinion.（その結果は私の意見を強めた）" },
  { label: "【英語・高校在学】", q: "「restrict」の意味は？", choices: ["〜を回復する", "〜を休ませる", "〜を制限する"], answer: 2, explain: "Entry is restricted to members.（入場は会員に限られている）。名詞は restriction" },
  { label: "【英語・高校在学】", q: "「scarce」の意味は？", choices: ["乏しい、不足した", "怖がらせる", "大量の"], answer: 0, explain: "Water is scarce in the desert.（砂漠では水が乏しい）。名詞は scarcity" },
  { label: "【英語・高校在学】", q: "「as opposed to 〜」の意味は？", choices: ["〜とは対照的に", "〜に向かって", "〜を提案して"], answer: 0, explain: "He prefers action as opposed to talk.（彼は話すことよりも行動を好む）" },
  { label: "【英語・高校在学】", q: "「in favor of 〜」の意味は？", choices: ["〜に反対して", "〜に賛成して", "〜の好意によって"], answer: 1, explain: "Most people are in favor of the plan.（大半の人がその計画に賛成だ）。反対は against" },
  { label: "【英語・高校在学】", q: "「at stake」の意味は？", choices: ["賭けを降りて", "杭に打たれて", "（失うかもしれないものが）かかっている"], answer: 2, explain: "His reputation is at stake.（彼の評判がかかっている）" },
  { label: "【英語・高校在学】", q: "「for the sake of 〜」の意味は？", choices: ["〜のために", "〜に比べて", "〜にもかかわらず"], answer: 0, explain: "He worked hard for the sake of his family.（彼は家族のために一生懸命働いた）" },
  { label: "【英語・高校在学】", q: "「with regard to 〜」の意味は？", choices: ["〜を気にかけて", "〜に関して", "〜を後ろにして"], answer: 1, explain: "I have a question with regard to the schedule.（日程に関して質問があります）。regarding 〜 / concerning 〜 とほぼ同じ" },
  { label: "【英語・高校在学】", q: "「on the whole」の意味は？", choices: ["穴の中に", "全体に反して", "全体として、概して"], answer: 2, explain: "On the whole, the trip was a success.（全体として、その旅行は成功だった）" },
  { label: "【英語・高校在学】", q: "「be subject to 〜」の意味は？", choices: ["〜を受けやすい、〜に従う必要がある", "〜の主題だ", "〜に反対する"], answer: 0, explain: "Prices are subject to change.（価格は変更されることがある）" },
  { label: "【英語・高校在学】", q: "「regardless of 〜」の意味は？", choices: ["〜を気にして", "〜にかかわらず", "〜に注意して"], answer: 1, explain: "Everyone can join regardless of age.（年齢にかかわらず誰でも参加できる）" },
  { label: "【英語・高校在学】", q: "「in accordance with 〜」の意味は？", choices: ["〜を説明して", "〜のために", "〜に従って、〜に一致して"], answer: 2, explain: "Please act in accordance with the rules.（規則に従って行動してください）" },
  { label: "【英語・高校在学】", q: "「on the verge of 〜」の意味は？", choices: ["〜の瀬戸際で、まさに〜しようとして", "〜の側面に", "〜を超えて"], answer: 0, explain: "The company was on the verge of bankruptcy.（その会社は倒産の瀬戸際にあった）" },
  { label: "【英語・高校在学】", q: "「be bound to 〜」の意味は？", choices: ["〜へ向かって縛られる", "きっと〜する、〜するに決まっている", "〜に会う"], answer: 1, explain: "He is bound to win.（彼はきっと勝つ）。be bound for 〜 は「〜行きだ」" },
  { label: "【英語・高校在学】", q: "「rule out 〜」の意味は？", choices: ["〜を支配する", "〜に線を引く", "〜を除外する、可能性を否定する"], answer: 2, explain: "The police ruled out the possibility of an accident.（警察は事故の可能性を除外した）" },
  { label: "【英語・高校在学】", q: "( ) in simple English, this book is easy to read. 空所に入る語は？", choices: ["Writing", "Written", "Wrote"], answer: 1, explain: "分詞構文の受け身。Being written の being が省略された形で、「〜で書かれているので」の意味。主語の book は「書かれる」側" },
  { label: "【英語・高校在学】", q: "( ) from his accent, he must be from Osaka. 空所に入る語は？", choices: ["Judge", "Judged", "Judging"], answer: 2, explain: "Judging from 〜 は「〜から判断すると」という慣用的な分詞構文。主語が一致しなくても使える" },
  { label: "【英語・高校在学】", q: "Weather ( ), we will hold the festival outdoors. 空所に入る語は？", choices: ["permitted", "permitting", "permit"], answer: 1, explain: "独立分詞構文。Weather permitting は「天気がよければ」。If the weather permits と同じ意味" },
  { label: "【英語・高校在学】", q: "Now ( ) you are here, let's start the meeting. 空所に入る語は？", choices: ["that", "as", "if"], answer: 0, explain: "now that 〜 は「今や〜なので」。since に近い意味で、理由を表す接続詞" },
  { label: "【英語・高校在学】", q: "Only then ( ) I realize my mistake. 空所に入る語は？", choices: ["did", "have", "was"], answer: 0, explain: "only ＋ 副詞（句）が文頭にくると倒置になる。過去の一般動詞の文なので did ＋ 主語 ＋ 原形" },
  { label: "【英語・高校在学】", q: "So difficult ( ) the exam that nobody passed. 空所に入る語は？", choices: ["did", "was", "had"], answer: 1, explain: "so ＋ 形容詞 が文頭に出ると倒置になる。So difficult was the exam that 〜 は The exam was so difficult that 〜 の強調形" },
  { label: "【英語・高校在学】", q: "Little ( ) he know that his friends were waiting. 空所に入る語は？", choices: ["did", "was", "had"], answer: 0, explain: "Little が「全然〜ない」という否定の意味で文頭に出ると倒置になる。Little did he know 〜 は「彼は〜とは夢にも思わなかった」" },
  { label: "【英語・高校在学】", q: "I ( ) love this song. 〔強調：本当に大好きだ〕空所に入る語は？", choices: ["do", "am", "did"], answer: 0, explain: "動詞の前に do（does / did）を置くと意味が強調される。I do love this song. は「この曲は本当に大好きだ」" },
  { label: "【英語・高校在学】", q: "Young ( ) he is, he is very wise. 空所に入る語は？", choices: ["as", "than", "so"], answer: 0, explain: "形容詞 ＋ as ＋ 主語 ＋ 動詞 で「〜だけれども」（譲歩）。Although he is young と同じ意味" },
  { label: "【英語・高校在学】", q: "There is no rule without exceptions. この文の意味は？", choices: ["例外のない規則はない", "規則には例外が存在しない", "規則はなく、例外だけがある"], answer: 0, explain: "no 〜 without … は二重否定で「…のない〜はない」＝「どんな規則にも例外がある」" },
  { label: "【英語・高校在学】", q: "She is no less clever than her brother. この文の意味は？", choices: ["兄に劣らず賢い", "兄ほど賢くない", "兄よりはるかに賢い"], answer: 0, explain: "no less 〜 than … は「…に劣らず〜」（＝ as 〜 as …）。not less than 〜 は「少なくとも〜」と区別する" },
  { label: "【英語・高校在学】", q: "He can't speak English, much less French. この文の意味は？", choices: ["フランス語ならなおさら話せる", "まして、フランス語は話せない", "フランス語のほうが少しは話せる"], answer: 1, explain: "否定文のあとの much less 〜 は「まして〜ない」。肯定文のあとの much more 〜 は「まして〜だ」" },
  { label: "【英語・高校在学】", q: "This is the man to ( ) I spoke yesterday. 空所に入る語は？", choices: ["who", "whom", "which"], answer: 1, explain: "前置詞 ＋ 関係代名詞 では、人が先行詞のとき目的格 whom を使う。（これは私が昨日話しかけた男性だ）" },
  { label: "【英語・高校在学】", q: "I like such books ( ) are easy to read. 空所に入る語は？", choices: ["which", "what", "as"], answer: 2, explain: "such ＋ 名詞 のあとは、関係代名詞 as を使う（such 〜 as …）。the same 〜 as … も同じ型" },
  { label: "【英語・高校在学】", q: "( ) do you think he is? 空所に入る語は？", choices: ["Who", "Whether", "Does"], answer: 0, explain: "think / believe / suppose などを含む疑問文では、疑問詞を文頭に置く。Do you think who he is? とは言わない" },
  { label: "【英語・高校在学】", q: "She was ( ) a prize at the contest. 空所に入る語は？", choices: ["given", "gave", "give"], answer: 0, explain: "SVOO の文は受け身にできる。She was given a prize.（彼女は賞を与えられた）。A prize was given to her. も可" },
  { label: "【英語・高校在学】", q: "I'm sorry ( ) kept you waiting. 空所に入る語（句）は？", choices: ["to have", "for have", "to be"], answer: 0, explain: "完了不定詞 to have ＋ 過去分詞 は、述語より前の出来事を表す。（お待たせして申し訳ない）" },
  { label: "【英語・高校在学】", q: "A new bridge is ( ) built over the river. 空所に入る語は？", choices: ["been", "being", "be"], answer: 1, explain: "受け身の進行形は be動詞 ＋ being ＋ 過去分詞。「〜されているところだ」" },
  { label: "【英語・高校在学】", q: "He has ( ) to Paris. He isn't here now. 空所に入る語は？", choices: ["been", "gone", "went"], answer: 1, explain: "have gone to 〜 は「〜へ行ってしまった（今ここにいない）」、have been to 〜 は「〜へ行ったことがある」" },
  { label: "【英語・高校在学】", q: "He got up early ( ) as to catch the first train. 空所に入る語は？", choices: ["so", "such", "too"], answer: 0, explain: "so as to 〜 は「〜するために」（目的）。in order to 〜 と同じ意味" },
  { label: "【英語・高校在学】", q: "I regret ( ) you that you failed the exam. 空所に入る語（句）は？", choices: ["telling", "to tell", "tell"], answer: 1, explain: "regret to 〜 は「残念ながら〜する」、regret ～ing は「〜したことを後悔する」" },
  { label: "【英語・高校在学】", q: "I'll never forget ( ) the Great Wall. 空所に入る語（句）は？", choices: ["to see", "seeing", "see"], answer: 1, explain: "forget ～ing は「〜したことを忘れる」、forget to 〜 は「〜するのを忘れる」。ここは「見たことを忘れない」" },
  { label: "【英語・高校在学】", q: "He denied ( ) the window. 空所に入る語（句）は？", choices: ["to break", "break", "breaking"], answer: 2, explain: "deny の後ろは動名詞。（彼は窓を割ったことを否定した）。admit / avoid / finish / enjoy なども動名詞をとる" },
  { label: "【英語・高校在学】", q: "I would rather you ( ) smoke here. 空所に入る語は？", choices: ["don't", "didn't", "won't"], answer: 1, explain: "would rather ＋ 主語 ＋ 過去形 で「〜してくれたらいいのに（してほしくない）」。仮定法過去の用法" },
  { label: "【英語・高校在学】", q: "Please come as soon ( ) possible. 空所に入る語は？", choices: ["as", "than", "that"], answer: 0, explain: "as 〜 as possible は「できるだけ〜」。as soon as possible（できるだけ早く）" },
  { label: "【英語・高校在学】", q: "Neither of the boys ( ) the answer. 空所に入る語は？", choices: ["know", "knows", "knowing"], answer: 1, explain: "neither of 〜 は単数扱いが基本。（少年たちのどちらも答えを知らない）" },
  { label: "【英語・高校在学】", q: "Reading is to the mind ( ) food is to the body. 空所に入る語は？", choices: ["that", "what", "which"], answer: 1, explain: "A is to B what C is to D で「AとBの関係は、CとDの関係と同じだ」。（読書と心の関係は食べ物と体の関係のようなものだ）" },
  { label: "【英語・高校在学】", q: "You ought ( ) apologize to her. 空所に入る語は？", choices: ["to", "for", "of"], answer: 0, explain: "ought to ＋ 動詞の原形 は「〜すべきだ」。should に近い意味" },
  { label: "【英語・高校在学】", q: "She listened to music with her eyes ( ). 空所に入る語は？", choices: ["closing", "closed", "close"], answer: 1, explain: "with ＋ O ＋ 過去分詞 で付帯状況を表す。目は「閉じられる」側なので過去分詞 closed を使う" },
  { label: "【英語・高校在学】", q: "( ) been told to wait, he stayed in the room. 空所に入る語は？", choices: ["Having", "Being", "Be"], answer: 0, explain: "完了形の受動態の分詞構文は Having been ＋ 過去分詞。「待つように言われたので」と、主節より前の出来事を表す" },
  { label: "【英語・高校在学】", q: "If I had studied harder, I ( ) a better job now. 空所に入る語（句）は？", choices: ["would have", "would have had", "will have"], answer: 0, explain: "混合仮定法。If節が過去完了（過去の事実の反対）、主節が would ＋ 動詞の原形（現在の事実の反対）。now がヒント" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼女は私に、その本を読んだことがあるかと尋ねた」正しい文は？", choices: ["She asked me if I had read the book.", "She asked me if had I read the book.", "She asked me did I read the book."], answer: 0, explain: "間接疑問では〈if ＋ 主語 ＋ 動詞〉の語順。時制の一致により、read が had read になる" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼が去ってから10年になる」正しい文は？", choices: ["It is ten years when he left.", "It has been ten years since he left.", "It has been ten years from he left."], answer: 1, explain: "It has been 〜 since ... で「…してから〜になる」。since のあとは過去形（he left）" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼が嘘をついていたことに気づいた」正しい文は？", choices: ["I found out that he had been lying.", "I found out that he has been lie.", "I found out he was been lying."], answer: 0, explain: "気づいた時点より前から続いていたことは過去完了進行形（had been ＋ 〜ing）で表す" },
  { label: "【英語・高校在学】", q: "並べ替え：「あなたが何をしようと私は気にしない」正しい文は？", choices: ["I don't care what do you do.", "I don't care what you do.", "I don't care you do what."], answer: 1, explain: "間接疑問は〈疑問詞 ＋ 主語 ＋ 動詞〉の語順。疑問文の倒置（do you）にはならない" },
  { label: "【英語・高校在学】", q: "並べ替え：「私は彼女に電話するのを忘れてしまった」正しい文は？", choices: ["I forgot calling to her.", "I forgot to call her.", "I forgot call her to."], answer: 1, explain: "forget to 〜 は「〜するのを忘れる」。call は他動詞なので、to なしで her を直接続ける" },
  { label: "【英語・高校在学】", q: "並べ替え：「その計画は実行するのが難しい」正しい文は？", choices: ["The plan is difficult to carry out it.", "The plan is difficult carrying out.", "The plan is difficult to carry out."], answer: 2, explain: "difficult to 〜 の形では、主語（The plan）が不定詞の目的語にあたるため、it は入れない" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼は私にどこへ行くのかと尋ねた」正しい文は？", choices: ["He asked me where was I going.", "He asked me where I was going.", "He asked me where did I go."], answer: 1, explain: "間接疑問〈where ＋ 主語 ＋ 動詞〉。時制の一致で、「I am going」が「I was going」になる" },
  { label: "【英語・高校在学】", q: "並べ替え：「早く寝れば寝るほど、早く起きられる」正しい文は？", choices: ["The earlier you go to bed, the earlier you can get up.", "The more early you go to bed, the more early you can get up.", "The earlier you go to bed, you can get up the earlier."], answer: 0, explain: "the ＋ 比較級, the ＋ 比較級 の形。early は短い語なので -er をつける（more early とは言わない）" },
  { label: "【英語・高校在学】", q: "並べ替え：「部屋に入るとすぐに、彼女は泣き出した」正しい文は？", choices: ["On entering the room, she burst into tears.", "On enter the room, she burst into tears.", "On entered the room, she burst into tears."], answer: 0, explain: "on ～ing は「〜するとすぐに」（＝ as soon as 〜）。burst into tears は「わっと泣き出す」" },
  { label: "【英語・高校在学】", q: "並べ替え：「私はその仕事を彼に任せた」正しい文は？", choices: ["I left to him the job to.", "I left him to the job.", "I left the job to him."], answer: 2, explain: "leave A to B は「AをBに任せる」。（私はその仕事を彼に任せた）" },
  { label: "【英語・高校在学】", q: "He is the last man ( ) tell a lie. 空所に入る語は？", choices: ["to", "for", "of"], answer: 0, explain: "the last man to 〜 は「最も〜しそうにない人」。（彼は決して嘘をつくような人ではない）" },
  { label: "【英語・高校在学】", q: "All ( ) glitters is not gold. 空所に入る語は？", choices: ["which", "that", "what"], answer: 1, explain: "all のあとの関係代名詞は that を使う。All that glitters is not gold. は「光るものがすべて金とは限らない」（部分否定のことわざ）" },

  // ===== 英語（高校在学）301〜400問 =====
  { label: "【英語・高校在学】", q: "「accelerate」の意味は？", choices: ["〜を拒む", "〜を加速させる、速める", "〜に近づく"], answer: 1, explain: "The car accelerated quickly.（その車は急に加速した）。名詞は acceleration" },
  { label: "【英語・高校在学】", q: "「accessible」の意味は？", choices: ["利用しやすい、近づきやすい", "受け入れられない", "偶然の"], answer: 0, explain: "The museum is accessible by train.（その美術館は電車で行きやすい）。名詞は access" },
  { label: "【英語・高校在学】", q: "「acknowledge」の意味は？", choices: ["〜を知らせる", "〜を獲得する", "〜を認める"], answer: 2, explain: "He acknowledged his mistake.（彼は自分の誤りを認めた）。admit に近いが、よりかたい語" },
  { label: "【英語・高校在学】", q: "「adequate」の意味は？", choices: ["十分な、適切な", "熱心な", "同等の"], answer: 0, explain: "The room is adequate for six people.（その部屋は6人にとって十分な広さだ）。反対は inadequate" },
  { label: "【英語・高校在学】", q: "「ambition」の意味は？", choices: ["救急車", "大使", "野心、大志"], answer: 2, explain: "She has a strong ambition to become a leader.（彼女はリーダーになるという強い野心を持っている）。形容詞は ambitious" },
  { label: "【英語・高校在学】", q: "「analogy」の意味は？", choices: ["分析", "類推、たとえ", "類似品"], answer: 1, explain: "He explained the idea by using an analogy.（彼はたとえを使ってその考えを説明した）。analysis（分析）と区別する" },
  { label: "【英語・高校在学】", q: "「appreciate」の意味は？", choices: ["〜に感謝する、正しく評価する", "〜を近づける", "〜を逮捕する"], answer: 0, explain: "I appreciate your help.（お力添えに感謝します）。名詞は appreciation" },
  { label: "【英語・高校在学】", q: "「attain」の意味は？", choices: ["〜に出席する", "〜を達成する、〜に到達する", "〜を引きつける"], answer: 1, explain: "She attained her goal after years of effort.（彼女は何年もの努力の末に目標を達成した）。名詞は attainment" },
  { label: "【英語・高校在学】", q: "「authentic」の意味は？", choices: ["権威的な", "自動の", "本物の、信頼できる"], answer: 2, explain: "You can taste authentic Italian food here.（ここでは本場のイタリア料理が味わえる）" },
  { label: "【英語・高校在学】", q: "「beneficial」の意味は？", choices: ["有益な", "良心的な", "利益のない"], answer: 0, explain: "Exercise is beneficial to your health.（運動は健康に有益だ）。名詞 benefit は「利益」" },
  { label: "【英語・高校在学】", q: "「boost」の意味は？", choices: ["〜を押し上げる、高める", "〜を自慢する", "〜を縛る"], answer: 0, explain: "The campaign boosted sales.（そのキャンペーンは売り上げを押し上げた）。名詞でも使い、「後押し」の意味" },
  { label: "【英語・高校在学】", q: "「burden」の意味は？", choices: ["埋葬", "重荷、負担", "官僚"], answer: 1, explain: "The cost is a heavy burden for the family.（その費用は家族にとって重い負担だ）" },
  { label: "【英語・高校在学】", q: "「capacity」の意味は？", choices: ["首都", "性格", "収容力、能力"], answer: 2, explain: "The stadium has a capacity of 50,000.（そのスタジアムは5万人を収容できる）" },
  { label: "【英語・高校在学】", q: "「cease」の意味は？", choices: ["〜をやめる、終わる", "〜を捕まえる", "〜を引き起こす"], answer: 0, explain: "The noise ceased at last.（その騒音はついに止んだ）。stop よりかたい語" },
  { label: "【英語・高校在学】", q: "「coherent」の意味は？", choices: ["首尾一貫した、筋の通った", "けだるい", "協力的な"], answer: 0, explain: "She gave a coherent explanation.（彼女は筋の通った説明をした）。反対は incoherent" },
  { label: "【英語・高校在学】", q: "「commence」の意味は？", choices: ["〜を委託する", "〜を始める、始まる", "〜を命令する"], answer: 1, explain: "The ceremony will commence at ten.（式典は10時に始まる）。start / begin のかたい言い方" },
  { label: "【英語・高校在学】", q: "「concrete」（形容詞）の意味は？", choices: ["具体的な", "抽象的な", "あいまいな"], answer: 0, explain: "Please give me a concrete example.（具体的な例を挙げてください）。名詞では「コンクリート」の意味" },
  { label: "【英語・高校在学】", q: "「confront」の意味は？", choices: ["〜を確認する", "〜を混同する", "〜に直面する、立ち向かう"], answer: 2, explain: "She confronted the problem bravely.（彼女は勇敢にその問題に立ち向かった）。be confronted with 〜 は「〜に直面している」" },
  { label: "【英語・高校在学】", q: "「consensus」の意味は？", choices: ["国勢調査", "反対意見", "総意、合意"], answer: 2, explain: "The committee reached a consensus.（委員会は合意に達した）。census（国勢調査）と区別する" },
  { label: "【英語・高校在学】", q: "「contemporary」の意味は？", choices: ["一時的な", "現代の、同時代の", "伝統的な"], answer: 1, explain: "contemporary art（現代美術）。名詞では「同時代の人」の意味もある" },
  { label: "【英語・高校在学】", q: "「cultivate」の意味は？", choices: ["〜を耕す、養う", "〜を祝う", "〜を収集する"], answer: 0, explain: "Farmers cultivate the land.（農民は土地を耕す）。cultivate a habit は「習慣を身につける」" },
  { label: "【英語・高校在学】", q: "「curriculum」の意味は？", choices: ["好奇心", "カリキュラム、教育課程", "履歴書"], answer: 1, explain: "The school revised its curriculum.（学校はカリキュラムを見直した）。複数形は curricula" },
  { label: "【英語・高校在学】", q: "「decline」の意味は？", choices: ["減少する、衰える、〜を断る", "〜を飾る", "〜を宣言する"], answer: 0, explain: "The number of students is declining.（生徒数が減少している）。He declined the offer.（彼はその申し出を断った）" },
  { label: "【英語・高校在学】", q: "「deteriorate」の意味は？", choices: ["〜を決定する", "悪化する", "〜を破壊する"], answer: 1, explain: "His health deteriorated rapidly.（彼の健康状態は急速に悪化した）。名詞は deterioration" },
  { label: "【英語・高校在学】", q: "「dilemma」の意味は？", choices: ["ジレンマ、板挟み", "辞書", "外交"], answer: 0, explain: "I'm in a dilemma. I can't decide which job to take.（板挟みだ。どちらの仕事を選ぶか決められない）" },
  { label: "【英語・高校在学】", q: "「disclose」の意味は？", choices: ["〜を閉じる", "〜を明らかにする、公表する", "〜を割り引く"], answer: 1, explain: "The company refused to disclose the information.（その会社は情報の公開を拒んだ）。名詞は disclosure" },
  { label: "【英語・高校在学】", q: "「distribute」の意味は？", choices: ["〜を区別する", "〜を邪魔する", "〜を配布する、分配する"], answer: 2, explain: "They distributed food to the victims.（彼らは被災者に食料を配った）。名詞は distribution" },
  { label: "【英語・高校在学】", q: "「drastic」の意味は？", choices: ["劇的な、思い切った", "散文的な", "魅力的な"], answer: 0, explain: "We need to take drastic measures.（思い切った対策をとる必要がある）" },
  { label: "【英語・高校在学】", q: "「eligible」の意味は？", choices: ["雄弁な", "適格な、資格のある", "省略された"], answer: 1, explain: "You are eligible to vote at 18.（18歳で投票する資格がある）。be eligible for / to 〜 の形で使う" },
  { label: "【英語・高校在学】", q: "「embrace」の意味は？", choices: ["〜を抱きしめる、受け入れる", "〜を当惑させる", "〜を省略する"], answer: 0, explain: "The company embraced new technology.（その会社は新しい技術を受け入れた）。They embraced each other.（彼らは抱き合った）" },
  { label: "【英語・高校在学】", q: "「enforce」の意味は？", choices: ["〜を施行する、強制する", "〜を豊かにする", "〜を続ける"], answer: 0, explain: "The police enforce the law.（警察は法律を執行する）。名詞は enforcement" },
  { label: "【英語・高校在学】", q: "「essence」の意味は？", choices: ["本質、真髄", "試験", "存在"], answer: 0, explain: "The essence of the problem is trust.（その問題の本質は信頼だ）。形容詞 essential は「不可欠な」" },
  { label: "【英語・高校在学】", q: "「ethical」の意味は？", choices: ["民族の", "倫理的な、道徳上の", "感情的な"], answer: 1, explain: "It is not ethical to lie to patients.（患者にうそをつくのは倫理的でない）。名詞 ethics は「倫理」" },
  { label: "【英語・高校在学】", q: "「exploit」の意味は？", choices: ["〜を探検する", "〜を利用する、搾取する", "〜を暴露する"], answer: 1, explain: "They exploit cheap labor.（彼らは安い労働力を搾取している）。資源などを「活用する」の意味でも使う" },
  { label: "【英語・高校在学】", q: "「extinct」の意味は？", choices: ["絶滅した", "極端な", "外部の"], answer: 0, explain: "Dinosaurs became extinct millions of years ago.（恐竜は数百万年前に絶滅した）。名詞は extinction" },
  { label: "【英語・高校在学】", q: "「fluctuate」の意味は？", choices: ["〜を流す", "〜を強調する", "変動する、上下する"], answer: 2, explain: "Prices fluctuate from day to day.（物価は日々変動する）。名詞は fluctuation" },
  { label: "【英語・高校在学】", q: "「formulate」の意味は？", choices: ["〜を形づくる、系統立てて述べる", "〜を禁止する", "〜を忘れる"], answer: 0, explain: "She formulated a new plan.（彼女は新しい計画を練り上げた）。名詞 formula は「公式」" },
  { label: "【英語・高校在学】", q: "「hazard」の意味は？", choices: ["危険、危険要因", "ぼんやり", "収穫"], answer: 0, explain: "Smoking is a health hazard.（喫煙は健康上の危険要因だ）。形容詞は hazardous" },
  { label: "【英語・高校在学】", q: "「hostile」の意味は？", choices: ["病院の", "敵意のある", "ホテルの"], answer: 1, explain: "The crowd was hostile to the speaker.（群衆は演説者に敵意を示した）。名詞は hostility" },
  { label: "【英語・高校在学】", q: "「identical」の意味は？", choices: ["同一の、そっくりの", "理想的な", "身元の"], answer: 0, explain: "The twins look identical.（その双子はそっくりだ）。be identical to 〜 は「〜と同一だ」" },
  { label: "【英語・高校在学】", q: "「illustrate」の意味は？", choices: ["〜を照らす", "〜を説明する、例証する", "〜を病気にする"], answer: 1, explain: "The graph illustrates the change in population.（そのグラフは人口の変化を示している）。名詞は illustration（挿絵、例）" },
  { label: "【英語・高校在学】", q: "「immense」の意味は？", choices: ["計り知れない、膨大な", "即座の", "不道徳な"], answer: 0, explain: "an immense amount of data（膨大な量のデータ）。huge よりかたい語" },
  { label: "【英語・高校在学】", q: "「implication」の意味は？", choices: ["適用", "含意、影響", "複雑さ"], answer: 1, explain: "The study has important implications for education.（その研究は教育に重要な影響をもたらす）。動詞は imply（暗に示す）" },
  { label: "【英語・高校在学】", q: "「be inclined to 〜」の意味は？", choices: ["〜するのを避けたい", "〜する傾向がある、〜したい気がする", "〜しなければならない"], answer: 1, explain: "He is inclined to get angry easily.（彼は怒りっぽい）。I'm inclined to agree with you.（あなたに賛成したい気がする）" },
  { label: "【英語・高校在学】", q: "「incorporate」の意味は？", choices: ["〜を組み入れる、合併する", "〜を腐敗させる", "〜を訂正する"], answer: 0, explain: "We incorporated your ideas into the plan.（あなたの案を計画に組み入れた）" },
  { label: "【英語・高校在学】", q: "「indifferent」の意味は？", choices: ["異なる", "無関心な", "独立した"], answer: 1, explain: "He is indifferent to politics.（彼は政治に無関心だ）。be indifferent to 〜 の形で使う" },
  { label: "【英語・高校在学】", q: "「insight」の意味は？", choices: ["洞察、見識", "視界", "保険"], answer: 0, explain: "The book gave me a new insight into history.（その本は私に歴史への新しい洞察を与えてくれた）" },
  { label: "【英語・高校在学】", q: "「intervene」の意味は？", choices: ["〜を発明する", "介入する、仲裁する", "〜を面接する"], answer: 1, explain: "The teacher intervened in the quarrel.（先生がそのけんかに割って入った）。名詞は intervention" },
  { label: "【英語・高校在学】", q: "「isolate」の意味は？", choices: ["〜を単純化する", "〜を隔離する、孤立させる", "〜を見つける"], answer: 1, explain: "Patients with the disease are isolated.（その病気の患者は隔離される）。名詞は isolation" },
  { label: "【英語・高校在学】", q: "「justify」の意味は？", choices: ["〜を正当化する", "〜を判断する", "〜を結合する"], answer: 0, explain: "Nothing can justify violence.（何ものも暴力を正当化できない）。名詞は justification、justice は「正義」" },
  { label: "【英語・高校在学】", q: "「cope with 〜」の意味は？", choices: ["〜にうまく対処する", "〜を比較する", "〜と協力する"], answer: 0, explain: "How do you cope with stress?（ストレスにどう対処していますか）。deal with 〜 に近い意味" },
  { label: "【英語・高校在学】", q: "「take 〜 into account」の意味は？", choices: ["〜を口座に入れる", "〜を無視する", "〜を考慮に入れる"], answer: 2, explain: "You should take the cost into account.（費用を考慮に入れるべきだ）。take into consideration とほぼ同じ" },
  { label: "【英語・高校在学】", q: "「in the face of 〜」の意味は？", choices: ["〜の顔の前で", "〜に直面して、〜にもかかわらず", "〜のおかげで"], answer: 1, explain: "She stayed calm in the face of danger.（彼女は危険に直面しても冷静だった）" },
  { label: "【英語・高校在学】", q: "「on account of 〜」の意味は？", choices: ["〜のために（理由）", "〜を計算して", "〜の代わりに"], answer: 0, explain: "The game was delayed on account of rain.（雨のために試合は遅れた）。because of 〜 と同じ意味" },
  { label: "【英語・高校在学】", q: "「in the event of 〜」の意味は？", choices: ["〜の場合には", "〜の行事で", "結局〜になって"], answer: 0, explain: "In the event of an earthquake, stay calm.（地震の場合は、落ち着いていなさい）" },
  { label: "【英語・高校在学】", q: "「be prone to 〜」の意味は？", choices: ["〜を証明する", "〜しがちである、〜になりやすい", "〜に前向きだ"], answer: 1, explain: "He is prone to catching colds.（彼は風邪をひきやすい）。to の後ろは名詞・動名詞" },
  { label: "【英語・高校在学】", q: "「in line with 〜」の意味は？", choices: ["〜の列に並んで", "〜に反して", "〜に沿って、〜と一致して"], answer: 2, explain: "The plan is in line with our policy.（その計画は私たちの方針に沿っている）" },
  { label: "【英語・高校在学】", q: "「for the time being」の意味は？", choices: ["いつも", "時間のために", "当分の間、さしあたり"], answer: 2, explain: "You can stay here for the time being.（当分の間、ここにいていいよ）" },
  { label: "【英語・高校在学】", q: "「come to terms with 〜」の意味は？", choices: ["〜と条件を交渉する", "〜と折り合いをつける、〜を受け入れる", "〜の期限を決める"], answer: 1, explain: "It took him years to come to terms with the loss.（その喪失を受け入れるのに何年もかかった）" },
  { label: "【英語・高校在学】", q: "「live up to 〜」の意味は？", choices: ["〜まで生きる", "〜に住んで", "〜に応える、〜にふさわしく生きる"], answer: 2, explain: "He couldn't live up to his parents' expectations.（彼は両親の期待に応えられなかった）" },
  { label: "【英語・高校在学】", q: "「fall short of 〜」の意味は？", choices: ["〜に達しない、〜に及ばない", "〜を短くする", "〜に偶然出くわす"], answer: 0, explain: "The result fell short of our expectations.（結果は私たちの期待に及ばなかった）" },
  { label: "【英語・高校在学】", q: "「phase out 〜」の意味は？", choices: ["〜を始める", "〜を段階的に廃止する", "〜の段階を合わせる"], answer: 1, explain: "The government plans to phase out the old system.（政府は古い制度を段階的に廃止する予定だ）" },
  { label: "【英語・高校在学】", q: "( ) comes first will get a prize. 空所に入る語は？", choices: ["Whatever", "Whoever", "Whichever"], answer: 1, explain: "whoever は「〜する人は誰でも」（anyone who）。先行詞を含む複合関係代名詞で、名詞節をつくる" },
  { label: "【英語・高校在学】", q: "Take ( ) book you like. 空所に入る語は？", choices: ["whichever", "whoever", "whenever"], answer: 0, explain: "whichever ＋ 名詞 は「どちらの（どの）〜でも」。選択肢が限られている中から選ぶときに使う" },
  { label: "【英語・高校在学】", q: "( ) hard he tried, he couldn't win. 空所に入る語（句）は？", choices: ["No matter how", "No matter what", "Even if"], answer: 0, explain: "No matter how ＋ 形容詞（副詞）＋ 主語 ＋ 動詞 は「どんなに〜しても」。However 〜 と同じ意味" },
  { label: "【英語・高校在学】", q: "( ) he saw me, he ran away. 空所に入る語（句）は？", choices: ["The moment", "Since", "While"], answer: 0, explain: "the moment 〜 は「〜するとすぐに」（as soon as 〜）。the instant / the minute もほぼ同じ意味" },
  { label: "【英語・高校在学】", q: "Take an umbrella ( ) it rains. 空所に入る語（句）は？", choices: ["in case", "unless", "although"], answer: 0, explain: "in case 〜 は「〜するといけないから、万一〜の場合に備えて」。if とは意味が異なるので注意" },
  { label: "【英語・高校在学】", q: "He is not a teacher ( ) a doctor. 空所に入る語は？", choices: ["but", "and", "or"], answer: 0, explain: "not A but B は「AではなくB」。（彼は教師ではなく医者だ）" },
  { label: "【英語・高校在学】", q: "Neither he nor I ( ) wrong. 空所に入る語は？", choices: ["is", "am", "are"], answer: 1, explain: "neither A nor B が主語のとき、動詞は B（近いほうの主語）に合わせる。B が I なので am を使う" },
  { label: "【英語・高校在学】", q: "Either you or he ( ) responsible for this. 空所に入る語は？", choices: ["are", "be", "is"], answer: 2, explain: "either A or B が主語のとき、動詞は B（近いほうの主語）に合わせる。he は三人称単数なので is" },
  { label: "【英語・高校在学】", q: "He has three times as ( ) books as I do. 空所に入る語は？", choices: ["many", "much", "more"], answer: 0, explain: "倍数表現 〜 times as ＋ 原級 ＋ as … 。books は数えられる名詞なので many を使う" },
  { label: "【英語・高校在学】", q: "Man is the only animal ( ) can speak. 空所に入る語は？", choices: ["which", "that", "who"], answer: 1, explain: "先行詞に the only / the first / the last / all などがつくときは、関係代名詞は that が好まれる" },
  { label: "【英語・高校在学】", q: "That is the reason ( ) he was absent. 空所に入る語は？", choices: ["why", "what", "which"], answer: 0, explain: "reason が先行詞のときは、関係副詞 why を使う。This is why 〜（こういうわけで〜）の形でもよく使う" },
  { label: "【英語・高校在学】", q: "It is said ( ) he is rich. 空所に入る語は？", choices: ["that", "what", "to"], answer: 0, explain: "It is said that 〜 は「〜と言われている」。He is said to be rich. と書き換えられる" },
  { label: "【英語・高校在学】", q: "( ) beautiful she is! 空所に入る語は？", choices: ["What", "How", "So"], answer: 1, explain: "感嘆文：How ＋ 形容詞 ＋ 主語 ＋ 動詞！ 名詞がついていないので、What ではなく How を使う" },
  { label: "【英語・高校在学】", q: "Let's go to the park, ( )? 空所に入る語（句）は？", choices: ["will we", "shall we", "don't we"], answer: 1, explain: "Let's 〜 の付加疑問は shall we? を使う。Let me 〜 や命令文の付加疑問とは形が違う" },
  { label: "【英語・高校在学】", q: "Nobody came, ( )? 空所に入る語（句）は？", choices: ["did they", "didn't they", "did he"], answer: 0, explain: "nobody は否定の意味をもつので、付加疑問は肯定形にする。また、nobody は they で受ける" },
  { label: "【英語・高校在学】", q: "I'll call you when he ( ) here. 空所に入る語は？", choices: ["will arrive", "arrives", "arrive"], answer: 1, explain: "時を表す副詞節（when 〜）では、未来のことでも現在形を使う。主語が he なので arrives" },
  { label: "【英語・高校在学】", q: "He insisted on ( ) there alone. 空所に入る語（句）は？", choices: ["go", "to go", "going"], answer: 2, explain: "insist on 〜 の on は前置詞なので、後ろは動名詞（〜ing）。（彼はひとりでそこへ行くと言い張った）" },
  { label: "【英語・高校在学】", q: "He studied hard ( ) not to fail the exam. 空所に入る語は？", choices: ["so that", "in order", "for"], answer: 1, explain: "in order not to 〜 は「〜しないために」（目的の否定）。so as not to 〜 も同じ意味" },
  { label: "【英語・高校在学】", q: "Would you be so kind ( ) to show me the way? 空所に入る語は？", choices: ["as", "that", "enough"], answer: 0, explain: "so ＋ 形容詞 ＋ as to 〜 は「〜するほど…だ」。Would you be so kind as to 〜? は「〜していただけますか」というていねいな依頼" },
  { label: "【英語・高校在学】", q: "( ) it not been for your help, I would have failed. 空所に入る語は？", choices: ["Had", "Were", "Has"], answer: 0, explain: "If it had not been for 〜 の if を省略して倒置した形。「（あのとき）〜がなかったら」" },
  { label: "【英語・高校在学】", q: "It is essential that he ( ) present at the meeting. 空所に入る語（句）は？", choices: ["is", "be", "will be"], answer: 1, explain: "essential / important / necessary などのあとの that 節では、動詞は原形（仮定法現在）になる" },
  { label: "【英語・高校在学】", q: "If only I ( ) younger! 空所に入る語は？", choices: ["am", "were", "will be"], answer: 1, explain: "If only ＋ 仮定法過去 は「〜でありさえすれば（いいのに）」。I wish よりも強い願望を表す" },
  { label: "【英語・高校在学】", q: "( ) was his anger that he couldn't speak. 空所に入る語は？", choices: ["Such", "So", "Very"], answer: 0, explain: "Such ＋ be動詞 ＋ 主語 ＋ that 〜 は「〜するほど…だった」。Such が文頭に出た倒置表現" },
  { label: "【英語・高校在学】", q: "It is strange that he ( ) say such a thing. 空所に入る語は？", choices: ["should", "will", "shall"], answer: 0, explain: "驚き・意外・遺憾などを表す形容詞のあとの that 節では should を使うことがある（感情の should）" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼がいなかったら、私たちは勝てなかっただろう」正しい文は？", choices: ["If it had not been for him, we could not have won.", "If it had not been for him, we could not win.", "If it were not for him, we could not have won."], answer: 0, explain: "過去の事実と反対の仮定は、If it had not been for 〜, 主語 ＋ could not have ＋ 過去分詞" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼女に会ったのは、それが初めてだった」正しい文は？", choices: ["That was the first time I have met her.", "That was the first time I had met her.", "That was the first time I had meet her."], answer: 1, explain: "「それが〜した初めてだった」は、過去から見た経験なので、that 節の中は過去完了（had ＋ 過去分詞）にする" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼女は医者になることを夢見ている」正しい文は？", choices: ["She dreams to become a doctor.", "She dreams of becoming a doctor.", "She dreams becoming a doctor of."], answer: 1, explain: "dream of ～ing は「〜することを夢見る」。of は前置詞なので、後ろは動名詞" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼は私が思っていたほど若くない」正しい文は？", choices: ["He is not so young than I thought.", "He is not as young as I thought.", "He is not as younger as I thought."], answer: 1, explain: "not as（so）〜 as … は「…ほど〜ない」。as と as のあいだには原級を置く" },
  { label: "【英語・高校在学】", q: "並べ替え：「私たちの成功は、チームワークによるところが大きい」正しい文は？", choices: ["Our success is largely owing teamwork.", "Our success is largely due to teamwork.", "Our success is largely due of teamwork."], answer: 1, explain: "be due to 〜 は「〜のおかげだ、〜が原因だ」。owing to 〜 は前置詞の働きで、be 動詞のあとには置けない" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼女はその知らせを聞いて、喜びのあまり飛び上がった」正しい文は？", choices: ["She jumped for joy when hear she the news.", "She jumped for joy when she heard the news.", "She jumped by joy when she heard the news."], answer: 1, explain: "jump for joy は「喜びのあまり飛び上がる」。when のあとは〈主語 ＋ 動詞〉の語順" },
  { label: "【英語・高校在学】", q: "並べ替え：「見た目で人を判断してはいけない」正しい文は？", choices: ["You should not judge people with their appearance.", "You should not judge people by their appearance.", "You should not judge people at their appearance."], answer: 1, explain: "judge A by B は「BでAを判断する」。by は判断の基準を表す" },
  { label: "【英語・高校在学】", q: "並べ替え：「この問題に取り組むのはどうだろうか」正しい文は？", choices: ["How about to tackle this problem?", "How about tackle this problem?", "How about tackling this problem?"], answer: 2, explain: "How about ～ing? は「〜するのはどうですか」。about は前置詞なので、後ろは動名詞。tackle は「〜に取り組む」" },
  { label: "【英語・高校在学】", q: "I'd appreciate ( ) if you could help me. 空所に入る語は？", choices: ["it", "that", "this"], answer: 0, explain: "appreciate it if 〜 は「〜していただけるとありがたい」。appreciate は目的語に it が必要で、if 節を直接とれない" },
  { label: "【英語・高校在学】", q: "She has plenty ( ) friends. 空所に入る語は？", choices: ["of", "for", "to"], answer: 0, explain: "plenty of 〜 は「たくさんの〜」。数えられる名詞にも数えられない名詞にも使える" },
  { label: "【英語・高校在学】", q: "The students were divided ( ) two groups. 空所に入る語は？", choices: ["to", "into", "in"], answer: 1, explain: "divide A into B は「AをBに分ける」。into は変化・分割の結果を表す" },
  { label: "【英語・高校在学】", q: "He was accused ( ) stealing money. 空所に入る語は？", choices: ["for", "of", "with"], answer: 1, explain: "accuse A of B は「AをBのことで非難する（告発する）」。blame A for B と前置詞が違うので注意" },
  { label: "【英語・高校在学】", q: "She was absorbed ( ) reading. 空所に入る語は？", choices: ["in", "by", "on"], answer: 0, explain: "be absorbed in 〜 は「〜に没頭している」。be lost in 〜 / be devoted to 〜 も似た表現" },
  { label: "【英語・高校在学】", q: "I congratulated him ( ) passing the exam. 空所に入る語は？", choices: ["for", "on", "about"], answer: 1, explain: "congratulate A on B は「AをBのことで祝う」。（私は彼の試験合格を祝った）" },

// ===== 英語（高校在学）401〜500問 =====
  { label: "【英語・高校在学】", q: "「modest」の意味は？", choices: ["大げさな", "謙虚な、控えめな", "現代的な"], answer: 1, explain: "He is modest about his success.（彼は成功について控えめだ）。名詞は modesty" },
  { label: "【英語・高校在学】", q: "「notion」の意味は？", choices: ["通知", "国家", "概念、考え"], answer: 2, explain: "I have no notion of what he means.（彼の言いたいことがまったくわからない）。idea よりかたい語" },
  { label: "【英語・高校在学】", q: "「outcome」の意味は？", choices: ["結果、成果", "外出", "収入"], answer: 0, explain: "We are waiting for the outcome of the election.（私たちは選挙の結果を待っている）。result とほぼ同じ" },
  { label: "【英語・高校在学】", q: "「paradox」の意味は？", choices: ["平行線", "逆説、矛盾した事実", "楽園"], answer: 1, explain: "It is a paradox that the richer we become, the less time we have.（豊かになるほど時間がなくなるのは逆説的だ）" },
  { label: "【英語・高校在学】", q: "「plausible」の意味は？", choices: ["拍手の", "楽しい", "もっともらしい、納得できる"], answer: 2, explain: "His explanation sounds plausible.（彼の説明はもっともらしく聞こえる）。真実かどうかは別で、「ありそうな」というニュアンス" },
  { label: "【英語・高校在学】", q: "「potential」（形容詞）の意味は？", choices: ["力強い", "潜在的な、可能性のある", "詩的な"], answer: 1, explain: "a potential customer（見込み客）。名詞では「潜在能力、可能性」の意味" },
  { label: "【英語・高校在学】", q: "「precise」の意味は？", choices: ["貴重な", "圧縮した", "正確な、的確な"], answer: 2, explain: "Give me the precise time.（正確な時刻を教えて）。副詞は precisely（まさに）" },
  { label: "【英語・高校在学】", q: "「prejudice」の意味は？", choices: ["偏見", "優先", "準備"], answer: 0, explain: "There is still prejudice against foreigners.（外国人に対する偏見はまだある）" },
  { label: "【英語・高校在学】", q: "「profound」の意味は？", choices: ["豊富な", "深い、深遠な", "進歩的な"], answer: 1, explain: "The war had a profound effect on him.（戦争は彼に深い影響を与えた）" },
  { label: "【英語・高校在学】", q: "「prospect」の意味は？", choices: ["保護", "展望台", "見込み、見通し"], answer: 2, explain: "There is little prospect of success.（成功の見込みはほとんどない）。複数形 prospects で「将来性」" },
  { label: "【英語・高校在学】", q: "「radical」の意味は？", choices: ["根本的な、急進的な", "放射状の", "現実的な"], answer: 0, explain: "The company made radical changes.（その会社は抜本的な改革を行った）" },
  { label: "【英語・高校在学】", q: "「random」の意味は？", choices: ["乱暴な", "無作為の、でたらめな", "豊かな"], answer: 1, explain: "We chose the winners at random.（私たちは無作為に当選者を選んだ）。at random で「手当たり次第に」" },
  { label: "【英語・高校在学】", q: "「rational」の意味は？", choices: ["感情的な", "全国的な", "合理的な、理性的な"], answer: 2, explain: "Humans are rational animals.（人間は理性的な動物だ）。反対は irrational" },
  { label: "【英語・高校在学】", q: "「reside」の意味は？", choices: ["居住する", "抵抗する", "〜を返す"], answer: 0, explain: "He resides in Osaka.（彼は大阪に居住している）。live のかたい言い方で、名詞は resident（住民）" },
  { label: "【英語・高校在学】", q: "「restore」の意味は？", choices: ["〜を制限する", "〜を回復させる、修復する", "〜を保存する"], answer: 1, explain: "They restored the old temple.（彼らは古い寺を修復した）。名詞は restoration" },
  { label: "【英語・高校在学】", q: "「retain」の意味は？", choices: ["〜を引退させる", "〜を取り戻す", "〜を保持する"], answer: 2, explain: "She retained her calm in the emergency.（彼女は緊急時にも冷静さを保った）。keep のかたい言い方" },
  { label: "【英語・高校在学】", q: "「rigid」の意味は？", choices: ["厳格な、固い", "正しい", "穏やかな"], answer: 0, explain: "The school has rigid rules.（その学校には厳しい規則がある）。反対は flexible" },
  { label: "【英語・高校在学】", q: "「scope」の意味は？", choices: ["顕微鏡", "範囲、視野", "計画"], answer: 1, explain: "This question is beyond the scope of the study.（この問題は研究の範囲を超えている）" },
  { label: "【英語・高校在学】", q: "「skeptical」の意味は？", choices: ["科学的な", "皮肉な", "疑い深い、懐疑的な"], answer: 2, explain: "I'm skeptical about his story.（私は彼の話に懐疑的だ）。イギリス英語では sceptical とつづる" },
  { label: "【英語・高校在学】", q: "「sensible」の意味は？", choices: ["敏感な", "分別のある、賢明な", "感動的な"], answer: 1, explain: "It was sensible of you to wait.（待ったのは賢明だった）。「敏感な」は sensitive と区別する" },
  { label: "【英語・高校在学】", q: "「shift」の意味は？", choices: ["〜を共有する", "〜を輝かせる", "〜を移す、変化（する）"], answer: 2, explain: "There has been a shift in public opinion.（世論に変化があった）。名詞でも動詞でも使う" },
  { label: "【英語・高校在学】", q: "「sole」の意味は？", choices: ["唯一の", "柔らかい", "孤独な"], answer: 0, explain: "He is the sole survivor.（彼は唯一の生存者だ）。名詞では「足の裏」の意味もある" },
  { label: "【英語・高校在学】", q: "「stable」の意味は？", choices: ["馬小屋の", "安定した", "立派な"], answer: 1, explain: "The patient's condition is stable.（患者の容態は安定している）。名詞では「馬小屋」の意味" },
  { label: "【英語・高校在学】", q: "「strategy」の意味は？", choices: ["ストライキ", "構造", "戦略"], answer: 2, explain: "We need a new marketing strategy.（新しい販売戦略が必要だ）。形容詞は strategic" },
  { label: "【英語・高校在学】", q: "「submit」の意味は？", choices: ["〜を提出する、服従する", "〜を潜水する", "〜を補う"], answer: 0, explain: "Submit your report by Friday.（金曜日までにレポートを提出しなさい）。名詞は submission" },
  { label: "【英語・高校在学】", q: "「subsequent」の意味は？", choices: ["主観的な", "その後の", "実質的な"], answer: 1, explain: "subsequent events（その後の出来事）。subsequent to 〜 は「〜のあとで」" },
  { label: "【英語・高校在学】", q: "「supplement」の意味は？", choices: ["〜を供給する", "〜を抑える", "〜を補う、補足"], answer: 2, explain: "He supplements his income by working at night.（彼は夜に働いて収入を補っている）。名詞では「サプリメント、補足」" },
  { label: "【英語・高校在学】", q: "「surge」の意味は？", choices: ["急増、急上昇", "手術", "外科医"], answer: 0, explain: "There was a surge in demand.（需要が急増した）。動詞でも「急上昇する」" },
  { label: "【英語・高校在学】", q: "「suspend」の意味は？", choices: ["〜を疑う", "〜を一時停止する、つるす", "〜を支える"], answer: 1, explain: "The train service was suspended because of the typhoon.（台風で電車の運行が一時停止された）。名詞は suspension" },
  { label: "【英語・高校在学】", q: "「thrive」の意味は？", choices: ["〜を投げる", "〜を脅す", "栄える、繁栄する"], answer: 2, explain: "Small businesses thrive in this town.（この町では小さな商売が栄えている）" },
  { label: "【英語・高校在学】", q: "「trigger」の意味は？", choices: ["〜を引き起こす、引き金", "〜を裏切る", "〜を悩ます"], answer: 0, explain: "The news triggered a panic.（そのニュースがパニックを引き起こした）。名詞では「引き金」" },
  { label: "【英語・高校在学】", q: "「ultimate」の意味は？", choices: ["最新の", "究極の、最終的な", "極端な"], answer: 1, explain: "Our ultimate goal is world peace.（私たちの最終目標は世界平和だ）。副詞は ultimately（結局は）" },
  { label: "【英語・高校在学】", q: "「undertake」の意味は？", choices: ["〜を理解する", "〜を下に置く", "〜を引き受ける、着手する"], answer: 2, explain: "She undertook the task of organizing the event.（彼女はイベントを企画する仕事を引き受けた）" },
  { label: "【英語・高校在学】", q: "「utilize」の意味は？", choices: ["〜を活用する", "〜を役立たなくする", "〜を公共化する"], answer: 0, explain: "We should utilize renewable energy.（再生可能エネルギーを活用すべきだ）。use のかたい言い方" },
  { label: "【英語・高校在学】", q: "「vital」の意味は？", choices: ["活発でない", "極めて重要な、生命の", "視覚の"], answer: 1, explain: "Water is vital to life.（水は生命にとって不可欠だ）。vital signs は「生命兆候」" },
  { label: "【英語・高校在学】", q: "「vulnerable」の意味は？", choices: ["価値のある", "自発的な", "傷つきやすい、弱い"], answer: 2, explain: "Children are vulnerable to disease.（子どもは病気にかかりやすい）。be vulnerable to 〜 の形で使う" },
  { label: "【英語・高校在学】", q: "「widespread」の意味は？", choices: ["広範囲にわたる", "幅の広い", "散らばった"], answer: 0, explain: "There is widespread support for the plan.（その計画は広く支持されている）" },
  { label: "【英語・高校在学】", q: "「withdraw」の意味は？", choices: ["〜を乾かす", "〜を引き出す、撤退する", "〜を描く"], answer: 1, explain: "He withdrew money from his account.（彼は口座からお金を引き出した）。活用は withdraw - withdrew - withdrawn" },
  { label: "【英語・高校在学】", q: "「yield」の意味は？", choices: ["〜を叫ぶ", "〜を黄色くする", "〜を産出する、譲る"], answer: 2, explain: "The farm yields a lot of rice.（その農場は多くの米を産出する）。yield to 〜 で「〜に屈する」" },
  { label: "【英語・高校在学】", q: "「comprise」の意味は？", choices: ["〜から成る、〜を構成する", "〜を妥協する", "〜を理解する"], answer: 0, explain: "The team comprises ten members.（そのチームは10人のメンバーから成る）。comprehend（理解する）と区別する" },
  { label: "【英語・高校在学】", q: "「in light of 〜」の意味は？", choices: ["〜の軽さで", "〜を考慮して、〜に照らして", "〜を照らして"], answer: 1, explain: "In light of the new data, we changed the plan.（新しいデータを考慮して、計画を変更した）" },
  { label: "【英語・高校在学】", q: "「at all costs」の意味は？", choices: ["安く", "全費用を払って", "どんな犠牲を払っても"], answer: 2, explain: "We must avoid war at all costs.（どんな犠牲を払っても戦争を避けなければならない）" },
  { label: "【英語・高校在学】", q: "「in the absence of 〜」の意味は？", choices: ["〜がない場合には、〜がいないときに", "〜の欠席のために", "〜が存在して"], answer: 0, explain: "In the absence of evidence, he was set free.（証拠がなかったため、彼は釈放された）" },
  { label: "【英語・高校在学】", q: "「with a view to ～ing」の意味は？", choices: ["〜を見渡して", "〜する目的で、〜するつもりで", "〜の景色を見て"], answer: 1, explain: "He saved money with a view to buying a house.（彼は家を買うつもりでお金を貯めた）。to の後ろは動名詞" },
  { label: "【英語・高校在学】", q: "「as far as I am concerned」の意味は？", choices: ["私が心配する限り", "私に近づく限り", "私に関する限り、私としては"], answer: 2, explain: "As far as I am concerned, you can go.（私としては、行ってもかまわない）" },
  { label: "【英語・高校在学】", q: "「run the risk of ～ing」の意味は？", choices: ["〜する危険を冒す", "〜する危険から逃げる", "〜する危険がない"], answer: 0, explain: "You run the risk of losing your job.（あなたは職を失う危険を冒している）" },
  { label: "【英語・高校在学】", q: "「pay off」の意味は？", choices: ["〜を支払って去る", "うまくいく、報われる", "〜を延期する"], answer: 1, explain: "His hard work finally paid off.（彼の努力がついに報われた）。借金などを「完済する」の意味でも使う" },
  { label: "【英語・高校在学】", q: "「back up 〜」の意味は？", choices: ["〜を後ろへ進める", "〜を延期する", "〜を支持する、バックアップをとる"], answer: 2, explain: "Please back up your files.（ファイルのバックアップをとってください）。I'll back you up.（あなたを支持するよ）" },
  { label: "【英語・高校在学】", q: "「step down」の意味は？", choices: ["辞任する、退く", "〜を踏みつける", "階段を上がる"], answer: 0, explain: "The president stepped down last month.（社長は先月辞任した）" },
  { label: "【英語・高校在学】", q: "「hold back 〜」の意味は？", choices: ["〜を手伝う", "〜を抑える、控える", "〜を保管する"], answer: 1, explain: "She held back her tears.（彼女は涙をこらえた）" },
  { label: "【英語・高校在学】", q: "Suppose you ( ) a million yen now, what would you do? 空所に入る語（句）は？", choices: ["win", "would win", "won"], answer: 2, explain: "Suppose（もし〜なら）のあとに仮定法過去を続け、現在の事実と反対の仮定を表せる。主節は would ＋ 動詞の原形" },
  { label: "【英語・高校在学】", q: "He acted as though nothing ( ) happened. 空所に入る語は？", choices: ["has", "had", "have"], answer: 1, explain: "as though（as if）のあとに過去完了を使うと、「まるで〜だったかのように」（主節より前のことについての仮定）" },
  { label: "【英語・高校在学】", q: "Without your help, I ( ) have succeeded. 空所に入る語は？", choices: ["couldn't", "can't", "won't"], answer: 0, explain: "Without 〜 は「〜がなかったら」。過去の事実と反対なので、could not have ＋ 過去分詞 とする" },
  { label: "【英語・高校在学】", q: "He ( ) have missed the train. He isn't here yet. 空所に入る語は？", choices: ["would", "may", "need"], answer: 1, explain: "may have ＋ 過去分詞 は「〜したかもしれない」（過去についての推量）" },
  { label: "【英語・高校在学】", q: "You ought to ( ) told me earlier. 空所に入る語は？", choices: ["have", "had", "has"], answer: 0, explain: "ought to have ＋ 過去分詞 は「〜すべきだったのに」。should have ＋ 過去分詞 とほぼ同じ意味" },
  { label: "【英語・高校在学】", q: "He ( ) to live in a small town. 空所に入る語は？", choices: ["would", "used", "was"], answer: 1, explain: "過去の状態（live や be）は used to で表す。would は過去の習慣的な動作には使えるが、状態動詞には使えない" },
  { label: "【英語・高校在学】", q: "You had better ( ) late for the meeting. 空所に入る語（句）は？", choices: ["not be", "be not", "not to be"], answer: 0, explain: "had better の否定形は had better not ＋ 動詞の原形。（会議に遅れないほうがいい）" },
  { label: "【英語・高校在学】", q: "( ) what to do, she asked her teacher for advice. 空所に入る語（句）は？", choices: ["Knowing not", "Not known", "Not knowing"], answer: 2, explain: "分詞構文の否定形は、分詞の直前に not を置く。（何をすべきかわからなかったので、先生に助言を求めた）" },
  { label: "【英語・高校在学】", q: "( ) speaking, women live longer than men. 空所に入る語は？", choices: ["Generally", "General", "Generalize"], answer: 0, explain: "Generally speaking は「一般的に言えば」。慣用的な分詞構文で、主語が一致しなくても使える" },
  { label: "【英語・高校在学】", q: "( ) his age, he is very strong. 空所に入る語は？", choices: ["Considered", "Considering", "Consider"], answer: 1, explain: "considering 〜 は「〜のわりには、〜を考えると」。慣用的な分詞構文で、前置詞のようにも使える" },
  { label: "【英語・高校在学】", q: "This is the house, the roof ( ) is red. 空所に入る語（句）は？", choices: ["which", "whose of", "of which"], answer: 2, explain: "the roof of which is red（その屋根が赤い家）。whose roof is red とも言える。of which は物が先行詞のときに使う" },
  { label: "【英語・高校在学】", q: "She has three sons, ( ) are doctors. 空所に入る語（句）は？", choices: ["all of whom", "all of which", "all them"], answer: 0, explain: "〈数量表現 ＋ of whom〉の形で、人を先行詞とする非制限用法。（彼女には3人の息子がいて、全員が医者だ）" },
  { label: "【英語・高校在学】", q: "He is what is ( ) a genius. 空所に入る語は？", choices: ["calling", "called", "call"], answer: 1, explain: "what is called 〜 は「いわゆる〜」。（彼はいわゆる天才だ）。what we call 〜 とも言う" },
  { label: "【英語・高校在学】", q: "( ), it began to rain. 空所に入る語（句）は？", choices: ["To worse make matters", "Making matters worst", "To make matters worse"], answer: 2, explain: "to make matters worse は「さらに悪いことに」。慣用的な不定詞表現" },
  { label: "【英語・高校在学】", q: "He is, so to ( ), a walking dictionary. 空所に入る語は？", choices: ["speak", "say", "tell"], answer: 0, explain: "so to speak は「いわば」。慣用的な不定詞表現" },
  { label: "【英語・高校在学】", q: "( ) to say, health is more important than money. 空所に入る語は？", choices: ["Needing", "Needless", "Need"], answer: 1, explain: "needless to say は「言うまでもなく」。It goes without saying that 〜 と同じ意味" },
  { label: "【英語・高校在学】", q: "She speaks French, not to ( ) English. 空所に入る語は？", choices: ["say", "mention", "talk"], answer: 1, explain: "not to mention 〜 は「〜は言うまでもなく」。to say nothing of 〜 / let alone 〜 も近い意味" },
  { label: "【英語・高校在学】", q: "It goes without saying that health is important. この文の意味は？", choices: ["健康が大切だとは言えない", "言うまでもなく健康は大切だ", "健康について話さないほうがよい"], answer: 1, explain: "It goes without saying that 〜 は「〜は言うまでもない」" },
  { label: "【英語・高校在学】", q: "He is far from ( ) a liar. 空所に入る語は？", choices: ["be", "to be", "being"], answer: 2, explain: "far from ～ing / 名詞 は「決して〜ではない」。from は前置詞なので、後ろは動名詞" },
  { label: "【英語・高校在学】", q: "She is anything but shy. この文の意味は？", choices: ["決して内気ではない", "内気以外なら何でもある", "とても内気だ"], answer: 0, explain: "anything but 〜 は「決して〜ではない」。nothing but 〜 は「〜だけ、〜にすぎない」" },
  { label: "【英語・高校在学】", q: "He did nothing but ( ) all day. 空所に入る語（句）は？", choices: ["to cry", "cry", "crying"], answer: 1, explain: "do nothing but ＋ 動詞の原形 は「〜ばかりしている」。but の前に do があるときは to をつけない" },
  { label: "【英語・高校在学】", q: "You cannot be too careful. この文の意味は？", choices: ["注意しすぎてはいけない", "注意しなくてもよい", "いくら注意してもしすぎることはない"], answer: 2, explain: "cannot 〜 too … は「いくら〜しても…しすぎることはない」" },
  { label: "【英語・高校在学】", q: "The work is all but finished. この文の意味は？", choices: ["ほとんど終わっている", "まったく終わっていない", "終わっているもの以外すべてだ"], answer: 0, explain: "all but 〜 は「ほとんど〜、〜以外すべて」。形容詞や動詞の前では「ほとんど〜」の意味になる" },
  { label: "【英語・高校在学】", q: "This camera is superior ( ) that one. 空所に入る語は？", choices: ["than", "to", "from"], answer: 1, explain: "superior / inferior / senior / junior は比較に than ではなく to を使う（ラテン語系比較級）" },
  { label: "【英語・高校在学】", q: "Tom is two years senior ( ) me. 空所に入る語は？", choices: ["to", "than", "of"], answer: 0, explain: "senior to 〜 は「〜より年上（上位）だ」。than ではなく to を使う" },
  { label: "【英語・高校在学】", q: "As ( ) as 500 people attended the event. 空所に入る語は？", choices: ["much", "more", "many"], answer: 2, explain: "as many as ＋ 数 は「〜もの（数が多いことを強調）」。people は数えられるので many" },
  { label: "【英語・高校在学】", q: "Seldom ( ) he visit his parents. 空所に入る語は？", choices: ["does", "is", "has"], answer: 0, explain: "Seldom（めったに〜ない）が文頭に出ると倒置になる。一般動詞の現在形なので does ＋ 主語 ＋ 原形" },
  { label: "【英語・高校在学】", q: "( ) you need help, call me. 空所に入る語は？", choices: ["Would", "Should", "Did"], answer: 1, explain: "Should ＋ 主語 ＋ 原形 は、If you should need help の if を省略した倒置形。「万一〜なら」" },
  { label: "【英語・高校在学】", q: "He didn't call, nor ( ) he write. 空所に入る語は？", choices: ["did", "does", "has"], answer: 0, explain: "nor が文中にくると、あとは倒置になる。前の文が過去形（didn't call）なので did を使う" },
  { label: "【英語・高校在学】", q: "Not until he left ( ) I notice the mistake. 空所に入る語は？", choices: ["had", "did", "was"], answer: 1, explain: "Not until 〜 が文頭に出ると、主節が倒置になる。（彼が去ってはじめて、私は間違いに気づいた）" },
  { label: "【英語・高校在学】", q: "The room was empty ( ) a small table. 空所に入る語（句）は？", choices: ["except for", "except of", "excepting to"], answer: 0, explain: "except for 〜 は「〜を除いて、〜以外は」。全体の内容に対して例外を述べるときに使う" },
  { label: "【英語・高校在学】", q: "Apart ( ) the price, it's a good deal. 空所に入る語は？", choices: ["for", "from", "of"], answer: 1, explain: "apart from 〜 は「〜は別として、〜に加えて」。aside from 〜 も同じ意味" },
  { label: "【英語・高校在学】", q: "He was made ( ) clean the room. 空所に入る語は？", choices: ["for", "at", "to"], answer: 2, explain: "make ＋ O ＋ 原形 の受け身は、be made to ＋ 原形。受け身では to が必要になる" },
  { label: "【英語・高校在学】", q: "He said to me, 「Where do you live?」を間接話法にすると、He asked me where I ( ). 空所に入る語は？", choices: ["lived", "live", "do live"], answer: 0, explain: "疑問詞を使う疑問文は〈疑問詞 ＋ 主語 ＋ 動詞〉の語順にし、時制を過去に一致させる" },
  { label: "【英語・高校在学】", q: "I was about to leave ( ) the phone rang. 空所に入る語は？", choices: ["while", "when", "as soon"], answer: 1, explain: "be about to 〜 when ... は「まさに〜しようとしたとき…」" },
  { label: "【英語・高校在学】", q: "There is ( ) any milk left. 空所に入る語は？", choices: ["hard", "hardy", "hardly"], answer: 2, explain: "hardly any 〜 は「ほとんど〜ない」。hardly は否定の意味をもつ副詞" },
  { label: "【英語・高校在学】", q: "What do you say to ( ) a walk? 空所に入る語は？", choices: ["taking", "take", "to take"], answer: 0, explain: "What do you say to ～ing? は「〜するのはどうですか」。to は前置詞なので、後ろは動名詞" },
  { label: "【英語・高校在学】", q: "He ran fast lest he ( ) late. 空所に入る語（句）は？", choices: ["was", "is", "should be"], answer: 2, explain: "lest ＋ 主語 ＋ should ＋ 原形 は「〜しないように」。lest 自体に否定の意味がある" },
  { label: "【英語・高校在学】", q: "( ) you understand the rule, the game is easy. 空所に入る語は？", choices: ["Once", "Even", "Until"], answer: 0, explain: "once 〜 は接続詞で「いったん〜すれば」。（いったんルールを理解すれば、そのゲームは簡単だ）" },
  { label: "【英語・高校在学】", q: "No wonder he is tired. この文の意味は？", choices: ["彼が疲れているのは不思議だ", "彼が疲れているのも無理はない", "彼は疲れていないにちがいない"], answer: 1, explain: "No wonder 〜 は「〜も不思議ではない、〜も当然だ」。It is no wonder that 〜 の省略形" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼がそんなに早く来るとは思わなかった」正しい文は？", choices: ["I didn't expect him to come so early.", "I didn't expect he to come so early.", "I didn't expect him come so early."], answer: 0, explain: "expect ＋ 人 ＋ to 不定詞 で「人が〜すると思う（予期する）」。人は目的格（him）にする" },
  { label: "【英語・高校在学】", q: "並べ替え：「私は彼に駅まで送ってもらった」正しい文は？", choices: ["I had him to take me to the station.", "I had him take me to the station.", "I had taken him me to the station."], answer: 1, explain: "have ＋ 人 ＋ 原形 で「人に〜してもらう（させる）」。to は不要" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼女は話すより聞くほうが好きだ」正しい文は？", choices: ["She prefers listening than speaking.", "She prefers to listen than to speak.", "She prefers listening to speaking."], answer: 2, explain: "prefer A to B（AをBより好む）。A と B が動名詞のときは prefer ～ing to ～ing の形" },
  { label: "【英語・高校在学】", q: "並べ替え：「私がいちばん気に入っているのは、この絵だ」正しい文は？", choices: ["What I like best is this picture.", "What is I like best this picture.", "That I like best is this picture."], answer: 0, explain: "関係代名詞 what ＋ 主語 ＋ 動詞 は「〜するもの（こと）」。名詞のかたまりとして文の主語になる" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼女は私に電話をかけ直すと約束した」正しい文は？", choices: ["She promised calling me back.", "She promised to call me back.", "She promised me to calling back."], answer: 1, explain: "promise to 〜 は「〜すると約束する」。promise は不定詞をとり、動名詞はとらない" },
  { label: "【英語・高校在学】", q: "並べ替え：「彼は私に、遅れないようにと言った」正しい文は？", choices: ["He told me not to be late.", "He told me to not being late.", "He told me don't be late."], answer: 0, explain: "tell ＋ 人 ＋ not to 〜 で「人に〜しないように言う」。否定形の不定詞は not を to の前に置く" },
  { label: "【英語・高校在学】", q: "I can't make ( ) what he is saying. 空所に入る語は？", choices: ["out", "up", "off"], answer: 0, explain: "make out 〜 は「〜を理解する、聞き取る」。make up は「でっち上げる、化粧する」" },
  { label: "【英語・高校在学】", q: "Do you mind ( ) I open the window? 空所に入る語は？", choices: ["that", "whether to", "if"], answer: 2, explain: "Do you mind if 〜? は「〜してもよろしいですか」。許可を求める表現で、「いいですよ」は Not at all." },
  { label: "【英語・高校在学】", q: "The bridge is ( ) construction. 空所に入る語は？", choices: ["in", "on", "under"], answer: 2, explain: "under construction は「建設中」。under repair は「修理中」、under discussion は「議論中」" },
  { label: "【英語・高校在学】", q: "She was ( ) to tears by the sad story. 空所に入る語は？", choices: ["moving", "moved", "move"], answer: 1, explain: "be moved to tears は「感動して涙を流す」。人が感動するときは過去分詞 moved を使う" },

  { label: "【英語・大学受験】", q: "「coincide」の意味は？", choices: ["同時に起こる、一致する", "〜を協力させる", "〜を数える"], answer: 0, explain: "Her birthday coincides with the national holiday.（彼女の誕生日は祝日と重なる）。名詞は coincidence（偶然の一致）" },
  { label: "【英語・大学受験】", q: "「deduce」の意味は？", choices: ["〜を差し引く", "〜を推論する、演繹する", "〜を減らす"], answer: 1, explain: "We can deduce the cause from the evidence.（証拠から原因を推論できる）。deduct（差し引く）と区別する" },
  { label: "【英語・大学受験】", q: "「hierarchy」の意味は？", choices: ["調和", "遺産", "階層、序列"], answer: 2, explain: "The company has a strict hierarchy.（その会社には厳格な序列がある）。形容詞は hierarchical" },
  { label: "【英語・大学受験】", q: "「inherent」の意味は？", choices: ["固有の、本来備わっている", "遺伝の", "敵意のある"], answer: 0, explain: "Risk is inherent in any investment.（どんな投資にもリスクは本来つきものだ）。be inherent in 〜 の形で使う" },
  { label: "【英語・大学受験】", q: "「lucrative」の意味は？", choices: ["ばかげた", "明るい", "儲かる、有利な"], answer: 2, explain: "He has a lucrative business.（彼は儲かる事業を持っている）" },
  { label: "【英語・大学受験】", q: "「mundane」の意味は？", choices: ["世界的な", "ありふれた、平凡な", "神秘的な"], answer: 1, explain: "She is tired of mundane daily routines.（彼女は平凡な毎日の繰り返しにうんざりしている）" },
  { label: "【英語・大学受験】", q: "「notorious」の意味は？", choices: ["悪名高い", "目立たない", "高貴な"], answer: 0, explain: "The city is notorious for its heavy traffic.（その都市はひどい渋滞で悪名高い）。famous と違い悪い意味で使う" },
  { label: "【英語・大学受験】", q: "「obsolete」の意味は？", choices: ["必要な", "明白な", "時代遅れの、廃れた"], answer: 2, explain: "This technology is already obsolete.（この技術はもう時代遅れだ）" },
  { label: "【英語・大学受験】", q: "「paramount」の意味は？", choices: ["並行した", "最高に重要な", "平均的な"], answer: 1, explain: "Safety is of paramount importance.（安全は何よりも重要だ）" },
  { label: "【英語・大学受験】", q: "「peculiar」の意味は？", choices: ["独特の、奇妙な", "ふつうの", "ていねいな"], answer: 0, explain: "He has a peculiar habit of talking to himself.（彼には独り言を言う奇妙な癖がある）。be peculiar to 〜 は「〜に特有だ」" },
  { label: "【英語・大学受験】", q: "「pragmatic」の意味は？", choices: ["理論的な", "熱心な", "実利的な、実用的な"], answer: 2, explain: "She takes a pragmatic approach to problems.（彼女は問題に実際的な方法で取り組む）" },
  { label: "【英語・大学受験】", q: "「reconcile」の意味は？", choices: ["〜を認識する", "〜を和解させる、調和させる", "〜を復元する"], answer: 1, explain: "It is hard to reconcile work with family life.（仕事と家庭生活を両立させるのは難しい）。名詞は reconciliation" },
  { label: "【英語・大学受験】", q: "「render」の意味は？", choices: ["〜を借りる", "〜を取り除く", "〜を（ある状態に）する、与える"], answer: 2, explain: "The news rendered him speechless.（その知らせは彼を言葉も出ない状態にした）。render A B は「AをBの状態にする」" },
  { label: "【英語・大学受験】", q: "「resemble」の意味は？", choices: ["〜を再び集める", "〜を保留する", "〜に似ている"], answer: 2, explain: "She resembles her mother.（彼女は母親に似ている）。他動詞なので前置詞は不要で、進行形・受け身にもしない" },
  { label: "【英語・大学受験】", q: "「scrutiny」の意味は？", choices: ["綿密な調査、精査", "秘密", "懐疑"], answer: 0, explain: "The plan is under close scrutiny.（その計画は綿密な調査を受けている）。動詞は scrutinize" },
  { label: "【英語・大学受験】", q: "「spontaneous」の意味は？", choices: ["持続的な", "自動の", "自発的な、自然に起こる"], answer: 2, explain: "The crowd gave a spontaneous cheer.（群衆は思わず歓声を上げた）。副詞は spontaneously" },
  { label: "【英語・大学受験】", q: "「tangible」の意味は？", choices: ["微妙な", "触れることのできる、具体的な", "大きな"], answer: 1, explain: "There is no tangible evidence.（具体的な証拠はない）。反対は intangible" },
  { label: "【英語・大学受験】", q: "「tentative」の意味は？", choices: ["緊張した", "確固たる", "暫定的な、仮の"], answer: 2, explain: "They reached a tentative agreement.（彼らは暫定的な合意に達した）" },
  { label: "【英語・大学受験】", q: "「trivial」の意味は？", choices: ["取るに足らない、些細な", "真実の", "三角形の"], answer: 0, explain: "Don't worry about such a trivial matter.（そんな些細なことは気にするな）" },
  { label: "【英語・大学受験】", q: "「unprecedented」の意味は？", choices: ["予想外の", "前例のない", "計画的な"], answer: 1, explain: "The country faces an unprecedented crisis.（その国は前例のない危機に直面している）。precedent は「前例」" },
  { label: "【英語・大学受験】", q: "「verify」の意味は？", choices: ["〜を変える", "〜を多様化する", "〜を確かめる、検証する"], answer: 2, explain: "Please verify your identity.（身元を確認してください）。名詞は verification" },
  { label: "【英語・大学受験】", q: "「mitigate」の意味は？", choices: ["〜を和らげる、軽減する", "〜を移動する", "〜を悪化させる"], answer: 0, explain: "Trees mitigate the effects of heat.（樹木は暑さの影響を和らげる）" },
  { label: "【英語・大学受験】", q: "「alleviate」の意味は？", choices: ["〜を同盟させる", "〜を割り当てる", "〜を軽減する、和らげる"], answer: 2, explain: "This medicine will alleviate the pain.（この薬は痛みを和らげる）" },
  { label: "【英語・大学受験】", q: "「perceive」の意味は？", choices: ["〜を受け取る", "〜を知覚する、気づく", "〜を認可する"], answer: 1, explain: "Dogs perceive sounds that humans cannot hear.（犬は人間に聞こえない音を知覚する）。名詞は perception" },
  { label: "【英語・大学受験】", q: "「inhibit」の意味は？", choices: ["〜に住む", "〜を展示する", "〜を抑制する、妨げる"], answer: 2, explain: "Fear can inhibit learning.（恐怖は学習を妨げることがある）。inhabit（住む）と区別する" },
  { label: "【英語・大学受験】", q: "「undermine」の意味は？", choices: ["〜を地下に作る", "〜を理解する", "〜を弱体化させる、むしばむ"], answer: 2, explain: "Constant criticism undermined his confidence.（絶え間ない批判が彼の自信をむしばんだ）" },
  { label: "【英語・大学受験】", q: "「perish」の意味は？", choices: ["〜を完成する", "滅びる、死ぬ", "〜を仕上げる"], answer: 1, explain: "Many people perished in the fire.（その火事で多くの人が命を落とした）。形容詞 perishable は「腐りやすい」" },
  { label: "【英語・大学受験】", q: "「ponder」の意味は？", choices: ["〜を重くする", "〜を池に捨てる", "〜を熟考する"], answer: 2, explain: "She pondered the question for a long time.（彼女は長い間その問題をじっくり考えた）" },
  { label: "【英語・大学受験】", q: "「prevalent」の意味は？", choices: ["広く行き渡った、流行している", "優先的な", "先行する"], answer: 0, explain: "This disease is prevalent among children.（この病気は子どもによく見られる）。動詞は prevail" },
  { label: "【英語・大学受験】", q: "「contemplate」の意味は？", choices: ["〜を飾る", "〜をじっくり考える", "〜を比較する"], answer: 1, explain: "He contemplated changing his job.（彼は転職を考えていた）。後ろは動名詞" },
  { label: "【英語・大学受験】", q: "「disparity」の意味は？", choices: ["絶望", "分散", "格差、相違"], answer: 2, explain: "There is a large disparity between rich and poor.（貧富の間には大きな格差がある）" },
  { label: "【英語・大学受験】", q: "「fiscal」の意味は？", choices: ["財政上の", "物理的な", "魚の"], answer: 0, explain: "The fiscal year starts in April in Japan.（日本の会計年度は4月に始まる）" },
  { label: "【英語・大学受験】", q: "「foresee」の意味は？", choices: ["〜を監督する", "〜を見逃す", "〜を予見する"], answer: 2, explain: "No one could foresee the result.（誰もその結果を予見できなかった）。活用は foresee - foresaw - foreseen" },
  { label: "【英語・大学受験】", q: "「indispensable」の意味は？", choices: ["価値のない", "不可欠な", "分配できない"], answer: 1, explain: "Water is indispensable to life.（水は生命に不可欠だ）。be indispensable to 〜 の形で使う" },
  { label: "【英語・大学受験】", q: "「versatile」の意味は？", choices: ["詩的な", "偏った", "多才な、用途の広い"], answer: 2, explain: "She is a versatile actress.（彼女は多才な女優だ）" },
  { label: "【英語・大学受験】", q: "「subtle」の意味は？", choices: ["微妙な、かすかな", "地下の", "突然の"], answer: 0, explain: "There is a subtle difference between the two words.（2つの語の間には微妙な違いがある）。b は発音しない" },
  { label: "【英語・大学受験】", q: "「viable」の意味は？", choices: ["目に見える", "実行可能な、成り立つ", "活発な"], answer: 1, explain: "It is not a viable plan.（それは実行可能な計画ではない）" },
  { label: "【英語・大学受験】", q: "「thorough」の意味は？", choices: ["〜を通じて", "困難な", "徹底的な、完全な"], answer: 2, explain: "They made a thorough investigation.（彼らは徹底的な調査を行った）。through との混同に注意。発音は /ˈθʌrə/" },
  { label: "【英語・大学受験】", q: "「in the wake of 〜」の意味は？", choices: ["〜の後に続いて、〜の結果として", "〜の目覚めに", "〜を警戒して"], answer: 0, explain: "In the wake of the disaster, many people lost their homes.（その災害の結果、多くの人が家を失った）" },
  { label: "【英語・大学受験】", q: "「by virtue of 〜」の意味は？", choices: ["〜に反して", "〜のおかげで、〜によって", "〜の徳として"], answer: 1, explain: "He got the job by virtue of his experience.（彼は経験のおかげでその仕事を得た）" },
  { label: "【英語・大学受験】", q: "「at the mercy of 〜」の意味は？", choices: ["〜に慈悲を与えて", "〜に感謝して", "〜のなすがままで"], answer: 2, explain: "The boat was at the mercy of the waves.（そのボートは波のなすがままだった）" },
  { label: "【英語・大学受験】", q: "「for lack of 〜」の意味は？", choices: ["〜が不足しているために", "〜を欠いても", "〜の代わりに"], answer: 0, explain: "The plan failed for lack of funds.（その計画は資金不足で失敗した）" },
  { label: "【英語・大学受験】", q: "「to say the least」の意味は？", choices: ["最低でも", "せめて言えば", "控えめに言っても"], answer: 2, explain: "His behavior was strange, to say the least.（彼の態度は控えめに言っても奇妙だった）" },
  { label: "【英語・大学受験】", q: "「come to light」の意味は？", choices: ["明るくなる", "明るみに出る、発覚する", "軽くなる"], answer: 1, explain: "New facts came to light during the investigation.（調査の中で新たな事実が明るみに出た）" },
  { label: "【英語・大学受験】", q: "「set aside 〜」の意味は？", choices: ["〜を取っておく、脇に置く", "〜を設置する", "〜を離れて座る"], answer: 0, explain: "She set aside some money each month.（彼女は毎月いくらかのお金を取っておいた）。「（意見などを）脇に置く」の意味でも使う" },
  { label: "【英語・大学受験】", q: "「turn a blind eye to 〜」の意味は？", choices: ["〜に目を向ける", "〜を盲目にする", "〜を見て見ぬふりをする"], answer: 2, explain: "The teacher turned a blind eye to the rule-breaking.（先生はその規則違反を見て見ぬふりをした）" },
  { label: "【英語・大学受験】", q: "「on the grounds that 〜」の意味は？", choices: ["〜だけでなく", "〜という理由で", "〜の土地の上で"], answer: 1, explain: "He refused on the grounds that he was too busy.（彼は忙しすぎるという理由で断った）" },
  { label: "【英語・大学受験】", q: "「in proportion to 〜」の意味は？", choices: ["〜を割り当てて", "〜に反比例して", "〜に比例して"], answer: 2, explain: "Your pay increases in proportion to your experience.（給料は経験に比例して上がる）" },
  { label: "【英語・大学受験】", q: "「take issue with 〜」の意味は？", choices: ["〜に異議を唱える", "〜を問題にしない", "〜を発行する"], answer: 0, explain: "I take issue with his opinion.（私は彼の意見に異議がある）" },
  { label: "【英語・大学受験】", q: "「see eye to eye」の意味は？", choices: ["目を見て話す", "視力が合う", "意見が一致する"], answer: 2, explain: "We don't see eye to eye on this matter.（私たちはこの件で意見が合わない）" },
  { label: "【英語・大学受験】", q: "「get away with 〜」の意味は？", choices: ["〜から離れる", "〜をうまくやりおおせる、罰を免れる", "〜を持ち去る"], answer: 1, explain: "He cheated on the test and got away with it.（彼はテストでカンニングをして、とがめられずに済んだ）" },
  { label: "【英語・大学受験】", q: "「make do with 〜」の意味は？", choices: ["〜を作り直す", "〜をする必要がある", "〜でなんとか間に合わせる"], answer: 2, explain: "We had to make do with a small room.（私たちは小さな部屋でなんとか間に合わせなければならなかった）" },
  { label: "【英語・大学受験】", q: "「give way to 〜」の意味は？", choices: ["〜に道を譲る、〜に屈する", "〜から離れる", "〜に方法を教える"], answer: 0, explain: "Anger gave way to sadness.（怒りは悲しみに変わった）。Give way to traffic from the right.（右からの車に道を譲れ）" },
  { label: "【英語・大学受験】", q: "「call for 〜」の意味は？", choices: ["〜に電話する", "〜を要求する、必要とする", "〜を呼び寄せる"], answer: 1, explain: "The situation calls for immediate action.（その状況はただちに行動を求めている）" },
  { label: "【英語・大学受験】", q: "I wish he ( ) stop smoking. 空所に入る語は？", choices: ["would", "will", "did"], answer: 0, explain: "I wish ＋ 主語 ＋ would ＋ 原形 は、「〜してくれたらいいのに」という相手への不満や要望を表す" },
  { label: "【英語・大学受験】", q: "I would have gone to the party if I ( ) so busy. 空所に入る語（句）は？", choices: ["wasn't", "hadn't been", "weren't"], answer: 1, explain: "主節が would have ＋ 過去分詞 なので、if節は過去完了（had ＋ 過去分詞）にする" },
  { label: "【英語・大学受験】", q: "( ) I in your position, I would refuse. 空所に入る語は？", choices: ["Had", "Was", "Were"], answer: 2, explain: "If I were in your position の if を省略した倒置形。仮定法過去では be動詞は were を使う" },
  { label: "【英語・大学受験】", q: "There are times ( ) I feel lonely. 空所に入る語は？", choices: ["where", "when", "which"], answer: 1, explain: "先行詞が times（時）なので、関係副詞 when を使う。（さびしく感じるときがある）" },
  { label: "【英語・大学受験】", q: "( ) from the sky, the island looks like a heart. 空所に入る語は？", choices: ["Seeing", "Saw", "Seen"], answer: 2, explain: "分詞構文。島は「見られる」側なので過去分詞 Seen を使う。(When it is) seen from the sky の省略" },
  { label: "【英語・大学受験】", q: "With night ( ) on, we hurried home. 空所に入る語（句）は？", choices: ["come", "coming", "to come"], answer: 1, explain: "with ＋ O ＋ 現在分詞 は「Oが〜している状態で」。night は「近づいてくる」側なので現在分詞を使う" },
  { label: "【英語・大学受験】", q: "Under no circumstances ( ) you open this door. 空所に入る語（句）は？", choices: ["are", "should", "would be"], answer: 1, explain: "Under no circumstances などの否定の副詞句が文頭にくると倒置になる。「どんな場合も〜してはならない」" },
  { label: "【英語・大学受験】", q: "Rarely ( ) we see such a beautiful scene. 空所に入る語は？", choices: ["are", "have", "do"], answer: 2, explain: "Rarely（めったに〜ない）が文頭にくると倒置になる。一般動詞の現在形なので do ＋ 主語 ＋ 原形" },
  { label: "【英語・大学受験】", q: "Here ( ) the bus! 空所に入る語（句）は？", choices: ["does come", "comes", "is coming"], answer: 1, explain: "Here ＋ 動詞 ＋ 名詞 の倒置形。主語が名詞（the bus）のときの語順で、代名詞なら Here it comes! の語順になる" },
  { label: "【英語・大学受験】", q: "A whale is no more a fish than a horse is. この文の意味は？", choices: ["クジラは馬ほど魚ではない", "クジラが魚でないのは、馬が魚でないのと同じだ", "クジラは魚で、馬も魚だ"], answer: 1, explain: "A is no more B than C is D は「AがBでないのは、CがDでないのと同じだ」（くじら構文）。どちらも否定する" },
  { label: "【英語・大学受験】", q: "He is no better than a beggar. この文の意味は？", choices: ["彼は物乞いも同然だ", "彼は物乞いよりましだ", "彼は物乞いほど貧しくない"], answer: 0, explain: "no better than 〜 は「〜も同然だ」。not better than 〜 は「〜ほど優れていない」と区別する" },
  { label: "【英語・大学受験】", q: "I like him all the more ( ) he has faults. 空所に入る語は？", choices: ["although", "unless", "because"], answer: 2, explain: "all the more because 〜 は「〜だからなおさら」。理由を表す語句（because / for / as など）が続く" },
  { label: "【英語・大学受験】", q: "If you ( ) to succeed, you must work hard. 空所に入る語は？", choices: ["are", "will", "be"], answer: 0, explain: "be to 不定詞の「意図・目的」の用法。If you are to 〜 は「〜するつもりなら、〜したいなら」" },
  { label: "【英語・大学受験】", q: "I have difficulty ( ) English. 空所に入る語（句）は？", choices: ["to speak", "speaking", "speak"], answer: 1, explain: "have difficulty (in) ～ing は「〜するのに苦労する」。have trouble (in) ～ing も同じ意味" },
  { label: "【英語・大学受験】", q: "I feel like ( ) out tonight. 空所に入る語（句）は？", choices: ["to go", "go", "going"], answer: 2, explain: "feel like ～ing は「〜したい気がする」。like の後ろは前置詞なので動名詞になる" },
  { label: "【英語・大学受験】", q: "When it comes to ( ), he is the best. 空所に入る語（句）は？", choices: ["cook", "to cook", "cooking"], answer: 2, explain: "when it comes to ～ing は「〜のことになると」。この to は前置詞なので、後ろは動名詞" },
  { label: "【英語・大学受験】", q: "It is natural that he ( ) be angry. 空所に入る語は？", choices: ["should", "can", "must"], answer: 0, explain: "natural / strange / surprising などの判断を表す形容詞のあとの that 節では、should を使うことがある" },
  { label: "【英語・大学受験】", q: "What with work ( ) family, she is always busy. 空所に入る語は？", choices: ["but", "and", "or"], answer: 1, explain: "what with A and B は「AやらBやらで」。原因・理由を並べるときの慣用表現" },
  { label: "【英語・大学受験】", q: "It is not what you say ( ) how you say it that matters. 空所に入る語は？", choices: ["but", "and", "or"], answer: 0, explain: "not A but B（AではなくB）を強調構文の中で使った形。（大切なのは何を言うかではなく、どう言うかだ）" },
  { label: "【英語・大学受験】", q: "The ( ) lecture made everyone sleepy. 空所に入る語は？", choices: ["bored", "bore", "boring"], answer: 2, explain: "講義が「退屈な」ので現在分詞 boring。人が「退屈している」なら bored を使う" },
  { label: "【英語・大学受験】", q: "It is believed ( ) the universe began with a big bang. 空所に入る語は？", choices: ["what", "that", "which"], answer: 1, explain: "It is believed that 〜 は「〜と信じられている」。The universe is believed to have begun 〜 と書き換えられる" },
  { label: "【英語・大学受験】", q: "「the former ... the latter ～」の the latter の意味は？", choices: ["前者", "後者", "最近の"], answer: 1, explain: "Tom and Bob are brothers. The former is a doctor, and the latter is a teacher.（前者は医者で、後者は教師だ）" },
  { label: "【英語・大学受験】", q: "Scarcely had he sat down ( ) the phone rang. 空所に入る語は？", choices: ["than", "when", "then"], answer: 1, explain: "Scarcely ＋ had ＋ 主語 ＋ 過去分詞 ＋ when 〜 は「〜するやいなや…」。Hardly 〜 when … と同じ" },
  { label: "【英語・大学受験】", q: "He came all the way from Osaka, ( ) shows how serious he was. 空所に入る語は？", choices: ["what", "which", "that"], answer: 1, explain: "非制限用法の which は前の文全体を先行詞にできる。コンマのあとに that や what は使えない" },
  { label: "【英語・大学受験】", q: "She was kept ( ) for an hour. 空所に入る語（句）は？", choices: ["wait", "to wait", "waiting"], answer: 2, explain: "keep ＋ O ＋ ～ing は「Oを〜させておく」。受け身は be kept ～ing" },
  { label: "【英語・大学受験】", q: "Not a word ( ) he say. 空所に入る語は？", choices: ["did", "was", "had"], answer: 0, explain: "否定の意味の目的語が文頭に出ると倒置になる。（彼はひと言も言わなかった）" },
  { label: "【英語・大学受験】", q: "「be on the point of ～ing」の意味は？", choices: ["まさに〜しようとしている", "〜する点に立っている", "〜することを指摘する"], answer: 0, explain: "He was on the point of leaving.（彼はまさに出発するところだった）。be about to 〜 とほぼ同じ" },
  { label: "【英語・大学受験】", q: "I could not but ( ) him. 空所に入る語（句）は？", choices: ["admiring", "admire", "to admire"], answer: 1, explain: "cannot but ＋ 動詞の原形 は「〜せざるを得ない」。cannot help ～ing と同じ意味" },
  { label: "【英語・大学受験】", q: "並べ替え：「どんなに忙しくても、彼は毎日日記をつける」正しい文は？", choices: ["However busy he is, he keeps a diary every day.", "However he is busy, he keeps a diary every day.", "However busy is he, he keeps a diary every day."], answer: 0, explain: "However ＋ 形容詞 ＋ 主語 ＋ 動詞 で「どんなに〜でも」。形容詞が however のすぐあとにくる" },
  { label: "【英語・大学受験】", q: "並べ替え：「彼は自分が何を言っているのかわかっていないようだ」正しい文は？", choices: ["He doesn't seem to know what is he saying.", "He doesn't seem to know what he is saying.", "He doesn't seem knowing what he is saying."], answer: 1, explain: "間接疑問は〈疑問詞 ＋ 主語 ＋ 動詞〉の語順。seem の後ろは to 不定詞" },
  { label: "【英語・大学受験】", q: "並べ替え：「その知らせを聞いたとたん、彼は部屋を飛び出した」正しい文は？", choices: ["The moment heard he the news, he rushed out of the room.", "The moment he hears the news, he rushed out of the room.", "The moment he heard the news, he rushed out of the room."], answer: 2, explain: "the moment ＋ 主語 ＋ 動詞 は「〜するやいなや」。接続詞のように使うので、普通の語順になる" },
  { label: "【英語・大学受験】", q: "並べ替え：「この薬を飲めば、すぐに気分がよくなるでしょう」正しい文は？", choices: ["This medicine will make you feel better soon.", "This medicine will make you to feel better soon.", "This medicine will make you feeling better soon."], answer: 0, explain: "無生物主語の文。make ＋ O ＋ 原形 で「Oに〜させる」。to は不要" },
  { label: "【英語・大学受験】", q: "並べ替え：「彼女は夫が亡くなってから、ひとりで暮らしている」正しい文は？", choices: ["She lives alone since her husband died.", "She has lived alone since her husband died.", "She has lived alone since her husband has died."], answer: 1, explain: "since を使う文では、主節は現在完了、since 節は過去形にするのが基本" },
  { label: "【英語・大学受験】", q: "並べ替え：「私が最後に彼女に会ってから10年になる」正しい文は？", choices: ["It is ten years since I have last seen her.", "It is ten years when I last saw her.", "It is ten years since I last saw her."], answer: 2, explain: "It is ＋ 期間 ＋ since ＋ 主語 ＋ 過去形 で「〜してから…になる」" },
  { label: "【英語・大学受験】", q: "並べ替え：「問題は、彼が来るかどうかだ」正しい文は？", choices: ["The question is whether he will come.", "The question is that he will come or not.", "The question is if will he come."], answer: 0, explain: "名詞節をつくる whether は「〜かどうか」。be動詞のあとの補語として使える。if は補語にはならない" },
  { label: "【英語・大学受験】", q: "並べ替え：「私たちはその決定を延期せざるを得なかった」正しい文は？", choices: ["We could not but to put off the decision.", "We could not but put off the decision.", "We could not help put off the decision."], answer: 1, explain: "cannot but ＋ 原形 で「〜せざるを得ない」。but の後ろに to は不要" },
  { label: "【英語・大学受験】", q: "並べ替え：「時間さえあれば、このような問題は解決できる」正しい文は？", choices: ["Given time, problems like this can be solved.", "Giving time, problems like this can be solved.", "Gave time, problems like this can be solved."], answer: 0, explain: "Given ＋ 名詞 は「〜があれば、〜を考えると」。If they are given time の省略的な分詞構文" },
  { label: "【英語・大学受験】", q: "並べ替え：「彼はその仕事を引き受けたことを後悔している」正しい文は？", choices: ["He regrets to have accepted the job.", "He regrets having accepted the job.", "He regrets accepting having the job."], answer: 1, explain: "regret ～ing / having ＋ 過去分詞 で「〜したことを後悔する」。過去の出来事なので完了形の動名詞も使える" },
  { label: "【英語・大学受験】", q: "Mary, ( ) parents live in Paris, is studying art. 空所に入る語は？", choices: ["who", "whose", "which"], answer: 1, explain: "「メアリーの両親」と所有を表すので whose。非制限用法で、先行詞の Mary を補足説明している" },
  { label: "【英語・大学受験】", q: "I'd like this report ( ) by tomorrow. 空所に入る語は？", choices: ["finish", "finished", "finishing"], answer: 1, explain: "would like ＋ O ＋ 過去分詞 は「Oを〜してもらいたい」。報告書は「終えられる」側なので過去分詞" },
  { label: "【英語・大学受験】", q: "I never see this photo ( ) thinking of my mother. 空所に入る語は？", choices: ["without", "unless", "except"], answer: 0, explain: "never ... without ～ing は「〜すると必ず…する」（二重否定）。（この写真を見ると必ず母を思い出す）" },
  { label: "【英語・大学受験】", q: "He devoted himself ( ) the research. 空所に入る語は？", choices: ["for", "to", "in"], answer: 1, explain: "devote oneself to 〜 は「〜に身をささげる、没頭する」。to の後ろは名詞か動名詞" },
  { label: "【英語・大学受験】", q: "I'm not accustomed to ( ) in public. 空所に入る語（句）は？", choices: ["speak", "spoke", "speaking"], answer: 2, explain: "be accustomed to ～ing は「〜することに慣れている」。この to は前置詞なので動名詞になる" },
  { label: "【英語・大学受験】", q: "He got ( ) in the accident. 空所に入る語は？", choices: ["injure", "injuring", "injured"], answer: 2, explain: "get ＋ 過去分詞 は「〜される」という受け身的な意味を表す。He was injured と比べて動作の過程を強調する" },
  { label: "【英語・大学受験】", q: "The number of students ( ) increasing. 空所に入る語は？", choices: ["are", "is", "were"], answer: 1, explain: "the number of 〜 は「〜の数」で単数扱い。a number of 〜 は「多くの〜」で複数扱い" },
  { label: "【英語・大学受験】", q: "A number of students ( ) absent today. 空所に入る語は？", choices: ["was", "were", "is"], answer: 1, explain: "a number of 〜 は「多くの〜」の意味で複数扱いなので、動詞は were を使う" },

// ===== 英語（大学受験）101〜200問 =====
  { label: "【英語・大学受験】", q: "「〜を廃止する」を表す英単語は？", choices: ["absolve", "absorb", "abolish"], answer: 2, explain: "The country abolished the death penalty.（その国は死刑を廃止した）。名詞は abolition" },
  { label: "【英語・大学受験】", q: "「adhere」の意味は？", choices: ["〜を受け入れる", "固執する、くっつく", "〜を調整する"], answer: 1, explain: "adhere to 〜 で「〜を堅く守る」。They adhered to the rules.（彼らは規則を守った）。名詞は adherence" },
  { label: "【英語・大学受験】", q: "「alleged」の意味は？", choices: ["（真偽は不明だが）〜とされる、主張された", "寄付された", "同盟した"], answer: 0, explain: "the alleged criminal（容疑者とされる人）。動詞 allege は「〜と主張する」" },
  { label: "【英語・大学受験】", q: "「amend」の意味は？", choices: ["〜を終える", "〜を修正する、改正する", "〜を許す"], answer: 1, explain: "The law was amended last year.（その法律は昨年改正された）。名詞 amendment は「修正、改正」" },
  { label: "【英語・大学受験】", q: "「ample」の意味は？", choices: ["十分な、広々とした", "あいまいな", "熱心な"], answer: 0, explain: "We have ample time.（時間は十分ある）" },
  { label: "【英語・大学受験】", q: "「〜を引き起こす、かき立てる」を表す英単語は？", choices: ["arrange", "arouse", "arrest"], answer: 1, explain: "The speech aroused public interest.（その演説は世間の関心をかき立てた）" },
  { label: "【英語・大学受験】", q: "「assert」の意味は？", choices: ["〜を査定する", "〜を割り当てる", "〜を主張する、断言する"], answer: 2, explain: "He asserted his innocence.（彼は無実を主張した）。名詞は assertion" },
  { label: "【英語・大学受験】", q: "「avert」の意味は？", choices: ["〜を断言する", "〜を避ける、そらす", "〜を転換する"], answer: 1, explain: "They tried to avert a disaster.（彼らは惨事を防ごうとした）" },
  { label: "【英語・大学受験】", q: "「bolster」の意味は？", choices: ["〜を爆発させる", "〜を自慢する", "〜を強化する、支える"], answer: 2, explain: "The result bolstered his confidence.（その結果は彼の自信を高めた）" },
  { label: "【英語・大学受験】", q: "「candid」の意味は？", choices: ["率直な、正直な", "候補の", "ろうそくの"], answer: 0, explain: "Please give me your candid opinion.（率直な意見を聞かせてください）" },
  { label: "【英語・大学受験】", q: "「〜に無理に〜させる」を表す英単語は？", choices: ["compete", "compel", "compile"], answer: 1, explain: "He was compelled to resign.（彼は辞任せざるを得なかった）。compel A to 〜 の形で使う" },
  { label: "【英語・大学受験】", q: "「condemn」の意味は？", choices: ["〜を凝縮する", "〜を要約する", "〜を非難する、有罪と宣告する"], answer: 2, explain: "The leaders condemned the attack.（指導者たちはその攻撃を非難した）" },
  { label: "【英語・大学受験】", q: "「confine」の意味は？", choices: ["〜を確認する", "〜を制限する、閉じ込める", "〜を打ち明ける"], answer: 1, explain: "be confined to 〜 で「〜に限られる、〜に閉じ込められる」。The disease is confined to this area.（その病気はこの地域に限られている）" },
  { label: "【英語・大学受験】", q: "「目立つ、顕著な」を表す英単語は？", choices: ["continuous", "conscious", "conspicuous"], answer: 2, explain: "His absence was conspicuous.（彼の不在は目立った）" },
  { label: "【英語・大学受験】", q: "「contend」の意味は？", choices: ["〜を満足させる", "〜を伸ばす", "〜と主張する、競う"], answer: 2, explain: "He contends that the law is unfair.（彼はその法律は不公平だと主張している）" },
  { label: "【英語・大学受験】", q: "「cumulative」の意味は？", choices: ["文化的な", "累積的な", "好奇心の強い"], answer: 1, explain: "the cumulative effect of stress（ストレスの蓄積した影響）。動詞 accumulate は「〜をためる」" },
  { label: "【英語・大学受験】", q: "「〜を抑制する」を表す英単語は？", choices: ["curve", "cure", "curb"], answer: 2, explain: "The government tried to curb inflation.（政府はインフレを抑えようとした）" },
  { label: "【英語・大学受験】", q: "「〜に公然と逆らう、〜を無視する」を表す英単語は？", choices: ["define", "defy", "deny"], answer: 1, explain: "He defied the order.（彼は命令に逆らった）。名詞は defiance" },
  { label: "【英語・大学受験】", q: "「〜を描写する、描く」を表す英単語は？", choices: ["depict", "deport", "deprive"], answer: 0, explain: "The movie depicts life in the 1920s.（その映画は1920年代の生活を描いている）" },
  { label: "【英語・大学受験】", q: "「deter」の意味は？", choices: ["〜を悪化させる", "〜を思いとどまらせる", "〜を決定する"], answer: 1, explain: "deter A from ～ing で「Aが〜するのを思いとどまらせる」。The high price deterred me from buying it.（値段が高くて買う気をなくした）" },
  { label: "【英語・大学受験】", q: "「devise」の意味は？", choices: ["〜を考案する", "〜を分割する", "〜を告白する"], answer: 0, explain: "They devised a new method.（彼らは新しい方法を考案した）。divide（分ける）と区別する" },
  { label: "【英語・大学受験】", q: "「勤勉な」を表す英単語は？", choices: ["diligent", "delicate", "dominant"], answer: 0, explain: "She is a diligent student.（彼女は勤勉な生徒だ）。名詞は diligence" },
  { label: "【英語・大学受験】", q: "「〜を見分ける、識別する」を表す英単語は？", choices: ["discard", "disturb", "discern"], answer: 2, explain: "It is hard to discern the truth.（真実を見分けるのは難しい）" },
  { label: "【英語・大学受験】", q: "「dismiss」の意味は？", choices: ["〜を消費する", "〜を解雇する、〜を退ける", "〜を分配する"], answer: 1, explain: "He was dismissed from his job.（彼は職を解かれた）。Class dismissed.（授業は終わり）" },
  { label: "【英語・大学受験】", q: "「dispute」の意味は？", choices: ["論争（する）、〜に異議を唱える", "〜を処分する", "〜を散らす"], answer: 0, explain: "There is a dispute over the land.（その土地をめぐって争いがある）" },
  { label: "【英語・大学受験】", q: "「elusive」の意味は？", choices: ["とらえどころのない、つかまえにくい", "優雅な", "熟練の"], answer: 0, explain: "The answer remains elusive.（その答えはいまだにつかみどころがない）。動詞 elude は「〜をうまく逃れる」" },
  { label: "【英語・大学受験】", q: "「努力（する）」を表す英単語は？", choices: ["endure", "enforce", "endeavor"], answer: 2, explain: "We made every endeavor to finish on time.（私たちは時間内に終えるようあらゆる努力をした）。try の名詞・動詞のかたい言い方" },
  { label: "【英語・大学受験】", q: "「entail」の意味は？", choices: ["〜を伴う、必然的に含む", "〜を入場させる", "〜を楽しませる"], answer: 0, explain: "The job entails a lot of travel.（その仕事にはたくさんの出張が伴う）" },
  { label: "【英語・大学受験】", q: "「〜を侵食する、むしばむ」を表す英単語は？", choices: ["erase", "erode", "erupt"], answer: 1, explain: "The river eroded the bank.（川が土手を侵食した）。名詞は erosion" },
  { label: "【英語・大学受験】", q: "「（感情・記憶などを）呼び起こす」を表す英単語は？", choices: ["evolve", "evoke", "invoke"], answer: 1, explain: "The song evoked memories of childhood.（その歌は子どものころの記憶を呼び起こした）" },
  { label: "【英語・大学受験】", q: "「exempt」の意味は？", choices: ["〜を抜粋する", "免除された、〜を免除する", "排他的な"], answer: 1, explain: "Food is exempt from the tax.（食品は税が免除されている）。be exempt from 〜 の形で使う" },
  { label: "【英語・大学受験】", q: "「flaw」の意味は？", choices: ["炎", "床", "欠陥、欠点"], answer: 2, explain: "There is a flaw in your plan.（あなたの計画には欠陥がある）。形容詞は flawed、flawless は「欠点のない」" },
  { label: "【英語・大学受験】", q: "「倹約的な、質素な」を表す英単語は？", choices: ["frugal", "fragile", "fruitful"], answer: 0, explain: "He leads a frugal life.（彼は質素な生活を送っている）" },
  { label: "【英語・大学受験】", q: "「harsh」の意味は？", choices: ["有害な", "迅速な", "厳しい、過酷な"], answer: 2, explain: "The animals survived the harsh winter.（動物たちは厳しい冬を生き延びた）" },
  { label: "【英語・大学受験】", q: "「immune」の意味は？", choices: ["即座の", "免疫のある、〜の影響を受けない", "無罪の"], answer: 1, explain: "He is immune to the disease.（彼はその病気に免疫がある）。名詞は immunity" },
  { label: "【英語・大学受験】", q: "「〜を損なう、悪くする」を表す英単語は？", choices: ["impart", "impair", "impose"], answer: 1, explain: "Noise can impair your concentration.（騒音は集中力を損なうことがある）" },
  { label: "【英語・大学受験】", q: "「induce」の意味は？", choices: ["〜を阻止する", "〜を押す", "〜を引き起こす、説得して〜させる"], answer: 2, explain: "The medicine induces sleep.（その薬は眠気を引き起こす）。induce A to 〜 で「Aを説得して〜させる」" },
  { label: "【英語・大学受験】", q: "「infer」の意味は？", choices: ["〜を感染させる", "〜を推論する、推測する", "〜を提案する"], answer: 1, explain: "We can infer his feelings from his words.（彼の言葉から気持ちを推測できる）。名詞は inference" },
  { label: "【英語・大学受験】", q: "「独創的な、巧妙な」を表す英単語は？", choices: ["ingredient", "ingenious", "innocent"], answer: 1, explain: "It was an ingenious idea.（それは巧妙な考えだった）。名詞は ingenuity" },
  { label: "【英語・大学受験】", q: "「intricate」の意味は？", choices: ["内的な", "危険な", "複雑な、入り組んだ"], answer: 2, explain: "an intricate pattern（複雑な模様）" },
  { label: "【英語・大学受験】", q: "「lenient」の意味は？", choices: ["怠惰な", "冷たい", "寛大な、甘い"], answer: 2, explain: "The judge was lenient with him.（裁判官は彼に寛大だった）" },
  { label: "【英語・大学受験】", q: "「liable」の意味は？", choices: ["解放された", "（〜する）責任がある、〜しがちだ", "信頼できる"], answer: 1, explain: "be liable for 〜 で「〜に責任がある」。be liable to 〜 で「〜しがちだ」" },
  { label: "【英語・大学受験】", q: "「〜をおびき寄せる、誘惑（する）」を表す英単語は？", choices: ["lure", "lore", "lurk"], answer: 0, explain: "The bait lured the fish.（そのえさが魚をおびき寄せた）" },
  { label: "【英語・大学受験】", q: "「meager」の意味は？", choices: ["乏しい、わずかな", "温和な", "健康な"], answer: 0, explain: "He lives on a meager income.（彼はわずかな収入で暮らしている）" },
  { label: "【英語・大学受験】", q: "「migrate」の意味は？", choices: ["〜を混ぜる", "移住する、（動物が）移動する", "〜を軽減する"], answer: 1, explain: "Birds migrate to warmer places in winter.（鳥は冬に暖かい場所へ移動する）。名詞は migration" },
  { label: "【英語・大学受験】", q: "「momentum」の意味は？", choices: ["勢い、はずみ", "瞬間", "記念品"], answer: 0, explain: "The team gained momentum.（そのチームは勢いに乗った）" },
  { label: "【英語・大学受験】", q: "「〜を育てる、養う」を表す英単語は？", choices: ["natural", "nurture", "nutrition"], answer: 1, explain: "Parents nurture their children.（親は子どもを育てる）。nature（自然）と nurture（養育）は対で使うことが多い" },
  { label: "【英語・大学受験】", q: "「〜を省略する、省く」を表す英単語は？", choices: ["admit", "omit", "emit"], answer: 1, explain: "Don't omit any details.（詳細を省かないでください）。名詞は omission" },
  { label: "【英語・大学受験】", q: "「oppress」の意味は？", choices: ["〜を抑圧する、虐げる", "〜に反対する", "〜を押す"], answer: 0, explain: "The people were oppressed by the dictator.（人々は独裁者に抑圧された）" },
  { label: "【英語・大学受験】", q: "「perpetual」の意味は？", choices: ["永続的な、絶え間ない", "個人的な", "慎重な"], answer: 0, explain: "They lived in perpetual fear.（彼らは絶え間ない恐怖の中で暮らしていた）" },
  { label: "【英語・大学受験】", q: "「pervasive」の意味は？", choices: ["説得力のある", "広く行き渡った、浸透する", "受動的な"], answer: 1, explain: "Social media is pervasive in our lives.（SNSは私たちの生活に浸透している）。動詞は pervade" },
  { label: "【英語・大学受験】", q: "「plight」の意味は？", choices: ["飛行", "苦境、窮状", "陰謀"], answer: 1, explain: "They were moved by the plight of the refugees.（彼らは難民の窮状に心を動かされた）" },
  { label: "【英語・大学受験】", q: "「prestige」の意味は？", choices: ["圧力", "名声、威信", "特権"], answer: 1, explain: "The university has great prestige.（その大学は高い名声がある）" },
  { label: "【英語・大学受験】", q: "「〜を長引かせる、延長する」を表す英単語は？", choices: ["profit", "propel", "prolong"], answer: 2, explain: "They tried to prolong his life.（彼らは彼の命を延ばそうとした）" },
  { label: "【英語・大学受験】", q: "「provoke」の意味は？", choices: ["〜を挑発する、引き起こす", "〜を提供する", "〜を証明する"], answer: 0, explain: "His remarks provoked anger.（彼の発言は怒りを引き起こした）。名詞は provocation" },
  { label: "【英語・大学受験】", q: "「慎重な、賢明な」を表す英単語は？", choices: ["prudent", "pregnant", "present"], answer: 0, explain: "It is prudent to save money.（お金をためておくのは賢明だ）" },
  { label: "【英語・大学受験】", q: "「refrain」の意味は？", choices: ["〜を繰り返す", "〜を修復する", "控える、差し控える"], answer: 2, explain: "Please refrain from smoking.（喫煙はお控えください）。refrain from ～ing の形で使う" },
  { label: "【英語・大学受験】", q: "「relinquish」の意味は？", choices: ["〜を手放す、放棄する", "〜を解放する", "〜を信頼する"], answer: 0, explain: "He relinquished his right to the land.（彼はその土地への権利を放棄した）" },
  { label: "【英語・大学受験】", q: "「renowned」の意味は？", choices: ["有名な、名高い", "更新された", "辞任した"], answer: 0, explain: "She is a renowned scientist.（彼女は著名な科学者だ）。be renowned for 〜 で「〜で有名だ」" },
  { label: "【英語・大学受験】", q: "「resilient」の意味は？", choices: ["居住の", "抵抗する", "立ち直りが早い、弾力性のある"], answer: 2, explain: "Children are often more resilient than adults.（子どもは大人より立ち直りが早いことが多い）。名詞は resilience" },
  { label: "【英語・大学受験】", q: "「〜を犠牲にして」を表す英語表現は？", choices: ["on the basis of", "in terms of", "at the expense of"], answer: 2, explain: "He succeeded at the expense of his health.（彼は健康を犠牲にして成功した）" },
  { label: "【英語・大学受験】", q: "「in the course of 〜」の意味は？", choices: ["〜の方向に", "〜を除いて", "〜の間に、〜の過程で"], answer: 2, explain: "In the course of the conversation, he mentioned his plan.（会話の中で、彼は計画に触れた）" },
  { label: "【英語・大学受験】", q: "「on the brink of 〜」の意味は？", choices: ["〜の寸前で", "〜の端から離れて", "〜の次に"], answer: 0, explain: "The company is on the brink of bankruptcy.（その会社は倒産寸前だ）" },
  { label: "【英語・大学受験】", q: "「概して」を表す英語表現は？", choices: ["by and by", "by and large", "by far"], answer: 1, explain: "By and large, the plan was a success.（概して、その計画は成功だった）" },
  { label: "【英語・大学受験】", q: "「to a great extent」の意味は？", choices: ["かなりの程度まで", "とても遠くまで", "長い期間にわたって"], answer: 0, explain: "His success is due to a great extent to luck.（彼の成功はかなりの部分、運による）" },
  { label: "【英語・大学受験】", q: "「for the most part」の意味は？", choices: ["たいてい、大部分は", "最初のうちは", "部分的に"], answer: 0, explain: "For the most part, the students were satisfied.（大部分の生徒は満足していた）" },
  { label: "【英語・大学受験】", q: "「in a nutshell」の意味は？", choices: ["こっそりと", "実際には", "一言で言えば、要するに"], answer: 2, explain: "In a nutshell, we need more time.（要するに、もっと時間が必要だ）" },
  { label: "【英語・大学受験】", q: "「ときどき」を表す英語表現は？", choices: ["from time to time", "from now on", "from place to place"], answer: 0, explain: "We meet from time to time.（私たちはときどき会う）。now and then / once in a while とほぼ同じ" },
  { label: "【英語・大学受験】", q: "「むだに、むなしく」を表す英語表現は？", choices: ["in turn", "in need", "in vain"], answer: 2, explain: "He tried in vain to open the door.（彼はドアを開けようとしたが、むだだった）" },
  { label: "【英語・大学受験】", q: "「to no avail」の意味は？", choices: ["いつでも利用できて", "ためらわずに", "むだに、効果なく"], answer: 2, explain: "She searched everywhere, but to no avail.（彼女はあらゆる所を探したが、むだだった）" },
  { label: "【英語・大学受験】", q: "「under way」の意味は？", choices: ["道に迷って", "進行中で", "道を譲って"], answer: 1, explain: "The project is already under way.（そのプロジェクトはすでに進行中だ）" },
  { label: "【英語・大学受験】", q: "「in effect」の意味は？", choices: ["効果的に", "影響を受けて", "事実上、実質的に"], answer: 2, explain: "The two companies are, in effect, one.（その2社は事実上ひとつだ）。「（法律などが）有効で」の意味でも使う" },
  { label: "【英語・大学受験】", q: "「何よりも、とりわけ」を表す英語表現は？", choices: ["after all", "above all", "at all"], answer: 1, explain: "Above all, stay healthy.（何よりも、健康でいなさい）" },
  { label: "【英語・大学受験】", q: "「carry on」の意味は？", choices: ["続ける", "〜を運び出す", "〜を持ち込む"], answer: 0, explain: "Carry on with your work.（仕事を続けなさい）。carry on ～ing の形でも使う" },
  { label: "【英語・大学受験】", q: "「come about」の意味は？", choices: ["〜に近づく", "〜を横切る", "起こる、生じる"], answer: 2, explain: "How did the accident come about?（その事故はどのようにして起こったのですか）" },
  { label: "【英語・大学受験】", q: "「dispose of 〜」の意味は？", choices: ["〜を処分する", "〜を準備する", "〜を提案する"], answer: 0, explain: "Please dispose of the trash properly.（ごみは適切に処分してください）" },
  { label: "【英語・大学受験】", q: "「〜を廃止する、なくす」を表す英語表現は？", choices: ["get away with", "do away with", "put up with"], answer: 1, explain: "The school did away with the old rule.（その学校は古い規則を廃止した）" },
  { label: "【英語・大学受験】", q: "「draw up 〜」の意味は？", choices: ["〜を引き上げる", "〜に近づく", "〜を作成する（計画・書類）"], answer: 2, explain: "They drew up a contract.（彼らは契約書を作成した）" },
  { label: "【英語・大学受験】", q: "「fall back on 〜」の意味は？", choices: ["〜に頼る、〜を当てにする", "〜に落ちて戻る", "〜を後回しにする"], answer: 0, explain: "I have some savings to fall back on.（頼れる貯金がいくらかある）" },
  { label: "【英語・大学受験】", q: "「follow up」の意味は？", choices: ["（あとで）さらに調べる、追跡する", "〜のあとについて行く", "〜を上へ追う"], answer: 0, explain: "I'll follow up on the matter tomorrow.（その件は明日さらに確認する）。名詞は follow-up（追跡調査）" },
  { label: "【英語・大学受験】", q: "「〜に賛成する、〜に従う」を表す英語表現は？", choices: ["go along with", "go against", "go through"], answer: 0, explain: "I can't go along with his idea.（彼の考えには賛成できない）" },
  { label: "【英語・大学受験】", q: "「hold true」の意味は？", choices: ["真実を握る", "正直でいる", "当てはまる、有効である"], answer: 2, explain: "This rule holds true for everyone.（この規則はすべての人に当てはまる）" },
  { label: "【英語・大学受験】", q: "「keep pace with 〜」の意味は？", choices: ["〜を守る", "〜に遅れずについていく", "〜の速度を落とす"], answer: 1, explain: "Wages have not kept pace with prices.（賃金は物価に遅れずについていけていない）" },
  { label: "【英語・大学受験】", q: "「〜を見下す」を表す英語表現は？", choices: ["look down on", "look up to", "look into"], answer: 0, explain: "Don't look down on others.（他人を見下してはいけない）。look up to 〜 は「〜を尊敬する」" },
  { label: "【英語・大学受験】", q: "「put forward 〜」の意味は？", choices: ["〜を提案する、提出する", "〜を前進させる", "〜を延期する"], answer: 0, explain: "She put forward a new idea.（彼女は新しい案を出した）" },
  { label: "【英語・大学受験】", q: "( ) as it may seem, he is a millionaire. 空所に入る語（句）は？", choices: ["Strangely", "Strangeness", "Strange"], answer: 2, explain: "〈形容詞 ＋ as ＋ 主語 ＋ may ＋ 動詞〉は譲歩で「〜かもしれないが」。Strange as it may seem は「不思議に思えるかもしれないが」" },
  { label: "【英語・大学受験】", q: "There is no ( ) the fact that he is guilty. 空所に入る語（句）は？", choices: ["deny", "denying", "denied"], answer: 1, explain: "There is no ～ing は「〜することはできない」。There is no denying 〜 は「〜は否定できない」" },
  { label: "【英語・大学受験】", q: "I cannot thank you ( ). 空所に入る語（句）は？", choices: ["much", "well", "enough"], answer: 2, explain: "cannot ... enough は「いくら〜してもしすぎることはない」。（感謝してもしきれない）" },
  { label: "【英語・大学受験】", q: "I would sooner ( ) than betray my friends. 空所に入る語（句）は？", choices: ["to die", "dying", "die"], answer: 2, explain: "would sooner A than B は「BするくらいならAするほうがましだ」。would rather A than B と同じ形で、AもBも動詞の原形" },
  { label: "【英語・大学受験】", q: "The sooner you start, the ( ) it will be. 空所に入る語（句）は？", choices: ["best", "good", "better"], answer: 2, explain: "the ＋ 比較級, the ＋ 比較級 で「〜すればするほど…」。good の比較級は better" },
  { label: "【英語・大学受験】", q: "「granted that 〜」の意味は？", choices: ["〜を与えたので", "〜を許可して", "〜だとしても、〜を認めるとしても"], answer: 2, explain: "Granted that he is young, he is still responsible.（彼が若いことを認めるとしても、責任はある）" },
  { label: "【英語・大学受験】", q: "「in so far as 〜」の意味は？", choices: ["〜と同じ遠さで", "〜する限りにおいて", "〜のためにだけ"], answer: 1, explain: "I will help you in so far as I can.（できる限り手伝う）。as far as 〜 / so far as 〜 も同じ意味" },
  { label: "【英語・大学受験】", q: "The more he talked, ( ) I understood. 空所に入る語（句）は？", choices: ["the fewer", "the least", "the less"], answer: 2, explain: "the more 〜, the less … は「〜すればするほど…でなくなる」。（彼が話せば話すほど、私は理解できなくなった）" },
  { label: "【英語・大学受験】", q: "The man ( ) I thought was honest cheated me. 空所に入る語（句）は？", choices: ["who", "whom", "which"], answer: 0, explain: "I thought が挿入されているだけで、後ろの was の主語になるので主格 who を使う。（正直だと思っていた男にだまされた）" },
  { label: "【英語・大学受験】", q: "This is the topic ( ) I'm most interested. 空所に入る語（句）は？", choices: ["in which", "which", "of which"], answer: 0, explain: "be interested in 〜 の in が関係代名詞の前に出た形。〈前置詞 ＋ which〉の語順" },
  { label: "【英語・大学受験】", q: "He is a friend of ( ). 空所に入る語（句）は？", choices: ["mine", "my", "me"], answer: 0, explain: "a friend of mine は「私の友人（のひとり）」。〈a / this / that ＋ 名詞 ＋ of ＋ 所有代名詞〉の形" },
  { label: "【英語・大学受験】", q: "Is there anything ( ) I can do for you? 空所に入る語（句）は？", choices: ["what", "which", "that"], answer: 2, explain: "先行詞が anything のときは、関係代名詞 that を使うのが基本" },
  { label: "【英語・大学受験】", q: "He is too wise ( ) be deceived easily. 空所に入る語（句）は？", choices: ["for", "to", "enough to"], answer: 1, explain: "too 〜 to … は「〜すぎて…できない」。（彼は賢いので、簡単にはだまされない）" },
  { label: "【英語・大学受験】", q: "Only when you try ( ) you know your ability. 空所に入る語（句）は？", choices: ["will", "do", "are"], answer: 0, explain: "Only when 〜 が文頭にくると、主節が倒置になる。〈will ＋ 主語 ＋ 動詞〉の語順" },
  { label: "【英語・大学受験】", q: "「That being the case, we should cancel.」の That being the case の意味は？", choices: ["それが本当でなければ", "そういう事情なので", "その件にもかかわらず"], answer: 1, explain: "独立分詞構文。As that is the case と同じで、理由を表す。（そういう事情なので、中止すべきだ）" },

// ===== 英語（大学受験）201〜300問 =====
  { label: "【英語・大学受験】", q: "「revenue」の意味は？", choices: ["収入、歳入", "復讐", "革命"], answer: 0, explain: "The company's revenue increased last year.（その会社の収入は昨年増えた）" },
  { label: "【英語・大学受験】", q: "「rigorous」の意味は？", choices: ["活発な", "厳密な、厳格な", "堅い"], answer: 1, explain: "a rigorous test（厳密な試験）。名詞は rigor" },
  { label: "【英語・大学受験】", q: "「sanction」の意味は？", choices: ["聖域", "制裁、承認", "遺産"], answer: 1, explain: "The UN imposed sanctions on the country.（国連はその国に制裁を科した）。「承認する」の意味でも使う" },
  { label: "【英語・大学受験】", q: "「shrewd」の意味は？", choices: ["おとなしい", "抜け目のない、賢明な", "無愛想な"], answer: 1, explain: "He is a shrewd businessman.（彼は抜け目のない実業家だ）" },
  { label: "【英語・大学受験】", q: "「sluggish」の意味は？", choices: ["きらびやかな", "滑りやすい", "不振の、のろい"], answer: 2, explain: "The economy is sluggish.（景気は低迷している）" },
  { label: "【英語・大学受験】", q: "「stagnant」の意味は？", choices: ["静かな", "まっすぐな", "停滞した、よどんだ"], answer: 2, explain: "The economy has been stagnant for years.（経済は何年も停滞している）。動詞は stagnate" },
  { label: "【英語・大学受験】", q: "「努力する、励む」を表す英単語は？", choices: ["strike", "stride", "strive"], answer: 2, explain: "He strives to improve his skills.（彼は技術を高めようと努力している）。strive for 〜 / strive to 〜 の形で使う" },
  { label: "【英語・大学受験】", q: "「subside」の意味は？", choices: ["〜を補助する", "〜を代理する", "おさまる、静まる"], answer: 2, explain: "The storm subsided by morning.（嵐は朝までにおさまった）" },
  { label: "【英語・大学受験】", q: "「〜を上回る、〜にまさる」を表す英単語は？", choices: ["surpass", "surprise", "surround"], answer: 0, explain: "The result surpassed our expectations.（結果は私たちの期待を上回った）" },
  { label: "【英語・大学受験】", q: "「susceptible」の意味は？", choices: ["影響を受けやすい、感染しやすい", "受け入れ可能な", "疑わしい"], answer: 0, explain: "Children are susceptible to colds.（子どもは風邪にかかりやすい）。be susceptible to 〜 の形で使う" },
  { label: "【英語・大学受験】", q: "「tedious」の意味は？", choices: ["一時的な", "退屈な、あきあきする", "賃貸の"], answer: 1, explain: "The work was long and tedious.（その仕事は長くて退屈だった）" },
  { label: "【英語・大学受験】", q: "「〜を誘惑する、そそのかす」を表す英単語は？", choices: ["tame", "tempt", "tempo"], answer: 1, explain: "The smell of the cake tempted me.（ケーキのにおいに誘惑された）。名詞は temptation" },
  { label: "【英語・大学受験】", q: "「〜を終わらせる、終了する」を表す英単語は？", choices: ["determine", "terrify", "terminate"], answer: 2, explain: "The company terminated his contract.（会社は彼の契約を打ち切った）。名詞は termination" },
  { label: "【英語・大学受験】", q: "「thwart」の意味は？", choices: ["〜を投げる", "〜を曲げる", "〜を阻止する、くじく"], answer: 2, explain: "The police thwarted the plan.（警察はその計画を阻止した）" },
  { label: "【英語・大学受験】", q: "「〜を許容する、我慢する」を表す英単語は？", choices: ["tolerate", "tolerant", "translate"], answer: 0, explain: "I can't tolerate such rudeness.（そんな無礼は我慢できない）。名詞は tolerance、形容詞は tolerant" },
  { label: "【英語・大学受験】", q: "「tranquil」の意味は？", choices: ["穏やかな、静かな", "奇妙な", "堅い"], answer: 0, explain: "a tranquil lake（穏やかな湖）。名詞は tranquility" },
  { label: "【英語・大学受験】", q: "「transient」の意味は？", choices: ["一時的な、はかない", "透明な", "移行の"], answer: 0, explain: "Fame is transient.（名声ははかないものだ）" },
  { label: "【英語・大学受験】", q: "「tremendous」の意味は？", choices: ["震える", "ものすごい、莫大な", "トンネルの"], answer: 1, explain: "He made a tremendous effort.（彼は途方もない努力をした）" },
  { label: "【英語・大学受験】", q: "「混乱、騒動」を表す英単語は？", choices: ["turnover", "turmoil", "tournament"], answer: 1, explain: "The country was in turmoil after the election.（選挙後、その国は混乱していた）" },
  { label: "【英語・大学受験】", q: "「ubiquitous」の意味は？", choices: ["独特の", "どこにでもある、遍在する", "一様な"], answer: 1, explain: "Smartphones are now ubiquitous.（スマートフォンは今やどこにでもある）" },
  { label: "【英語・大学受験】", q: "「全員一致の」を表す英単語は？", choices: ["unanimous", "anonymous", "unique"], answer: 0, explain: "The decision was unanimous.（その決定は全員一致だった）。anonymous は「匿名の」" },
  { label: "【英語・大学受験】", q: "「〜を支持する、維持する」を表す英単語は？", choices: ["upload", "uphold", "upgrade"], answer: 1, explain: "The court upheld the decision.（裁判所はその判決を支持した）。活用は uphold - upheld - upheld" },
  { label: "【英語・大学受験】", q: "「消える、見えなくなる」を表す英単語は？", choices: ["vacant", "varnish", "vanish"], answer: 2, explain: "The magician vanished into thin air.（その手品師は跡形もなく消えた）" },
  { label: "【英語・大学受験】", q: "「verdict」の意味は？", choices: ["評決、判断", "動詞", "美徳"], answer: 0, explain: "The jury reached a verdict.（陪審員は評決に達した）" },
  { label: "【英語・大学受験】", q: "「不安定な、揮発性の」を表す英単語は？", choices: ["volatile", "voluntary", "violent"], answer: 0, explain: "The oil market is volatile.（石油市場は不安定だ）" },
  { label: "【英語・大学受験】", q: "「warrant」の意味は？", choices: ["〜を正当化する、保証する", "〜を警告する", "〜に与える"], answer: 0, explain: "The situation warrants immediate action.（その状況はただちに行動を起こす必要がある）。名詞では「令状」" },
  { label: "【英語・大学受験】", q: "「pledge」の意味は？", choices: ["人質", "賛美", "誓い、約束（する）"], answer: 2, explain: "He made a pledge to help the poor.（彼は貧しい人々を助けると誓った）" },
  { label: "【英語・大学受験】", q: "「ambivalent」の意味は？", choices: ["相反する感情をもつ、どっちつかずの", "野心的な", "両手利きの"], answer: 0, explain: "I feel ambivalent about moving.（引っ越しには複雑な気持ちだ）。名詞は ambivalence" },
  { label: "【英語・大学受験】", q: "「anecdote」の意味は？", choices: ["解毒剤", "逸話、エピソード", "年代記"], answer: 1, explain: "He told an amusing anecdote.（彼はおもしろい逸話を話した）。antidote は「解毒剤」" },
  { label: "【英語・大学受験】", q: "「〜をなだめる、〜に譲歩する」を表す英単語は？", choices: ["appraise", "appeal", "appease"], answer: 2, explain: "They tried to appease the angry crowd.（彼らは怒った群衆をなだめようとした）" },
  { label: "【英語・大学受験】", q: "「arduous」の意味は？", choices: ["熱心な", "骨の折れる、困難な", "古風な"], answer: 1, explain: "an arduous journey（骨の折れる旅）" },
  { label: "【英語・大学受験】", q: "「articulate」の意味は？", choices: ["はっきり表現する、明確な", "〜を人工的にする", "〜を主張する"], answer: 0, explain: "She is an articulate speaker.（彼女は話し方が明確だ）。動詞では「はっきり述べる」" },
  { label: "【英語・大学受験】", q: "「ascertain」の意味は？", choices: ["〜を上昇する", "〜を確かめる、突き止める", "〜を調整する"], answer: 1, explain: "We must ascertain the facts.（私たちは事実を確かめなければならない）" },
  { label: "【英語・大学受験】", q: "「astute」の意味は？", choices: ["洞察力のある、機敏な", "見知らぬ", "天文の"], answer: 0, explain: "an astute observer（洞察力のある観察者）" },
  { label: "【英語・大学受験】", q: "「avid」の意味は？", choices: ["熱心な、貪欲な", "避けられない", "危険な"], answer: 0, explain: "He is an avid reader.（彼は熱心な読書家だ）" },
  { label: "【英語・大学受験】", q: "「暗い、荒涼とした」を表す英単語は？", choices: ["bleach", "bleak", "blank"], answer: 1, explain: "The future looks bleak.（将来は暗く見える）" },
  { label: "【英語・大学受験】", q: "「cherish」の意味は？", choices: ["〜を選ぶ", "〜に乾杯する", "〜を大切にする、心に抱く"], answer: 2, explain: "I cherish the memories of my school days.（学生時代の思い出を大切にしている）" },
  { label: "【英語・大学受験】", q: "「〜を強制する」を表す英単語は？", choices: ["coincide", "coerce", "coexist"], answer: 1, explain: "He was coerced into signing the paper.（彼は書類に無理に署名させられた）。名詞は coercion" },
  { label: "【英語・大学受験】", q: "「簡潔な」を表す英単語は？", choices: ["conscious", "concise", "concrete"], answer: 1, explain: "Please keep your answer concise.（答えは簡潔にしてください）" },
  { label: "【英語・大学受験】", q: "「conducive」の意味は？", choices: ["指揮者の", "結論の", "助けとなる、寄与する"], answer: 2, explain: "A quiet room is conducive to study.（静かな部屋は勉強に役立つ）。be conducive to 〜 の形で使う" },
  { label: "【英語・大学受験】", q: "「converge」の意味は？", choices: ["〜を伝える", "集まる、収束する", "〜と会話する"], answer: 1, explain: "The roads converge at the station.（道路は駅で合流する）。反対は diverge" },
  { label: "【英語・大学受験】", q: "「cunning」の意味は？", choices: ["勇敢な", "好奇心の強い", "ずる賢い"], answer: 2, explain: "The fox is a cunning animal.（キツネはずる賢い動物だ）" },
  { label: "【英語・大学受験】", q: "「〜を使い果たす、減らす」を表す英単語は？", choices: ["deplete", "deploy", "deprive"], answer: 0, explain: "The long journey depleted our supplies.（長い旅で、私たちの物資は底をついた）。名詞は depletion" },
  { label: "【英語・大学受験】", q: "「detrimental」の意味は？", choices: ["決定的な", "有害な", "従属の"], answer: 1, explain: "Smoking is detrimental to health.（喫煙は健康に有害だ）。be detrimental to 〜 の形で使う" },
  { label: "【英語・大学受験】", q: "「dire」の意味は？", choices: ["直接の", "親愛な", "ひどい、差し迫った"], answer: 2, explain: "They are in dire need of help.（彼らは切実に助けを必要としている）" },
  { label: "【英語・大学受験】", q: "「discreet」の意味は？", choices: ["別個の", "離れた", "慎重な、思慮深い"], answer: 2, explain: "Please be discreet about this matter.（この件は慎重にお願いします）。discrete は「別個の」" },
  { label: "【英語・大学受験】", q: "「だんだん減る、縮小する」を表す英単語は？", choices: ["dwindle", "dwell", "swindle"], answer: 0, explain: "The population of the village is dwindling.（その村の人口は減りつつある）" },
  { label: "【英語・大学受験】", q: "「雄弁な」を表す英単語は？", choices: ["eloquent", "elegant", "elaborate"], answer: 0, explain: "He gave an eloquent speech.（彼は雄弁なスピーチをした）" },
  { label: "【英語・大学受験】", q: "「emulate」の意味は？", choices: ["〜を放出する", "〜を見習う、〜と張り合う", "〜をはっきりさせる"], answer: 1, explain: "Children often emulate their parents.（子どもはよく親をまねる）" },
  { label: "【英語・大学受験】", q: "「（法律を）制定する」を表す英単語は？", choices: ["enact", "exact", "react"], answer: 0, explain: "The government enacted a new law.（政府は新しい法律を制定した）。名詞は enactment" },
  { label: "【英語・大学受験】", q: "「erratic」の意味は？", choices: ["正確な", "不規則な、予測できない", "電気の"], answer: 1, explain: "His behavior is erratic.（彼の行動は予測できない）" },
  { label: "【英語・大学受験】", q: "「（力・影響を）及ぼす、発揮する」を表す英単語は？", choices: ["exact", "exist", "exert"], answer: 2, explain: "The moon exerts a force on the sea.（月は海に力を及ぼす）。exert oneself は「努力する」" },
  { label: "【英語・大学受験】", q: "「壊れやすい、もろい」を表す英単語は？", choices: ["fragile", "frugal", "flexible"], answer: 0, explain: "Be careful with the fragile vase.（その壊れやすい花びんに気をつけて）" },
  { label: "【英語・大学受験】", q: "「hamper」の意味は？", choices: ["〜を手伝う", "〜を妨げる", "〜を速める"], answer: 1, explain: "Bad weather hampered the search.（悪天候が捜索を妨げた）" },
  { label: "【英語・大学受験】", q: "「hinge」の意味は？", choices: ["高さ", "ひも", "ちょうつがい、〜しだいである"], answer: 2, explain: "Everything hinges on his decision.（すべては彼の決断しだいだ）。hinge on 〜 の形で使う" },
  { label: "【英語・大学受験】", q: "「差し迫った」を表す英単語は？", choices: ["eminent", "immense", "imminent"], answer: 2, explain: "A storm is imminent.（嵐が迫っている）。eminent は「著名な」" },
  { label: "【英語・大学受験】", q: "「〜を妨げる」を表す英単語は？", choices: ["impose", "impede", "impart"], answer: 1, explain: "Fallen trees impeded traffic.（倒れた木が交通を妨げた）。名詞は impediment" },
  { label: "【英語・大学受験】", q: "「incessant」の意味は？", choices: ["絶え間ない", "最初の", "偶然の"], answer: 0, explain: "The incessant noise kept me awake.（絶え間ない騒音で眠れなかった）" },
  { label: "【英語・大学受験】", q: "「inflict」の意味は？", choices: ["（苦痛・損害を）与える", "〜に影響する", "〜を注入する"], answer: 0, explain: "The storm inflicted heavy damage on the town.（嵐は町に大きな被害を与えた）" },
  { label: "【英語・大学受験】", q: "「生まれつきの」を表す英単語は？", choices: ["innate", "inner", "innovative"], answer: 0, explain: "Children have an innate ability to learn language.（子どもには言語を学ぶ生まれつきの能力がある）" },
  { label: "【英語・大学受験】", q: "「〜に反する」を表す英語表現は？", choices: ["run across", "run counter to", "run into"], answer: 1, explain: "His actions run counter to his words.（彼の行動は言葉に反している）" },
  { label: "【英語・大学受験】", q: "「〜で我慢する、妥協する」を表す英語表現は？", choices: ["settle down", "settle in", "settle for"], answer: 2, explain: "I won't settle for second best.（2番手では満足しない）" },
  { label: "【英語・大学受験】", q: "「〜を引き受ける」を表す英語表現は？", choices: ["take off", "take on", "take in"], answer: 1, explain: "She took on extra work.（彼女は余分な仕事を引き受けた）。「〜を雇う」の意味でも使う" },
  { label: "【英語・大学受験】", q: "「〜を全滅させる、一掃する」を表す英語表現は？", choices: ["wipe off", "wipe out", "wear out"], answer: 1, explain: "The disease wiped out the whole village.（その病気は村全体を全滅させた）" },
  { label: "【英語・大学受験】", q: "「break down」の意味は？", choices: ["〜を借りる", "外へ出る", "故障する、崩れる"], answer: 2, explain: "My car broke down on the way.（途中で車が故障した）。名詞は breakdown" },
  { label: "【英語・大学受験】", q: "「at odds with 〜」の意味は？", choices: ["〜と仲良く", "〜と同じくらい", "〜と対立して、〜と食い違って"], answer: 2, explain: "His views are at odds with mine.（彼の見解は私のと食い違っている）" },
  { label: "【英語・大学受験】", q: "「by way of 〜」の意味は？", choices: ["〜の方法で戦って", "〜の道の端で", "〜経由で、〜として"], answer: 2, explain: "We flew to Rome by way of Paris.（私たちはパリ経由でローマへ飛んだ）" },
  { label: "【英語・大学受験】", q: "「in tandem with 〜」の意味は？", choices: ["〜と協力して、〜と連動して", "〜と別々に", "〜と競って"], answer: 0, explain: "The two groups worked in tandem.（2つのグループは連携して働いた）" },
  { label: "【英語・大学受験】", q: "「問題外で、不可能で」を表す英語表現は？", choices: ["out of the question", "out of the way", "out of the blue"], answer: 0, explain: "Going out in this storm is out of the question.（この嵐の中を出かけるのは問題外だ）" },
  { label: "【英語・大学受験】", q: "「beside the point」の意味は？", choices: ["的はずれで、要点からずれて", "要点を述べて", "点のそばで"], answer: 0, explain: "Your comment is beside the point.（あなたのコメントは的はずれだ）" },
  { label: "【英語・大学受験】", q: "「in due course」の意味は？", choices: ["やがて、しかるべき時に", "期限どおりに", "当然のこととして"], answer: 0, explain: "You will receive the result in due course.（結果はやがて届く）" },
  { label: "【英語・大学受験】", q: "「永久に、これを最後に」を表す英語表現は？", choices: ["for now", "for sure", "for good"], answer: 2, explain: "He left Japan for good.（彼は日本を永久に去った）" },
  { label: "【英語・大学受験】", q: "「in the nick of time」の意味は？", choices: ["ちょうどよい時刻に", "ずっと前に", "ぎりぎりで間に合って"], answer: 2, explain: "We arrived in the nick of time.（私たちはぎりぎりで到着した）" },
  { label: "【英語・大学受験】", q: "「to date」の意味は？", choices: ["今までのところ、現在まで", "日付に合わせて", "最新の"], answer: 0, explain: "To date, no one has solved this problem.（現在までに、誰もこの問題を解いていない）" },
  { label: "【英語・大学受験】", q: "「振り返ってみると」を表す英語表現は？", choices: ["in respect", "in prospect", "in retrospect"], answer: 2, explain: "In retrospect, it was a mistake.（振り返ってみると、それは間違いだった）" },
  { label: "【英語・大学受験】", q: "「back down」の意味は？", choices: ["引き下がる、主張を取り下げる", "〜を後ろへ下ろす", "〜をバックアップする"], answer: 0, explain: "He refused to back down.（彼は引き下がるのを拒んだ）" },
  { label: "【英語・大学受験】", q: "「dwell on 〜」の意味は？", choices: ["〜に住む", "〜をくよくよ考える、詳しく述べる", "〜に頼る"], answer: 1, explain: "Don't dwell on the past.（過去にくよくよするな）" },
  { label: "【英語・大学受験】", q: "「fend off 〜」の意味は？", choices: ["〜を引き寄せる", "〜をかわす、撃退する", "〜を支える"], answer: 1, explain: "He fended off the questions.（彼は質問をかわした）" },
  { label: "【英語・大学受験】", q: "「iron out 〜」の意味は？", choices: ["〜にアイロンをかける", "（問題・違いを）解決する、取り除く", "〜を強化する"], answer: 1, explain: "We need to iron out the details.（細部の問題を解消する必要がある）" },
  { label: "【英語・大学受験】", q: "「shy away from 〜」の意味は？", choices: ["〜に近づく", "〜を避ける、尻込みする", "〜を見つける"], answer: 1, explain: "He shies away from responsibility.（彼は責任を避ける）" },
  { label: "【英語・大学受験】", q: "「〜から生じる、〜に由来する」を表す英語表現は？", choices: ["step from", "stay from", "stem from"], answer: 2, explain: "The problem stems from a lack of communication.（その問題は意思疎通の不足から生じている）" },
  { label: "【英語・大学受験】", q: "「sum up 〜」の意味は？", choices: ["〜を持ち上げる", "〜を要約する", "〜を集める"], answer: 1, explain: "To sum up, we need more time.（要約すると、もっと時間が必要だ）" },
  { label: "【英語・大学受験】", q: "「play down 〜」の意味は？", choices: ["〜を軽く扱う、控えめに言う", "〜を演奏する", "〜を押し下げる"], answer: 0, explain: "The government played down the risk.（政府はそのリスクを軽く扱った）" },
  { label: "【英語・大学受験】", q: "「pull off 〜」の意味は？", choices: ["〜をやり遂げる", "〜を引き抜く", "〜を延期する"], answer: 0, explain: "Nobody thought he could pull it off.（彼にそれができるとは誰も思わなかった）" },
  { label: "【英語・大学受験】", q: "「own up to 〜」の意味は？", choices: ["〜を所有する", "〜を（素直に）認める", "〜を上回る"], answer: 1, explain: "He owned up to his mistake.（彼は自分の間違いを素直に認めた）" },
  { label: "【英語・大学受験】", q: "Hard ( ) I tried, I couldn't open the door. 空所に入る語（句）は？", choices: ["as", "so", "than"], answer: 0, explain: "〈形容詞・副詞 ＋ as ＋ 主語 ＋ 動詞〉は譲歩で「〜だけれども」。Hard as I tried は「一生懸命やったけれど」" },
  { label: "【英語・大学受験】", q: "Not only did he lose his job, but he ( ) lost his house. 空所に入る語（句）は？", choices: ["also", "either", "neither"], answer: 0, explain: "Not only A but (also) B の B 側。Not only が文頭にきて倒置（did he lose）になっても、but は通常の語順で続ける" },
  { label: "【英語・大学受験】", q: "It is no wonder ( ) he failed. 空所に入る語（句）は？", choices: ["what", "how", "that"], answer: 2, explain: "It is no wonder that 〜 は「〜も不思議ではない」。that 以下は真主語" },
  { label: "【英語・大学受験】", q: "He, as well as his brothers, ( ) a doctor. 空所に入る語（句）は？", choices: ["are", "is", "were"], answer: 1, explain: "A as well as B のときの動詞は A に合わせる。A（He）が三人称単数なので is" },
  { label: "【英語・大学受験】", q: "Everyone ( ) the rule. 空所に入る語（句）は？", choices: ["knows", "know", "knowing"], answer: 0, explain: "everyone は単数扱いなので、動詞には -s がつく" },
  { label: "【英語・大学受験】", q: "Economics ( ) a difficult subject. 空所に入る語（句）は？", choices: ["are", "were", "is"], answer: 2, explain: "economics / mathematics / physics などの学問名は、-s で終わっても単数扱い" },
  { label: "【英語・大学受験】", q: "The police ( ) looking for him. 空所に入る語（句）は？", choices: ["are", "is", "was"], answer: 0, explain: "the police は複数扱い（警察官たち）。police officer は単数" },
  { label: "【英語・大学受験】", q: "Ten dollars ( ) not enough for a good meal. 空所に入る語（句）は？", choices: ["are", "were", "is"], answer: 2, explain: "金額・時間・距離を「ひとまとまり」として見るときは、単数扱いにする" },
  { label: "【英語・大学受験】", q: "He objected ( ) the plan. 空所に入る語（句）は？", choices: ["against", "for", "to"], answer: 2, explain: "object to 〜 は「〜に反対する」。to の後ろは名詞か動名詞" },
  { label: "【英語・大学受験】", q: "So great ( ) his joy that he couldn't speak. 空所に入る語（句）は？", choices: ["is", "were", "was"], answer: 2, explain: "So 〜 が文頭にくると、倒置が起こる。So ＋ 形容詞 ＋ be動詞 ＋ 主語 ＋ that 〜" },
  { label: "【英語・大学受験】", q: "( ) is important is to try your best. 空所に入る語（句）は？", choices: ["That", "Which", "What"], answer: 2, explain: "What 〜 は「〜すること（もの）」の意味の名詞節をつくる。文の主語になれる" },
  { label: "【英語・大学受験】", q: "She spoke so quickly ( ) I couldn't follow. 空所に入る語（句）は？", choices: ["as", "that", "than"], answer: 1, explain: "so ＋ 副詞 ＋ that 〜 は「とても…なので〜」" },
  { label: "【英語・大学受験】", q: "He is not ( ) a fool as to believe that. 空所に入る語（句）は？", choices: ["so", "such", "too"], answer: 1, explain: "not such a 〜 as to ... は「…するほど〜ではない」。such a ＋ 名詞 の語順に注意" },
  { label: "【英語・大学受験】", q: "This is the best movie ( ) I have ever seen. 空所に入る語（句）は？", choices: ["which", "what", "that"], answer: 2, explain: "先行詞に最上級（the best）がつくときは、関係代名詞は that が好まれる" },
  { label: "【英語・大学受験】", q: "Be careful not to ( ) the bag open. 空所に入る語（句）は？", choices: ["let", "make", "leave"], answer: 2, explain: "leave ＋ O ＋ C は「OをCのままにしておく」。（かばんを開けたままにしないように）" },












  






]);


